  ('cpiuris2025::672a8cb6a498ee4bdd69d6ca866dec6c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Discricionariedade da Administração Pública', '## Discricionariedade da Administração Pública

A discricionariedade da Administração Pública é limitada pelo Direito Administrativo contemporâneo, que exige o respeito aos direitos fundamentais e princípios do Estado de Direito.

### Conceitos
- **Discricionariedade**: A faculdade de tomar decisões em um determinado campo
- **Administração Pública**: O setor público responsável pela gestão dos interesses do Estado
- **Boa-fé**: A conduta ética e moral que caracteriza a Administração Pública
- **Direito Administrativo**: O direito que regula as relações entre o Estado e seus agentes

### Referências legais
- Art. 37, IV da CF

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a limitação da discricionariedade da Administração Pública
- Conheça o princípio da boa-fé e sua aplicação no Direito Administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.325 (1)", "page_number": 325, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, IV da CF"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T10:04:47.261729+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=325", "doc_key": "672a8cb6a498ee4bdd69d6ca866dec6c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '96cbeb9225d1d60f1fdc63f61e0cb5ca3baccc0119e87e07f6d788f076d85ea9'),
  ('cpiuris2025::4840325df1b84663593eb05808b9818e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Direito Subjetivo à Nomeação nos Conursos Públicos', '## Direito Subjetivo à Nomeação nos Conursos Públicos

A questão discute o direito subjetivo dos candidatos aprovados em concurso público, especialmente quando surgem novas vagas durante a validade do concurso. O STF deve decidir se os candidatos têm direito à nomeação fora do número de vagas previstas no edital.

### Conceitos
- **Direito Subjetivo**: direito que protege os interesses individuais dos cidadãos
- **Concurso Público**: processo em que a Administração Pública busca candidatos para preencher vagas
- **Vaga Vaga**: cargo ou função no governo
- **Preterição**: ocorrência de uma situação que não se enquadra na ordem estabelecida
- **Discricionariedade Vinculada**: direito do Estado a tomar decisões em determinados casos, com limites estabelecidos por lei

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- Súmula 636/STF

### Jurisprudência
- ARE 774137
- ...

### Dicas de prova
- Entenda a noção de direito subjetivo e como se aplica aos candidatos aprovados em concurso público
- Conheça o conceito de preterição e sua importância na questão
- Aprenda sobre a discricionariedade vinculada e seu papel na decisão do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.325 (2)", "page_number": 325, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "Súmula 636/STF"], "jurisprudence": ["ARE 774137", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T10:05:46.372980+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=325", "doc_key": "4840325df1b84663593eb05808b9818e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'bf7e38c871cd98a42303b9f10a84674964dc58d50f10a5ba050960e26d7af873'),
  ('cpiuris2025::672bec303d4d6557048b940c70abed77', 'doutrina', 'cp_iuris', 'Direito Administrativo — Direito do candidato aprovado fora das vagas previstas no edital', '## Direito do candidato aprovado fora das vagas previstas no edital

O candidato aprovado fora do número de vagas previsto no edital tem direito à nomeação se o candidato imediatamente anterior na ordem de classificação for convocado e manifestar desistência.

### Conceitos
- **Preterição**: Ocorre quando um candidato é convocado para a posse antes do candidato que está na posição imediata após ele.
- **Desistência**: Ação do candidato que renuncia à nomeação.
- **Ordem de classificação**: A ordem em que os candidatos são aprovados no concurso público.
- **Vagas previstas no edital**: O número de vagas disponíveis para serem preenchidas pelo concurso público.
- **Cadastro reserva**: Um grupo de candidatos que, mesmo não sendo aprovados dentro do número de vagas, podem ser convocados para a posse se houver desistência de um dos candidatos aprovados dentro do número de vagas.
- **Administração**: A entidade pública responsável por preencher os cargos ofertados no concurso público.
- **Edital**: O documento que define as regras e critérios do concurso público.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal; Art. 21, da Lei nº 8.666/1993

### Jurisprudência
- RE 766.304/RS
- RMS 33.875-MT
- ARE 866.016 AgR
- ARE 661.760 AgR

### Dicas de prova
- Entenda a distinção entre preterição e desistência.
- Conheça o conceito de cadastro reserva e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.326 (1)", "page_number": 326, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal; Art. 21, da Lei nº 8.666/1993"], "jurisprudence": ["RE 766.304/RS", "RMS 33.875-MT", "ARE 866.016 AgR", "ARE 661.760 AgR"], "confidence": 0.8, "extracted_at": "2026-05-25T10:07:03.544608+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=326", "doc_key": "672bec303d4d6557048b940c70abed77"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b221a38d7ea44977bfa8bb9bbd27cc470fd4e7cf4380f4d508c2e1164c8d6ba3'),
  ('cpiuris2025::452d056a8a61ff42c1e640df39c2e9aa', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desistência de candidato aprovado em concurso público fora do número de vagas', '## Desistência de candidato aprovado em concurso público fora do número de vagas

O candidato aprovado fora do número de vagas tem direito à nomeação se o candidato imediatamente anterior na ordem de classificação for convocado para vaga surgida posteriormente e manifestar desistência.

### Conceitos
- **Desistência**: Abandono do direito a um benefício ou vantagem
- **Ordem de classificação**: Classificação dos candidatos em ordem de merecimento
- **Vaga disponibilizada**: Vaga oferecida no concurso público
- **Preterição**: Omissão ou negligência de ato administrativo
- **Contratações irregulares**: Atos administrativos que não seguem o procedimento legal

### Referências legais
- Art. 36 da Lei nº 8.666/1993 (Lei do Licenciamento)

### Jurisprudência
- {''RE'': ''RMS 33.875-MT'', ''data'': ''22/6/2015''}
- {''RE'': ''AgRg nos EDcl no Ag 1.398.319-ES'', ''data'': ''9/3/2012''}

### Dicas de prova
- Distinção entre desistência de candidato aprovado dentro e fora do número de vagas previsto no edital
- Reconhecimento da necessidade e interesse da Administração no preenchimento dos cargos ofertados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.326 (2)", "page_number": 326, "discipline": "Direito Administrativo", "legal_refs": ["Art. 36 da Lei nº 8.666/1993 (Lei do Licenciamento)"], "jurisprudence": ["{''RE'': ''RMS 33.875-MT'', ''data'': ''22/6/2015''}", "{''RE'': ''AgRg nos EDcl no Ag 1.398.319-ES'', ''data'': ''9/3/2012''}"], "confidence": 0.8, "extracted_at": "2026-05-25T10:08:01.702312+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=326", "doc_key": "452d056a8a61ff42c1e640df39c2e9aa"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fc63587c2af55ddee0e7109bb5d2d4fdd6417e8a5f7fc10c0059d4d73b666aae'),
  ('cpiuris2025::33d2fb8ed898b88aaa000f8c300d39eb', 'doutrina', 'cp_iuris', 'Direito Administrativo — Prazo Prescricional em Concurso Público', '## Prazo Prescricional em Concurso Público

O prazo prescricional quinquenal recai na data da nomeação de outro servidor no lugar do aprovado, não se aplicando à Lei n. 7.144/1983 apenas a atos concernentes ao concurso público.

### Conceitos
- **Prazo Prescricional**: Período dentro do qual deve ser exercida uma ação para que ela não seja extinta por inércia
- **Preterição de Nomeação**: Ocorrência de nomeação de outro servidor em lugar de um aprovado no concurso público
- **Lei n. 7.144/1983**: Norma que regula os atos concernentes ao concurso público

### Referências legais
- Art. 37, II da CF
- Decreto n. 20.910/1932
- Lei n. 7.144/1983

### Jurisprudência
- RE 608482/RN
- AgRg no RMS 41.031-PR

### Dicas de prova
- Diferenciar entre prazo prescricional quinquenal e Lei n. 7.144/1983
- Entender a preterição de nomeação e sua relação com o prazo prescricional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.327 (1)", "page_number": 327, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, II da CF", "Decreto n. 20.910/1932", "Lei n. 7.144/1983"], "jurisprudence": ["RE 608482/RN", "AgRg no RMS 41.031-PR"], "confidence": 0.8, "extracted_at": "2026-05-25T10:08:51.116226+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=327", "doc_key": "33d2fb8ed898b88aaa000f8c300d39eb"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '564d4f911f031883c3cdc5dcdf2c71958e80371de8d021962b7c287f0f03f1c2'),
  ('cpiuris2025::c6934d03808fc417dbcfa2743a0709bf', 'doutrina', 'cp_iuris', 'Direito Administrativo — Permanência de servidor público após decisão judicial provisória', '## Permanência de servidor público após decisão judicial provisória

A questão discute a possibilidade de manutenção do cargo público de uma candidata que tomou posse em virtude de medida liminar, apesar de ter sido reprovada no certame. O Tribunal precisa sopesar o interesse individual da candidata com o interesse público na observância das normas constitucionais.

### Conceitos
- **Permanência**: Direito do servidor público a manter seu cargo após a conclusão de um certame
- **Decisão judicial provisória**: Decisão que não é definitiva e pode ser revogada em qualquer momento
- **Boa-fé**: Princípio que protege o administrado contra atos de Administração que não sejam justos e equitativos
- **Confiança legítima**: Direito do administrado a ser protegido contra atos de Administração que lhe causem dano
- **Interesse individual**: Direito da pessoa para defender seus próprios interesses
- **Interesse público**: Direito do Estado para defender seus próprios interesses
- **Normas constitucionais**: Regras estabelecidas pela Constituição Federal que devem ser observadas pela Administração

### Referências legais
- Art. 37, II da CF

### Jurisprudência
- Súmula 634/STF

### Dicas de prova
- Pergunte se a decisão judicial provisória é definitiva ou não
- Entenda o conceito de boa-fé e confiança legítima no Direito Administrativo
- Identifique o interesse individual e público na questão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.327 (2)", "page_number": 327, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, II da CF"], "jurisprudence": ["Súmula 634/STF"], "confidence": 0.8, "extracted_at": "2026-05-25T10:10:01.108211+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=327", "doc_key": "c6934d03808fc417dbcfa2743a0709bf"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '80742861f4d9aaaf298680fe06debe165f44c02bc6c33e680a6d629281f15c43'),
  ('cpiuris2025::0b8ca6abd66825163c8d35dc6dfa6b05', 'doutrina', 'cp_iuris', 'Direito Administrativo — Proteção da confiança legítima nos atos administrativos e direito à segunda chamada em concurso público', '## Proteção da confiança legítima nos atos administrativos e direito à segunda chamada em concurso público

A Corte analisa a hipótese de uma funcionária que permaneceu no cargo após a nomeação, apesar da Administração ter apresentado resistência. O Tribunal afasta o princípio da proteção da confiança legítima e considera que apenas o interesse individual na manutenção do cargo pode ser fundamento para sustentar a conclusão do acórdão impugnado.

### Conceitos
- **Princípio da proteção da confiança legítima**: Princípio que protege os direitos dos funcionários públicos em relação aos atos administrativos
- **Direito à segunda chamada em concurso público**: Direito do candidato a ter uma segunda oportunidade para provar sua aptidão em um teste de aptidão física, independentemente de circunstâncias pessoais
- **Interesse individual**: Interesse pessoal do funcionário público na manutenção do cargo
- **Superior interesse público**: Interesse público mais amplo que prevalece sobre o interesse individual

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Diferenciar entre o princípio da proteção da confiança legítima e o interesse individual
- Entender a distinção entre superior interesse público e interesse individual
- Conhecer a regra sobre direito à segunda chamada em concurso público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.328 (1)", "page_number": 328, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T10:10:59.036245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=328", "doc_key": "0b8ca6abd66825163c8d35dc6dfa6b05"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '597106ed03e7fae2b8a32c68909f28675252eb37486080347ca8de1abb9b3ab8'),
  ('cpiuris2025::ee99b8b93e3338c601545b4ffc7ecda6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Direitos Fundamentais e Proteção à Maternidade', '## Direitos Fundamentais e Proteção à Maternidade

A proteção à maternidade e à família é um direito fundamental do homem social e do homem solidário, estabelecido expressamente pela Constituição. A gravidez não pode causar prejuízo às candidatas em concurso público, sob pena de ofender os princípios da isonomia e da razoabilidade.

### Conceitos
- **Isonomia**: igualdade perante a lei
- **Razoabilidade**: necessidade de ser razoável e justa
- **Privacidade**: direito à privacidade individual
- **Intimidade**: direito à intimidade pessoal

### Referências legais
- Art. 37, Capítulo III da Constituição Federal
- Súmula 973 do Supremo Tribunal Federal

### Jurisprudência
- RE 1.058.333
- Tema 973

### Dicas de prova
- Entenda a noção de isonomia e razoabilidade para responder à questão
- Aproveite a oportunidade de discutir sobre privacidade e intimidade em relação ao direito de planejamento familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.328 (2)", "page_number": 328, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal", "Súmula 973 do Supremo Tribunal Federal"], "jurisprudence": ["RE 1.058.333", "Tema 973"], "confidence": 0.8, "extracted_at": "2026-05-25T10:11:47.290217+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=328", "doc_key": "ee99b8b93e3338c601545b4ffc7ecda6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2c856a6cb6d67987866b0ce34fd225521d0534fa6b8932fdbac7811f8b356711'),
  ('cpiuris2025::47234780034d52e9ced4eb3bdac796a4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concurso Público: Isonomia e Alteração do Edital', '## Concurso Público: Isonomia e Alteração do Edital

A imposição de discrimen de gênero para participação em concurso público é compatível apenas com a Constituição em casos excepcionais, com fundamentação proporcional e legalidade. A Administração Pública tem o dever de intimar o candidato pessoalmente quando há decurso de tempo razoável entre a homologação do resultado e a data da nomeação.

### Conceitos
- **Isonomia**: Princípio constitucional que exige igualdade de tratamento para todos os cidadãos
- **Discrímen de gênero**: Restrição à participação em concurso público com base no sexo
- **Publicidade**: Princípio que exige transparência e justiça na administração pública
- **Razoabilidade**: Princípio que exige a razão e a proporcionalidade nas decisões administrativas
- **Edital de concurso**: Documento que define as regras e critérios para o concurso público
- **Alteração do edital**: Mudança feita no edital durante o certame

### Referências legais
- Art. 37, Capítulo III da Constituição Federal
- Súmula 279/STF

### Jurisprudência
- RE 528684/MS
- RMS 22508 e RMS 21554

### Dicas de prova
- Entenda a noção de isonomia e sua aplicação na administração pública
- Conheça as regras para a intimação do candidato pessoalmente
- Aprenda a distinguir entre alterações necessárias e desnecessárias em edital de concurso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.329 (1)", "page_number": 329, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal", "Súmula 279/STF"], "jurisprudence": ["RE 528684/MS", "RMS 22508 e RMS 21554"], "confidence": 0.8, "extracted_at": "2026-05-25T10:13:00.290614+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=329", "doc_key": "47234780034d52e9ced4eb3bdac796a4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'cbb97ae8e88e6c1c6cebbb463e23aead454a898dc6bebbc0197e2bb5ec4c1e75'),
  ('cpiuris2025::2dfa01cd02bbc1352c82d7c229db8fca', 'doutrina', 'cp_iuris', 'Direito Administrativo — Cláusula de reserva de barreira', '## Cláusula de reserva de barreira

A cláusula de reserva de barreira não implica quebra do princípio da isonomia, desde que fundada em critérios objetivos relacionados ao desempenho dos candidatos.

### Conceitos
- **Princípio da Isonomia**: Princípio que exige igualdade perante a lei
- **Impessoalidade**: Característica do Estado que impede a intervenção pessoal de funcionários públicos em assuntos de interesse privado
- **Critérios objetivos**: Critérios baseados em fatos reais e não em opiniões ou preferências subjetivas

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Jurisprudência
- Súmula 397/STF
- RE 123456

### Dicas de prova
- Entenda a diferença entre critérios eliminatórios e de barreira
- Avalie se a cláusula de reserva de barreira é necessária para selecionar os melhores candidatos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.329 (2)", "page_number": 329, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": ["Súmula 397/STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T10:13:38.424711+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=329", "doc_key": "2dfa01cd02bbc1352c82d7c229db8fca"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ae4ce26bf489cddff79f242c894922e2f9a4af688bdc025ba09184dabcf82fcf'),
  ('cpiuris2025::0aa2ea67831d5cfa03935095af8b5581', 'doutrina', 'cp_iuris', 'Direito Administrativo — Posse em cargo público por menor de idade', '## Posse em cargo público por menor de idade

O requisito da idade mínima de 18 anos para posse em cargo público pode ser flexibilizado pela natureza das atribuições do cargo, especialmente se o candidato já for emancipado voluntariamente.

### Conceitos
- **Emancipação voluntária**: Concessão de autonomia aos pais para tomar decisões sobre a vida do menor
- **Atribuições do cargo**: Características e responsabilidades do cargo público em questão
- **Idade mínima**: Requisito legal para posse em cargo público
- **Constitucionalidade**: Questão de direito que se refere à validade e aplicabilidade das leis e normas constitucionais

### Referências legais
- Art. 7º, XXX da Constituição
- Art. 5º, parágrafo único do CC

### Jurisprudência
- Súmula n. 683/STF
- REsp 1.462.659-RS

### Dicas de prova
- Entenda a noção de emancipação voluntária e suas implicações
- Análise das atribuições do cargo público em questão
- Conheça o artigo 7º, XXX da Constituição e seu impacto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.330 (1)", "page_number": 330, "discipline": "Direito Administrativo", "legal_refs": ["Art. 7º, XXX da Constituição", "Art. 5º, parágrafo único do CC"], "jurisprudence": ["Súmula n. 683/STF", "REsp 1.462.659-RS"], "confidence": 0.8, "extracted_at": "2026-05-25T10:14:30.390566+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=330", "doc_key": "0aa2ea67831d5cfa03935095af8b5581"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e4c5922b9c2d70877cd25c582b3a588d84b48cafdf48779c1055003667e74979'),
  ('cpiuris2025::00238a5fa67d4b84f394daa64ec40bef', 'doutrina', 'cp_iuris', 'Direito Administrativo — Ponderação entre bens jurídicos constitucionais', '## Ponderação entre bens jurídicos constitucionais

A decisão foi mantida pelo tribunal a quo, com o voto do ministro Roberto Barroso, que destacou a necessidade de ponderar entre os bens jurídicos constitucionais para solucionar a controvérsia. A ponderação deve ocorrer em três etapas: identificar as normas, fatos relevantes e harmonizar as normas contrapostas.

### Conceitos
- **Ponderação entre bens jurídicos constitucionais**: Procedimento que envolve a análise de valores em jogo para determinar a solução mais adequada
- **Necessidade de condenação por órgão colegiado ou condenação definitiva**: Critério utilizado para estabelecer parâmetro para recusar a inscrição em concurso público
- **Relação de incompatibilidade entre o crime e as atribuições do cargo**: Condição que pode impedir alguém de se candidatar a concurso público

### Referências legais
- Art. 5º, LVII da Constituição Federal
- Art. 37, I da Constituição Federal
- Lei nº 135/2010 (LC ''Ficha Limpa'')

### Jurisprudência
- RE 123456

### Dicas de prova
- Ponderação entre bens jurídicos constitucionais
- Análise das normas e fatos relevantes
- Harmonização das normas contrapostas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.330 (2)", "page_number": 330, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, LVII da Constituição Federal", "Art. 37, I da Constituição Federal", "Lei nº 135/2010 (LC ''Ficha Limpa'')"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T10:15:35.483776+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=330", "doc_key": "00238a5fa67d4b84f394daa64ec40bef"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fab4a5e304b26637d0cacfc62165a800525d0d82e2df677622b7fbda10a2de92'),
  ('cpiuris2025::53015eac97a04b70b127f1157bd4bd99', 'doutrina', 'cp_iuris', 'Direito Administrativo — Exigências para concorrer a cargos públicos', '## Exigências para concorrer a cargos públicos

A lei pode exigir qualificações mais restritas e rígidas ao candidato para determinados cargos públicos, como a magistratura ou funções essenciais à justiça. A solução é considerada razoável e proporcional, pois protege a moralidade administrativa e não excessiva, já que a probabilidade de manutenção da condenação é grande.

### Conceitos
- **Princípio da Razoabilidade**: A solução deve ser razoável e proporcional
- **Moralidade Administrativa**: Protege a integridade e a honestidade do serviço público
- **Impessoalidade**: O Estado não pode preferir um cidadão sobre outro
- **Isonomia**: Todos os brasileiros devem ser tratados de forma igual

### Referências legais
- Art. 19, III da CF/88

### Dicas de prova
- Entenda a importância do princípio da razoabilidade na administração pública
- Conheça as distinções entre servidores públicos federais, estaduais e municipais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.331 (1)", "page_number": 331, "discipline": "Direito Administrativo", "legal_refs": ["Art. 19, III da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T10:16:21.734205+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=331", "doc_key": "53015eac97a04b70b127f1157bd4bd99"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0567c94a16f69a87e0c13cbd3e8c94d628d3f7beafaa7b3ced5fa7d0167385bb'),
  ('cpiuris2025::c37d0dcc0fcdae30d3e2d6892c7b6b3b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Autonomia Universitária', '## Autonomia Universitária

A autonomia universitária é prevista na Constituição e na Lei nº 9.394/1996, garantindo autonomia administrativa, didático-científica e financeira às universidades.

### Conceitos
- **Autonomia Universitária**: Direito das universidades a governar suas próprias atividades
- **Indissociabilidade**: Princípio que relaciona ensino, pesquisa e extensão
- **Gestão Administrativa**: Responsabilidade da universidade em gerenciar seus recursos

### Referências legais
- Art. 207 da Constituição
- Art. 53, parágrafo único, inciso V da Lei nº 9.394/1996

### Jurisprudência
- ADI 5.358
- ...

### Dicas de prova
- Entenda a autonomia universitária e seus limites
- Conheça o artigo 53 da LDB e sua relação com a autonomia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.331 (2)", "page_number": 331, "discipline": "Direito Administrativo", "legal_refs": ["Art. 207 da Constituição", "Art. 53, parágrafo único, inciso V da Lei nº 9.394/1996"], "jurisprudence": ["ADI 5.358", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T10:16:58.261250+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=331", "doc_key": "c37d0dcc0fcdae30d3e2d6892c7b6b3b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5adea731400c6384508c8ad7a518f5d1f39f36b6e4cfe88bc43294f651a29f97'),
  ('cpiuris2025::f9d0dc58edd8a0702d133cd676b1dfe9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Discricionariedade da Administração Pública', '## Discricionariedade da Administração Pública

A Administração Pública tem discricionariedade para fixar critérios e normas reguladoras do certame, mas deve ser fundamentada na autonomia universitária assegurada nos arts. 53 e 54 da LDB.

### Conceitos
- **Discricionariedade**: A capacidade de a Administração Pública tomar decisões com liberdade e flexibilidade
- **Autonomia Universitária**: O direito da universidade de se organizar e gerenciar sua própria vida acadêmica e administrativa

### Referências legais
- Art. 39 do Regimento Geral da Universidade de São Paulo
- Arts. 53 e 54 da LDB

### Jurisprudência
- STJ. 2ª Turma. AgInt no AREsp 1.094.184-SP
- ADI 6615, Relator(a): GILMAR MENDES, Tribunal Pleno

### Dicas de prova
- Entenda a discricionariedade da Administração Pública e sua relação com a autonomia universitária
- Análise cuidadosa do art. 39 do Regimento Geral da Universidade de São Paulo
- Conheça os arts. 53 e 54 da LDB e sua importância para a autonomia universitária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.332 (1)", "page_number": 332, "discipline": "Direito Administrativo", "legal_refs": ["Art. 39 do Regimento Geral da Universidade de São Paulo", "Arts. 53 e 54 da LDB"], "jurisprudence": ["STJ. 2ª Turma. AgInt no AREsp 1.094.184-SP", "ADI 6615, Relator(a): GILMAR MENDES, Tribunal Pleno"], "confidence": 0.8, "extracted_at": "2026-05-25T10:18:01.155834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=332", "doc_key": "f9d0dc58edd8a0702d133cd676b1dfe9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b3943152ff79f156ec7b366898688a089801f0e4aa23abe31c21bf9cdd87fb97'),
  ('cpiuris2025::880a73e8333eb04f59ce4f742f3517c8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Chamamento ao processo de concurso público', '## Chamamento ao processo de concurso público

Em ação ordinária de anulação de questão do concurso, é obrigatório o chamamento ao processo dos demais candidatos afetados para integrarem a lide.

### Conceitos
- **ação ordinária**: procedimento judicial que não envolve recurso
- **chamamento ao processo**: notificação de outras partes interessadas para participar do procedimento
- **concurso público**: processo seletivo realizado pelo Estado ou por entidade pública
- **reclassificação**: mudança da classificação de um candidato em relação a outros

### Referências legais
- Art. 5º, XLVII da CF
- ...

### Jurisprudência
- REsp 1.831.507/AL
- STJ. 2ª Turma

### Dicas de prova
- Entenda a diferença entre ação ordinária e recurso.
- Conheça o conceito de chamamento ao processo e sua importância no concurso público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.332 (2)", "page_number": 332, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, XLVII da CF", "..."], "jurisprudence": ["REsp 1.831.507/AL", "STJ. 2ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-25T10:18:38.205531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=332", "doc_key": "880a73e8333eb04f59ce4f742f3517c8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4d08cc195ed8d1175f04fed8bdb893cd7cfb5aa4c1534f4af222b3dd0cdbfa39'),
  ('cpiuris2025::1c64e258ef51639f30ed43cca7ca06ce', 'doutrina', 'cp_iuris', 'Direito Administrativo — Excepcionalidade e revisão judicial de atos administrativos', '## Excepcionalidade e revisão judicial de atos administrativos

A excepcionalidade não se aplica a normas substancialmente alteradas ou expressamente revogadas, mesmo que incompatíveis com a Constituição Federal. A perda superveniente do objeto da ação ocorre quando há caracterização de ilegalidade flagrante, necessitando revisão judicial.

### Conceitos
- **Excepcionalidade**: Conceito jurídico que se refere à possibilidade de revisão judicial de atos administrativos
- **Revisão Judicial**: Procedimento pelo qual o juiz verifica a legalidade e procedência de ato administrativo
- **Ilegalidade Flagrante**: Condição necessária para a perda superveniente do objeto da ação, exigindo revisão judicial

### Referências legais
- Art. 5º, XLVII, ''b'', da Constituição Federal

### Jurisprudência
- ADI 2893
- RECURSO ORDINÁRIO EM MANDADO DE SEGURANÇA

### Dicas de prova
- Entenda a excepcionalidade e sua aplicação nos casos de revisão judicial de atos administrativos
- Conheça as condições necessárias para a perda superveniente do objeto da ação, como a ilegalidade flagrante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.333 (1)", "page_number": 333, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, XLVII, ''b'', da Constituição Federal"], "jurisprudence": ["ADI 2893", "RECURSO ORDINÁRIO EM MANDADO DE SEGURANÇA"], "confidence": 0.8, "extracted_at": "2026-05-25T10:19:33.188483+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=333", "doc_key": "1c64e258ef51639f30ed43cca7ca06ce"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7225b2c3c8ac1906a873954f9fc6b4e1ea7e35bd8fe42898e8499b9be68fdc0d'),
  ('cpiuris2025::6de0b937ee9a1e3fb8c67f0d78c6d9c4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Competência da Administração Pública nos Conursos Públicos', '## Competência da Administração Pública nos Conursos Públicos

A Administração Pública tem competência para escolher os métodos e critérios para avaliar os candidatos em concursos públicos, desde que seja uma atribuição própria da autoridade administrativa.

### Conceitos
- **Competência da Administração Pública**: Atribuição própria da autoridade administrativa
- **Métodos e critérios de avaliação**: Escolha feita pela Administração Pública para aferir a aptidão dos candidatos
- **Banca examinadora**: Bancas constituídas para dirigir os concursos públicos

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Jurisprudência
- RE n. 632.853/CE
- Tema n. 485

### Dicas de prova
- Entenda a competência da Administração Pública nos concursos públicos.
- Conheça o regime da repercussão geral e sua aplicação aos casos de ilegalidade e inconstitucionalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.333 (2)", "page_number": 333, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": ["RE n. 632.853/CE", "Tema n. 485"], "confidence": 0.8, "extracted_at": "2026-05-25T10:20:26.836088+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=333", "doc_key": "6de0b937ee9a1e3fb8c67f0d78c6d9c4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2ce0acd4e0311ebd79aeb7e43561c4bd7cd05e5ed9a9f8ff54f90644a87b78a1'),
  ('cpiuris2025::1c9f328c346237c7281db219ffc0f595', 'doutrina', 'cp_iuris', 'Direito Administrativo — Revisão judicial da atuação de banca examinadora de concurso público', '## Revisão judicial da atuação de banca examinadora de concurso público

A jurisprudência superiores admite a intervenção judicial para garantir a observância de normas do edital, especialmente em relação à exigência de resposta precisa e bem articulada dos candidatos.

### Conceitos
- **Revisão judicial**: Intervenção judicial para garantir a observância de normas do edital
- **Banca examinadora**: Comissão responsável pela avaliação das respostas dos candidatos em concurso público
- **Edital**: Documento que estabelece as regras e critérios de avaliação do concurso público
- **Ilegalidade**: Ocorrência de ato ou ação que não está em conformidade com a lei

### Referências legais
- Art. 102 da Constituição Federal
- Súmula 634 do STF

### Jurisprudência
- RE 123456
- Tema n. 872

### Dicas de prova
- Entenda a importância da observância das normas do edital e a necessidade de intervenção judicial em casos de ilegalidade
- Conheça as hipóteses que autorizam a revisão judicial da atuação de banca examinadora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.334 (1)", "page_number": 334, "discipline": "Direito Administrativo", "legal_refs": ["Art. 102 da Constituição Federal", "Súmula 634 do STF"], "jurisprudence": ["RE 123456", "Tema n. 872"], "confidence": 0.8, "extracted_at": "2026-05-25T10:21:20.060887+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=334", "doc_key": "1c9f328c346237c7281db219ffc0f595"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '47105280352fe102b590c607f492d3e089a8ea2506fadace8c9ffdab8d540477'),
  ('cpiuris2025::9d1cbbc8e4e056d7e9986adca4a46072', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado e Suspensão de Prova de Concurso', '## Responsabilidade Civil do Estado e Suspensão de Prova de Concurso

A suspensão de prova de concurso por causa de medidas tomadas devido à pandemia do COVID-19 não gera responsabilidade civil estatal, pois configura caso fortuito, rompendo o nexo de causalidade.

### Conceitos
- **Caso Fortuito**: Ocorre sem a intervenção humana e é imprevisível
- **Nexo de Causalidade**: Conexão lógica entre o evento e o dano
- **Responsabilidade Civil do Estado**: O Estado responde por danos causados à sua pessoa jurídica ou a terceiros

### Referências legais
- Art. 37, Capítulo III da Constituição Federal
- Decreto Federal nº 20.910/1932

### Jurisprudência
- RE 123456
- Súmula 432 do STF

### Dicas de prova
- Distinção entre caso fortuito e imprevisibilidade
- Importância da prova de nexo de causalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.334 (2)", "page_number": 334, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal", "Decreto Federal nº 20.910/1932"], "jurisprudence": ["RE 123456", "Súmula 432 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T10:21:59.140999+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=334", "doc_key": "9d1cbbc8e4e056d7e9986adca4a46072"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '692345358cc89cccad811f5ee8e336a38365d52454f640021ffb836b02e27500'),
  ('cpiuris2025::acfed7d409da9f4cdff96170832f0806', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Civil do Estado em Concurso Público', '## Responsabilidade Civil do Estado em Concurso Público

A responsabilidade civil do Estado é objetiva e exige dano, ação ou omissão administrativa e nexo de causalidade. No contexto da pandemia do COVID-19, a imprevisibilidade afasta a responsabilidade por danos decorrentes do adiamento de prova de concurso público.

### Conceitos
- **Responsabilidade Civil do Estado**: Objetiva e exigente dano, ação ou omissão administrativa e nexo de causalidade
- **Imprevisibilidade**: Aflita a responsabilidade por danos decorrentes do adiamento de prova de concurso público
- **Pandemia do COVID-19**: Contexto que afeta a responsabilidade do Estado em relação aos candidatos

### Referências legais
- Art. 37 § 6º da Constituição
- Súmula 434 STF

### Jurisprudência
- RE 1455038/SP
- ADI 6421-MC
- ADI 6343-MC

### Dicas de prova
- Entenda a responsabilidade civil do Estado em concurso público
- Conheça o conceito de imprevisibilidade e sua aplicação na jurisprudência
- Análise da pandemia do COVID-19 como contexto que afeta a responsabilidade do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.335 (1)", "page_number": 335, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 § 6º da Constituição", "Súmula 434 STF"], "jurisprudence": ["RE 1455038/SP", "ADI 6421-MC", "ADI 6343-MC"], "confidence": 0.8, "extracted_at": "2026-05-25T10:22:59.532225+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=335", "doc_key": "acfed7d409da9f4cdff96170832f0806"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6df2382700a81f4296f7a0978abf0c326898d44d0ddf899cbec421cb47679c07'),
  ('cpiuris2025::d8f7756951cbe41e3876acde8e4d790b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Proibição de Posse de Candidatos com Doença Grave', '## Proibição de Posse de Candidatos com Doença Grave

A vedação à posse de candidatos com doença grave é questionada, sendo considerada inconstitucional por não permitir a possibilidade de retorno ao trabalho.

### Conceitos
- **Constituição**: O texto constitucional que regula os direitos e deveres dos cidadãos.
- **Administração Pública**: A gestão pública de serviços e políticas.
- **Vedação à Posse**: Restrição à possibilidade de um indivíduo ocupar um cargo público.
- **Doença Grave**: Condição médica que impede a realização de atividades normais.
- **Legitimidade**: Qualidade de ser legítimo ou justificável.
- **Repercussão Geral**: Efeito que se produz em uma área jurídica quando um caso é julgado por uma instância superior.
- **Concurso Público**: Processo para escolher candidatos para cargos públicos.

### Referências legais
- Art. 37, Capítulo III da Constituição Federal; Art. 307 da Lei Estadual n. 10.261/1998

### Jurisprudência
- RE 123456
- Súmula 432 do STF

### Dicas de prova
- Entenda a noção de vedação à posse e sua relação com a Constituição.
- Análise da doença grave e sua influência na possibilidade de retorno ao trabalho.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.335 (2)", "page_number": 335, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal; Art. 307 da Lei Estadual n. 10.261/1998"], "jurisprudence": ["RE 123456", "Súmula 432 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T10:23:52.325246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=335", "doc_key": "d8f7756951cbe41e3876acde8e4d790b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '251c0eb195ca2f9f5ccff42a7357627167a1e00f01bf1fd5cd8c946af8fd1909'),
  ('cpiuris2025::58e24ddc1550a53dbc0ae1c4ceb4e09e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Restrições ao acesso a cargos públicos', '## Restrições ao acesso a cargos públicos

A vedação à posse em cargo público de candidato(a) aprovado(a) com doença grave, mas sem sintomas incapacitantes ou restrição relevante, é inconstitucional, violando os princípios da legalidade, impessoalidade e eficiência.

### Conceitos
- **Princípio da Legalidade**: Requer que as ações administrativas sejam previamente autorizadas por lei
- **Impessoalidade**: Exige que as ações administrativas sejam tomadas de forma imparcial e sem influência de interesses pessoais
- **Eficiência**: Requer que as ações administrativas sejam tomadas de forma eficaz e econômica
- **Acessibilidade aos cargos públicos**: Requer que os candidatos tenham igual oportunidade de serem contratados para cargos públicos
- **Direito ao trabalho**: É um direito fundamental que permite à pessoa exercer sua atividade profissional

### Referências legais
- CF, art. 37, caput; CF, art. 1º, III

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre doenças que afetam homens e mulheres
- Importância do princípio da legalidade na administração pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.336 (1)", "page_number": 336, "discipline": "Direito Administrativo", "legal_refs": ["CF, art. 37, caput; CF, art. 1º, III"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T10:24:44.585471+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=336", "doc_key": "58e24ddc1550a53dbc0ae1c4ceb4e09e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f6c89b471d434ae11b9450467cd61c844662e42b6db1f854725ff2b25d5de7c0'),
  ('cpiuris2025::5ca24979edb83f5d1df4287076cd0bc8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Recurso Extraordinário e Ação Direta de Inconstitucionalidade', '## Recurso Extraordinário e Ação Direta de Inconstitucionalidade

Ação direta de inconstitucionalidade julgada procedente para declarar a inconstitucionalidade da Lei 12.753/2023, do Estado da Paraíba, que estabelece bônus de 10% na nota para candidatos paraibanos residentes no estado.

### Conceitos
- **Impessonalidade**: Princípio que proíbe distinções arbitrárias entre os cidadãos
- **Isonomia**: Princípio que proíbe a desigualdade entre os brasileiros
- **Ação Direta de Inconstitucionalidade**: Mecanismo processual para declarar a inconstitucionalidade de uma lei
- **Recurso Extraordinário**: Mecanismo processual para apelar decisões do Tribunal Pleno

### Referências legais
- Art. 5º, 19, II e 37, II da Constituição Federal

### Jurisprudência
- RE 886131
- Súmula 456/STF

### Dicas de prova
- Entenda a importância da Impessoalidade e Isonomia na Administração Pública
- Conheça o processo de Ação Direta de Inconstitucionalidade e Recurso Extraordinário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.336 (2)", "page_number": 336, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, 19, II e 37, II da Constituição Federal"], "jurisprudence": ["RE 886131", "Súmula 456/STF"], "confidence": 0.8, "extracted_at": "2026-05-25T10:25:45.191720+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=336", "doc_key": "5ca24979edb83f5d1df4287076cd0bc8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f488738358e1c700069e00ad6e97671686ea7e6d92566bd7380b84cea645af83'),
  ('cpiuris2025::12a6bfb7e77a519f6db9774fbee882b9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Proibição de tatuagens a candidatos a concurso público', '## Proibição de tatuagens a candidatos a concurso público

A proibição de tatuagens a candidatos a cargo público é inconstitucional, pois viola os princípios da isonomia e da razoabilidade.

### Conceitos
- **Isonomia**: Princípio constitucional que exige igualdade de tratamento para todos os cidadãos
- **Razoabilidade**: Princípio constitucional que exige que as ações do Estado sejam razoáveis e não arbitrárias
- **Liberdade de manifestação**: Direito individual de expressar-se de forma livre, sem medo de punição

### Referências legais
- Art. 37, caput, da Constituição Federal
- RE 898.450/2016

### Jurisprudência
- RE 898.450/2016

### Dicas de prova
- Distinção entre tatuagem e conduta atentatória aos bons costumes
- Importância da liberdade de manifestação individual
- Repercussão geral do RE 898.450/2016', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.337 (1)", "page_number": 337, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, caput, da Constituição Federal", "RE 898.450/2016"], "jurisprudence": ["RE 898.450/2016"], "confidence": 0.8, "extracted_at": "2026-05-25T10:26:32.085783+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=337", "doc_key": "12a6bfb7e77a519f6db9774fbee882b9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '96c412b5e0dafd866d6d5198cd684497b4d98bee00427c79919cbf2fa7b3fda0'),
  ('cpiuris2025::04fa4be92af0d732b4341518d46f05a2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Limites à liberdade de expressão nos funcionários públicos', '## Limites à liberdade de expressão nos funcionários públicos

O Estado não pode impedir a liberdade de expressão dos funcionários públicos, mas deve coibir tatuagens que prejudiquem a disciplina e a boa ordem. As Forças Armadas podem vedar o ingresso de pessoas com tatuagens que transmitam mensagens relacionadas à violação da lei e da ordem.

### Conceitos
- **liberdade de expressão**: direito fundamental de expressar opiniões, pensamentos e ideias
- **disciplina e boa ordem**: necessário para o funcionamento eficiente do Estado
- **coibição**: medida tomada pelo Estado para limitar uma conduta considerada incompatível com a função pública
- **função militar**: atividade exercida pelas Forças Armadas

### Referências legais
- Art. 37, XVI, da CF/88

### Dicas de prova
- Entenda a distinção entre liberdade de expressão e coibição
- Conheça as limitações para o ingresso de funcionários públicos com tatuagens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.337 (2)", "page_number": 337, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, XVI, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T10:27:14.053246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=337", "doc_key": "04fa4be92af0d732b4341518d46f05a2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '65830af65af9dcd2ce03ded21044014a9cdfbf8cbfb0b6e989cb3e397546e743'),
  ('cpiuris2025::071b60fc9d7ef5fc4f4886ac3105af18', 'doutrina', 'cp_iuris', 'Direito Administrativo — Indenização por danos materiais em decorrência de nomeação tardia para cargo público', '## Indenização por danos materiais em decorrência de nomeação tardia para cargo público

O STJ e o STF não consideram devida a indenização por danos materiais ao candidato aprovado em concurso público cuja nomeação tardia decorreu de decisão judicial, pois isso levaria a enriquecimento ilícito.

### Conceitos
- **Indenização**: Pagamento de uma quantia para compensar um dano ou prejuízo
- **Enriquecimento ilícito**: Aquisição indevida de bens ou direitos por meio de atos ilícitos
- **Personalidade jurídica**: O estado de ser que permite ao indivíduo contratar, ser processado e ter direitos e obrigações

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- ...

### Jurisprudência
