- {''term'': ''STJ e STF'', ''definition'': ''Superior Tribunal de Justiça e Supremo Tribunal Federal''}

### Dicas de prova
- Entenda a noção de enriquecimento ilícito e sua aplicação na indenização por danos materiais.
- Conheça a importância da personalidade jurídica para a titularidade de direitos e obrigações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.338 (1)", "page_number": 338, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "..."], "jurisprudence": ["{''term'': ''EREsp 1.117.974-RS'', ''definition'': ''Processo de recurso especial do EREsp''}", "{''term'': ''STJ e STF'', ''definition'': ''Superior Tribunal de Justiça e Supremo Tribunal Federal''}"], "confidence": 0.8, "extracted_at": "2026-05-25T10:28:20.305381+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=338", "doc_key": "071b60fc9d7ef5fc4f4886ac3105af18"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '10dfffef1acee4cdd429b9fc1f76c99f13f6e7d46479c8a8e1c394bcf22de0f8'),
  ('cpiuris2025::a509c5d2d684517e2e477097c0800a40', 'doutrina', 'cp_iuris', 'Direito Administrativo — Restituição de valores indevidamente recebidos por servidor público', '## Restituição de valores indevidamente recebidos por servidor público

O espólio não pode ser vinculado ao dever de restituição e, portanto, não é parte legítima na ação.

### Conceitos
- **Dever de restituição**: Obrigação do servidor público de devolver valores indevidamente recebidos
- **Espólio**: Bens ou direitos que não podem ser vinculados a uma pessoa específica
- **Parte legítima**: Direito de uma pessoa para agir em um determinado assunto

### Referências legais
- Art. 17 do CPC/2015
- Súmula 1.244.182/STJ
- REsp 1.805.473-DF
- REsp 1.769.306/AL
- RE 1176440/DF

### Jurisprudência
- REsp 1.805.473-DF
- REsp 1.769.306/AL
- RE 1176440/DF

### Dicas de prova
- Entenda a noção de espólio e sua relação com o dever de restituição
- Diferencie entre erro administrativo e interpretação errônea ou má aplicação da lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.338 (2)", "page_number": 338, "discipline": "Direito Administrativo", "legal_refs": ["Art. 17 do CPC/2015", "Súmula 1.244.182/STJ", "REsp 1.805.473-DF", "REsp 1.769.306/AL", "RE 1176440/DF"], "jurisprudence": ["REsp 1.805.473-DF", "REsp 1.769.306/AL", "RE 1176440/DF"], "confidence": 0.8, "extracted_at": "2026-05-25T10:29:06.900998+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=338", "doc_key": "a509c5d2d684517e2e477097c0800a40"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '61d7b60d60f0559ceb60e60eef914b77d2fa751f4daafe7e6b099537aea92720'),
  ('cpiuris2025::cb18d55e65dd44efdeff6c6d39370072', 'doutrina', 'cp_iuris', 'Direito Administrativo — Restituição de valores pagos por servidores públicos', '## Restituição de valores pagos por servidores públicos

A restituição de valores pagos por servidores públicos é devida se comprovada a boa-fé objetiva e impossibilidade de constatar o pagamento indevido. A jurisprudência do STJ e STF estabelece que não é devida a restituição em casos de decisão judicial posteriormente revogada.

### Conceitos
- **Boa-fé objetiva**: Comprovação de intenção legítima e imparcialidade
- **Restituição de valores**: Devolução de valores indevidamente pagos
- **Decisão judicial posteriormente revogada**: Decisão que foi alterada ou anulada por decisão superior
- **Confiança legítima**: Credibilidade e confiança depositadas em uma decisão judicial

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- Súmula 348 do STJ

### Jurisprudência
- EREsp 1.335.962-RS
- EAREsp 58.820-AL

### Dicas de prova
- Distinção entre boa-fé objetiva e confiança legítima
- Importância da decisão judicial posteriormente revogada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.339 (1)", "page_number": 339, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "Súmula 348 do STJ"], "jurisprudence": ["EREsp 1.335.962-RS", "EAREsp 58.820-AL"], "confidence": 0.8, "extracted_at": "2026-05-25T10:29:56.185878+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=339", "doc_key": "cb18d55e65dd44efdeff6c6d39370072"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'bcd30aebf1d6f8c9257f371a7ab14bbec461d2be19469683bce574dd22676086'),
  ('cpiuris2025::10faa145de0b4d4dcab0a203b44ca3d2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Teoria do Fato Consumado em Remoção de Servidor Público', '## Teoria do Fato Consumado em Remoção de Servidor Público

A teoria do fato consumado é aplicada para preservar interesses sociais consolidados, mas não se aplica em hipóteses contrárias à lei, especialmente quando amparadas em provimento judicial de natureza precária.

### Conceitos
- **Teoria do Fato Consumado**: aplicada para preservar interesses sociais consolidados
- **Interesses Jurídicos**: preservados pela teoria do fato consumado
- **Provedor Judicial de Natureza Precária**: provido em hipóteses contrárias à lei

### Referências legais
- Art. 37, Caput, da CF; Art. 5º, inciso XXXVI, da CF

### Jurisprudência
- RE 123456
- AgRg no REsp 1.453.357-RN (Segunda Turma, DJe 9/10/2014)

### Dicas de prova
- Distinção entre interesses jurídicos e sociais
- Reconhecimento da teoria do fato consumado em hipóteses específicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.339 (2)", "page_number": 339, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Caput, da CF; Art. 5º, inciso XXXVI, da CF"], "jurisprudence": ["RE 123456", "AgRg no REsp 1.453.357-RN (Segunda Turma, DJe 9/10/2014)"], "confidence": 0.8, "extracted_at": "2026-05-25T10:30:49.059911+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=339", "doc_key": "10faa145de0b4d4dcab0a203b44ca3d2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f14617d1cdff52efbbdbefcd84cb308ee2557b1a4507bde401a2dd710c891d0d'),
  ('cpiuris2025::b3e54d486c9910fea8e98ff3602b0dc0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Teoria do Fato Consumado e Convalidação dos Atos Administrativos', '## Teoria do Fato Consumado e Convalidação dos Atos Administrativos

A teoria do fato consumado é relacionada à convalidação dos atos administrativos, regulamentada pelo artigo 54 da Lei n. 9.784/99. Para que se tenha por aplicável essa teoria, é necessário distinguir entre duas situações: quando um ato contrário à lei é praticado sem dolo e sem contestação, atribuindo-se ares de legalidade, e quando o ato é praticado sob contestação das pessoas envolvidas.

### Conceitos
- **Teoria do Fato Consumado**: Relacionada à convalidação dos atos administrativos
- **Convalidação dos Atos Administrativos**: Regulamentada pelo artigo 54 da Lei n. 9.784/99
- **Dolo e Contestação**: Necessário distinguir entre situações em que o ato é praticado sem dolo e sem contestação, e quando é praticado sob contestação das pessoas envolvidas
- **Ares de Legalidade**: Atribuição de ares de legalidade a determinada circunstância
- **Segurança Jurídica**: Protege-se a segurança jurídica e o princípio da confiança legítima do administrado
- **Estabilidade das Relações**: Preservar a estabilidade das relações geradas pelo ato inválido
- **Boa-Fé**: Protege-se a boa-fé e o princípio da confiança legítima do administrado
- **Princípio da Confiança Legítima**: Associado à segurança jurídica

### Referências legais
- Art. 54 da Lei n. 9.784/99

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre situações em que o ato é praticado sem dolo e sem contestação, e quando é praticado sob contestação das pessoas envolvidas
- Entender a importância da segurança jurídica e do princípio da confiança legítima do administrado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.340 (1)", "page_number": 340, "discipline": "Direito Administrativo", "legal_refs": ["Art. 54 da Lei n. 9.784/99"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T10:32:02.872087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=340", "doc_key": "b3e54d486c9910fea8e98ff3602b0dc0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2a0b7ff4734e6361ba65dad96470617ff545623b5bf57db462392930a415ea39'),
  ('cpiuris2025::f505752200e99b893f5764fcce3bf5f7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Competência para instaurar e julgar processo disciplinar', '## Competência para instaurar e julgar processo disciplinar

A competência para instaurar e julgar processo disciplinar contra servidor público federal que praticou falta funcional durante a cessação de cargo em comissão é legítima no órgão onde foi praticada a irregularidade.

### Conceitos
- **Competência**: A capacidade do órgão para tomar decisões sobre um processo
- **Processo disciplinar**: O procedimento utilizado para punir servidor público federal por falta funcional
- **Cessação de cargo em comissão**: A transferência de um servidor público federal de um cargo para outro, geralmente temporário

### Referências legais
- Art. 36, III, ''a'', da Lei n. 8.112/90

### Jurisprudência
- EREsp 1.157.628-RJ
- Tema repetitivo: Competência para instaurar e julgar processo disciplinar

### Dicas de prova
- Entenda a competência do órgão que instaura o processo disciplinar
- Conheça as regras sobre a cessação de cargo em comissão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.340 (2)", "page_number": 340, "discipline": "Direito Administrativo", "legal_refs": ["Art. 36, III, ''a'', da Lei n. 8.112/90"], "jurisprudence": ["EREsp 1.157.628-RJ", "Tema repetitivo: Competência para instaurar e julgar processo disciplinar"], "confidence": 0.8, "extracted_at": "2026-05-25T10:32:48.415392+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=340", "doc_key": "f505752200e99b893f5764fcce3bf5f7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4265abe5c7d3142bac20f8923529671ba265eb522cc7fdcef14623d3f2b5b469'),
  ('cpiuris2025::d530d583364d1f395c9d45926cba6dc5', 'doutrina', 'cp_iuris', 'Direito Administrativo — Competência e responsabilidade nos atos administrativos', '## Competência e responsabilidade nos atos administrativos

Regra sobre a competência da instituição onde foi praticado o ato antijurídico, relacionando-se com a coleta de provas e realização de diligências.

### Conceitos
- **Competência**: A capacidade do órgão administrativo de julgar ou decidir sobre um determinado assunto.
- **Responsabilidade**: A obrigação do servidor público de agir com imparcialidade e justiça.
- **Atos administrativos**: Decisões ou ações tomadas por órgãos públicos.

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Dicas de prova
- Entenda que a competência é determinante para a responsabilidade do servidor público.
- Diferencie entre competência e responsabilidade nos atos administrativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.340 (3)", "page_number": 340, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T10:33:29.175998+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=340", "doc_key": "d530d583364d1f395c9d45926cba6dc5"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9bbd2a07d5a8d78d98e2a5b3c149224d9c8a8ea61558f9699a8a37b5e0b40a50'),
  ('cpiuris2025::4bcac1e053400dea80354a891066f40b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade dos Agentes Públicos', '## Responsabilidade dos Agentes Públicos

O texto destaca a responsabilidade dos agentes públicos em relação à instauração do processo disciplinar e a aplicação de penalidades. O vínculo funcional com o órgão cedente é fundamental para determinar quem julga e aplica as penalidades.

### Conceitos
- **Vínculo funcional**: Relação jurídica entre o servidor público e o órgão em que trabalha
- **Instauração do processo disciplinar**: Procedimento administrativo para julgar a conduta de um agente público
- **Aplicação de penalidades**: Medidas disciplinares impostas a um agente público por infrações cometidas

### Referências legais
- Art. 141 do RJU
- Art. 166 do RJU
- Art. 167 do RJU

### Jurisprudência
- STF - Plenário - ADF 362/BA
- EC 19/98

### Dicas de prova
- Entenda o conceito de vínculo funcional e sua importância na responsabilidade dos agentes públicos
- Conheça as regras para a instauração do processo disciplinar e a aplicação de penalidades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.341 (1)", "page_number": 341, "discipline": "Direito Administrativo", "legal_refs": ["Art. 141 do RJU", "Art. 166 do RJU", "Art. 167 do RJU"], "jurisprudence": ["STF - Plenário - ADF 362/BA", "EC 19/98"], "confidence": 0.8, "extracted_at": "2026-05-25T10:34:18.381536+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=341", "doc_key": "4bcac1e053400dea80354a891066f40b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3e32bfcc52b95479640600e2b70663facdcac663f3f0c76c326e90d161cb23c8'),
  ('cpiuris2025::c30f41a91599e2ca5796397c4f610bec', 'doutrina', 'cp_iuris', 'Direito Administrativo — Regras Básicas do Trabalho', '## Regras Básicas do Trabalho

São listadas regras básicas para o trabalho, incluindo remuneração, duração da jornada, repouso semanal e férias.

### Conceitos
- **Remuneração Noturna**: Salário superior àquele do diurno
- **Jornada de Trabalho**: Não superior a oito horas diárias e quarenta e quatro semanas
- **Repouso Semanal**: Preferencialmente aos domingos, com remuneração
- **Férias Anuais**: Com pelo menos um terço a mais do que o salário normal
- **Licença à Gestante**: Sem prejuízo do emprego e do salário, com duração de 120 dias
- **Proteção ao Mercado de Trabalho da Mulher**: Com incentivos específicos
- **Redução dos Riscos Inerentes ao Trabalho**: Por meio de normas de saúde, higiene e segurança
- **Proibição de Diferenças de Salário**: Por motivo de sexo, idade, cor ou estado civil

### Referências legais
- Art. XXVII da CLT

### Dicas de prova
- Reconheça as regras básicas do trabalho listadas no texto
- Entenda a importância das férias anuais e licenças para trabalhadores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.341 (2)", "page_number": 341, "discipline": "Direito Administrativo", "legal_refs": ["Art. XXVII da CLT"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T10:35:09.597758+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=341", "doc_key": "c30f41a91599e2ca5796397c4f610bec"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2ad7dbbc147c5d19bf0e17df4b96e2331b1f0e0e8664d38cfc65f83e112b9eeb'),
  ('cpiuris2025::fca7b8ac1f89e473fe53e8f3d9280007', 'doutrina', 'cp_iuris', 'Direito Administrativo — Intervenção do Estado na Propriedade', '## Intervenção do Estado na Propriedade

O Estado possui domínio eminente sobre todos os bens, independentemente de serem públicos ou privados. A intervenção do Estado na propriedade pode ocorrer em forma restritiva (limitações administrativas) ou supressiva (desapropriação), com o objetivo de alcançar o interesse público e proteger a função social da propriedade.

### Conceitos
- **Domínio Eminente**: Poder geral do Estado sobre todos os bens dentro de suas linhas territoriais
- **Função Social da Propriedade**: Obrigação de desenvolver sua função social para atingir o interesse público
- **Intervenção Restritiva**: Restrição com caráter geral e abstrata, sem alteração da titularidade do bem
- **Desapropriação**: Alteração da titularidade do bem, com o objetivo de alcançar o interesse público

### Referências legais
- Art. 5º, XXIII a XXV da CR/88
- Art. 170, III da CR/88

### Jurisprudência
- RE 123456
- Súmula 432 do STJ

### Dicas de prova
- Entenda o conceito de domínio eminente e sua relação com a propriedade
- Conheça as espécies de intervenção do Estado na propriedade (restritiva e supressiva)
- Avalie a importância da função social da propriedade para a intervenção estatal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.344", "page_number": 344, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, XXIII a XXV da CR/88", "Art. 170, III da CR/88"], "jurisprudence": ["RE 123456", "Súmula 432 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T10:36:16.761886+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=344", "doc_key": "fca7b8ac1f89e473fe53e8f3d9280007"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ae2bbf531407e8c5d594100a44b62b645d0a9803983a5576958f35fb52a92617'),
  ('cpiuris2025::cb150d628202e0f1c00b1809a3ed6886', 'doutrina', 'cp_iuris', 'Direito Administrativo — Intervenção do Estado na Propriedade', '## Intervenção do Estado na Propriedade

Requisição administrativa é medida de intervenção do estado na propriedade com caráter de urgência, assegurada indenização ao proprietário. É forma de intervenção transitória instituída por ato administrativo autoexecutório.

### Conceitos
- **Requisição Administrativa**: Medida de intervenção do estado na propriedade com caráter de urgência
- **Servidão Administrativa**: Direito real público que institui restrições sobre propriedade imóvel para execução de obras e serviços de interesse coletivo
- **Indenização**: Pagamento feito ao proprietário em caso de dano causado pela intervenção do estado
- **Ato Administrativo Autoexecutivo**: Ato administrativo que institui a requisição administrativa sem necessidade de autorização prévia

### Referências legais
- Art. 5º, inciso XXV da Constituição Federal

### Jurisprudência
- ACO 3463/STF

### Dicas de prova
- Diferenciar entre requisição administrativa e intervenção do estado na propriedade
- Entender a importância da indenização no caso de dano causado pela intervenção do estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.345 (1)", "page_number": 345, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, inciso XXV da Constituição Federal"], "jurisprudence": ["ACO 3463/STF"], "confidence": 0.8, "extracted_at": "2026-05-25T10:37:05.563892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=345", "doc_key": "cb150d628202e0f1c00b1809a3ed6886"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'bf640b6fb2c50ab77e4d4f66db66d7c2f8a6423a05ae58baf8522e1138af3aad'),
  ('cpiuris2025::0def65c62bbec1934a242853d4dfdf14', 'doutrina', 'cp_iuris', 'Direito Administrativo — Restrição Definitiva em Direito Administrativo', '## Restrição Definitiva em Direito Administrativo

A restrição definitiva pode ser instituída por meio de acordo administrativo, sentença judicial ou lei, com direito a indenização proporcional no caso de efetivo prejudico.

### Conceitos
- **Definitividade**: Caráter que impede a alteração da decisão
- **Utilidade Pública**: Justificativa para a instituição de uma restrição definitiva
- **Indenização**: Direito à compensação por prejudico
- **Prejuízo Efetivo**: Condição necessária para a concessão da indenização

### Referências legais
- Art. 5º, inciso XXI da CF/88
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre a definitividade e a finalidade
- Entender a relação entre utilidade pública e restrição definitiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.345 (2)", "page_number": 345, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, inciso XXI da CF/88", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T10:37:40.174443+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=345", "doc_key": "0def65c62bbec1934a242853d4dfdf14"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7a88e721757183ee5dba1a30d33c09c77bb7ac2d45881504b9e414cfd542a6d8'),
  ('cpiuris2025::64c1a41ce60e0fc724bbdd237f39965c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Intervenção do Estado na Propriedade', '## Intervenção do Estado na Propriedade

A intervenção do estado na propriedade é uma modalidade de intervenção estatal que ocorre quando o estado utiliza bens imóveis ou móveis como meio de apoio para a execução de obras e serviços públicos, ou para promover e proteger o patrimônio cultural brasileiro.

### Conceitos
- **Ocupação temporária**: Uso transitório de bens imóveis como meio de apoio para a execução de obras e serviços públicos.
- **Tombamento**: Modalidade de intervenção do Estado sobre a propriedade que promove e protege o patrimônio cultural brasileiro.
- **Servidão administrativa**: Diferença entre a ocupação temporária e a servidão administrativa, pois não possui caráter de definitividade.

### Referências legais
- Art. 216, §1º, CF

### Jurisprudência
- ACO 1.208
- Súmula N STF

### Dicas de prova
- Diferenciar a ocupação temporária da servidão administrativa.
- Entender o conceito de tombamento e sua importância na proteção do patrimônio cultural brasileiro.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.346 (1)", "page_number": 346, "discipline": "Direito Administrativo", "legal_refs": ["Art. 216, §1º, CF"], "jurisprudence": ["ACO 1.208", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T10:38:39.786673+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=346", "doc_key": "64c1a41ce60e0fc724bbdd237f39965c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd7bdbabf5e23cace8abf3d85caaf6436c595995da91d568505e59b5ccd2f4444'),
  ('cpiuris2025::5cf2cec521c29bbe689759db0eac6af0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Tombamento de Bens Imóveis', '## Tombamento de Bens Imóveis

O tombamento de bens imóveis envolve procedimentos administrativos e seus efeitos, incluindo preservação, restaurações e comunicação a proprietários sobre conservação.

### Conceitos
- **Bens Tombados**: Bens imóveis protegidos por decreto ou lei
- **Indenização**: Pagamento compensatório por dano ou perda
- **Esvaziamento do Conteúdo Econômico**: Perda de valor econômico do bem
- **Conservação e Conservação**: Proteção e manutenção do bem tombado
- **Autorização Pública**: Requisito para realizar reparos ou restaurações
- **Comunicação ao Órgão de Tombamento**: Informação sobre a situação do proprietário
- **Medidas de Urgência Pública**: Ações imediatas para proteger o bem tombado

### Referências legais
- Art. 26 da Lei nº 7.416/1980

### Dicas de prova
- Entenda a diferença entre preservação e conservação
- Conheça as exceções ao pagamento de indenização
- Reconheça o papel do proprietário na comunicação sobre conservação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.346 (2)", "page_number": 346, "discipline": "Direito Administrativo", "legal_refs": ["Art. 26 da Lei nº 7.416/1980"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T10:39:29.415631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=346", "doc_key": "5cf2cec521c29bbe689759db0eac6af0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '21aa130bba3ac2336c12529439bc7b086f83080e397e0722dde1e7cc0ca632c5'),
  ('cpiuris2025::433f6d894e5b16e3d5a4cf744b8e16ff', 'doutrina', 'cp_iuris', 'Direito Administrativo — Intervenção do Estado na Propriedade', '## Intervenção do Estado na Propriedade

O Estado pode intervenir na propriedade sem autorização especial, sob pena de multa, mas há exceções para a restauração e o comércio cultural. Além disso, os proprietários podem ter direito de preferência na alienação judicial de imóveis tombados.

### Conceitos
- **Intervenção do Estado**: Ação do Estado sobre a propriedade sem autorização especial
- **Servidão administrativa**: Limitação do direito de propriedade pelo Poder Público
- **Compensação pela limitação**: Reembolso ao proprietário por perda de valor da propriedade
- **Alienação judicial**: Venda do imóvel por meio de leilão
- **Lei de Precedente**: Decisão anterior que influencia a decisão atual

### Referências legais
- Art. 892, §3º, do CPC
- STJ. 2ª Turma. AREsp 551.389-RN

### Jurisprudência
- RE 123456
- STJ. 2ª Turma. REsp 1992514-CE

### Dicas de prova
- Entenda a diferença entre intervenção do Estado e servidão administrativa
- Conheça o conceito de compensação pela limitação e seu impacto nos direitos dos proprietários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.347 (1)", "page_number": 347, "discipline": "Direito Administrativo", "legal_refs": ["Art. 892, §3º, do CPC", "STJ. 2ª Turma. AREsp 551.389-RN"], "jurisprudence": ["RE 123456", "STJ. 2ª Turma. REsp 1992514-CE"], "confidence": 0.8, "extracted_at": "2026-05-25T10:40:25.021430+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=347", "doc_key": "433f6d894e5b16e3d5a4cf744b8e16ff"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f91966dac1bb80306ad7a3df67439f7801cd514bc300845f08c475ba23ee328b'),
  ('cpiuris2025::872c43739e815b5d32dbcfcd2d0d2c29', 'doutrina', 'cp_iuris', 'Direito Administrativo — Requisição administrativa e princípio federativo', '## Requisição administrativa e princípio federativo

A requisição administrativa não recai sobre bens e serviços públicos de outro ente federativo, exceto em casos excepcionais como estado de defesa ou estado de sítio.

### Conceitos
- **Requisição administrativa**: Atendimento de necessidades coletivas, urgentes e transitórias
- **Princípio federativo**: Protege a autonomia dos entes federados

### Referências legais
- Art. 15, XIII, da Lei Orgânica do Sistema Único de Saúde (Lei nº 8.080/90)
- Art. 136, § 1º, II
- Art. 139, VII

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre requisição administrativa e hipótese excepcional de estado de defesa ou estado de sítio
- Importância do princípio federativo na relação entre Poder Público e patrimônio privado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.347 (2)", "page_number": 347, "discipline": "Direito Administrativo", "legal_refs": ["Art. 15, XIII, da Lei Orgânica do Sistema Único de Saúde (Lei nº 8.080/90)", "Art. 136, § 1º, II", "Art. 139, VII"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T10:41:15.474358+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=347", "doc_key": "872c43739e815b5d32dbcfcd2d0d2c29"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '04a92350ff4569a0cf327f3817450be44c1cf729d816a22290ae652e65b979f3'),
  ('cpiuris2025::8598dc13f37af336c862d5aad21540a4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Intervenção do Estado na Propriedade', '## Intervenção do Estado na Propriedade

O Estado não pode interferir indevidamente na propriedade, respeitando a autonomia do proprietário. A intervenção administrativa pode limitar o direito de propriedade, mas não impede a incidência de tributos. O proprietário tem direito à indenização se a limitação administrativa reduzir o valor econômico do bem.

### Conceitos
- **Isonomia**: Tratamento igualitário entre os entes federados
- **Limitação administrativa**: Interferência do Estado na propriedade sem necessidade de autorização expressa
- **Propriedade**: Direito real que confere ao proprietário o domínio útil sobre um imóvel
- **Tributo**: Imposto imposto pelo Estado sobre a propriedade ou atividade econômica

### Referências legais
- Art. 21 da Constituição Federal de 1988
- Súmula 3454 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- ADI 3454/DF
- STF Plenário
- REsp 1695340-MG
- AgRg no REsp 1317806-MG
- AREsp 176140-BA

### Dicas de prova
- Distinguir entre limitação administrativa e interferência indevida do Estado na propriedade
- Entender a relação entre tributos e propriedade
- Conhecer o prazo prescricional para buscar indenização por limitações administrativas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.348", "page_number": 348, "discipline": "Direito Administrativo", "legal_refs": ["Art. 21 da Constituição Federal de 1988", "Súmula 3454 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "ADI 3454/DF", "STF Plenário", "REsp 1695340-MG", "AgRg no REsp 1317806-MG", "AREsp 176140-BA"], "confidence": 0.8, "extracted_at": "2026-05-25T10:42:15.472726+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=348", "doc_key": "8598dc13f37af336c862d5aad21540a4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ec73221dc7c1a7a3623312a2c951722563885f801a60de6eb1b8ce81d1d3e61f'),
  ('cpiuris2025::d718a7630a9c6c5aa935529cefeeea8f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação', '## Desapropriação

A desapropriação é uma modalidade de intervenção supressiva na propriedade, realizada pelo Poder Público com o objetivo de transferir a propriedade para si mesmo em razão de utilidade pública ou interesse social. A desapropriação é uma aquisição originária da propriedade e considera-se extinto o direito real de terceiros sobre o bem.

### Conceitos
- **Desapropriação**: Intervenção supressiva na propriedade realizada pelo Poder Público
- **Aquisição originária da propriedade**: Transferência da propriedade para o Poder Público sem qualquer ônus em favor de terceiro
- **Utilidade pública**: Razão que justifica a desapropriação, como interesse social ou necessidade pública

### Referências legais
- Art. 5º, XXIII e XXIV da CR/88
- Art. 31 do Decreto-Lei 3.365/41

### Jurisprudência
- RE 123456
- Súmula N STF
- REsp 1.668.058-ES

### Dicas de prova
- Entenda a diferença entre desapropriação e aquisição originária da propriedade
- Conheça as modalidades de desapropriação (necessidade pública e utilidade pública)
- Avalie o papel do Poder Público na desapropriação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.350", "page_number": 350, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, XXIII e XXIV da CR/88", "Art. 31 do Decreto-Lei 3.365/41"], "jurisprudence": ["RE 123456", "Súmula N STF", "REsp 1.668.058-ES"], "confidence": 0.8, "extracted_at": "2026-05-25T10:43:13.218266+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=350", "doc_key": "d718a7630a9c6c5aa935529cefeeea8f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2e5685e55406207d3ca43750f2a2adc4666c9158c984770d8e93ab41a59092f6'),
  ('cpiuris2025::897c04ac3ebe33ec6cd47d59ddaf2892', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação', '## Desapropriação

Desapropriação é modalidade de expropriação que pode ser feita por necessidade pública, utilidade pública ou interesse social.

### Conceitos
- **Necessidade Pública**: Falta de um bem ou serviço essencial para a segurança nacional ou o bem-estar da população.
- **Utilidade Pública**: Interesse que beneficia a sociedade como um todo, como a segurança nacional, defesa do Estado, etc.
- **Interesse Social**: Benefício para a população em geral, como reforma agrária ou urbanística.
- **Desapropriação por Necessidade Pública**: Falta de um bem ou serviço essencial para a segurança nacional ou o bem-estar da população.
- **Desapropriação por Utilidade Pública**: Benefício para a sociedade como um todo, como a segurança nacional, defesa do Estado, etc.
- **Desapropriação por Interesse Social**: Benefício para a população em geral, como reforma agrária ou urbanística.
- **Utilidade Pública Regulada**: Desapropriação regulamentada pelo Decreto-Lei 3.365/41.
- **Interesse Social Regulado**: Desapropriação regulamentada pela Lei n.º 4.132/62.

### Referências legais
- Art. 5º, incisos a a i do Decreto-Lei 3.365/41
- Art. 2º da Lei n.º 4.132/62

### Dicas de prova
- Diferenciar entre necessidade pública e utilidade pública.
- Entender a distinção entre interesse social e reforma agrária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.351", "page_number": 351, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, incisos a a i do Decreto-Lei 3.365/41", "Art. 2º da Lei n.º 4.132/62"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T10:44:27.914046+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=351", "doc_key": "897c04ac3ebe33ec6cd47d59ddaf2892"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '16f738bd4cdf54e002a6366a97db5f0f3875d2ea97a19ded8477eafaa035b9f2'),
  ('cpiuris2025::77e5b5ab53be051d4a8023ebf1346975', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação para fins de Reforma Agrária', '## Desapropriação para fins de Reforma Agrária

A desapropriação por interesse social, prevista no art. 184 da CR/88, é uma sanção punitiva realizada pela União para fins de reforma agrária, com prévia e justa indenização em títulos da dívida agrária.

### Conceitos
- **Desapropriação**: Ato pelo qual o Estado expropria um bem ou direito para fins específicos.
- **Reforma Agrária**: Política pública que visa redistribuir terras e benefícios econômicos rurais para os pequenos agricultores e comunidades rurais.
- **Interesse Social**: Motivo pelo qual o Estado pode expropriar um bem ou direito, previsto no art. 184 da CR/88.
- **Previa e Justa Indenização**: Obrigação do Estado de compensar o proprietário com uma indenização em títulos da dívida agrária.
- **Título da Dívida Agrária**: Documento que representa um crédito do governo para pagamento de uma dívida agrária.
- **Benfeitorias Necessárias e Úteis**: Benefícios que o proprietário pode receber em dinheiro, previstos no art. 184, § 1º da CR/88.
- **Procedimento Contraditório Especial**: Rito sumário para o processo judicial de desapropriação, regulamentado pela Lei Complementar n.º 76/93.
- **Isenção de Impostos**: Exigência do art. 184, § 5º da CR/88, que exclui os bens desapropriados de impostos federais, estaduais e municipais.

### Referências legais
- Art. 184 da CR/88
- Lei Complementar n.º 76/93

### Jurisprudência
- Súmula 354 do STJ

### Dicas de prova
- Diferenciar entre desapropriação punitiva e indenização.
- Entender a noção de interesse social e sua relação com a reforma agrária.
- Conhecer as regras sobre isenção de impostos para os bens desapropriados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.352 (1)", "page_number": 352, "discipline": "Direito Administrativo", "legal_refs": ["Art. 184 da CR/88", "Lei Complementar n.º 76/93"], "jurisprudence": ["Súmula 354 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T10:45:45.623621+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=352", "doc_key": "77e5b5ab53be051d4a8023ebf1346975"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '16fefd2768b58acda572a221257917f67d05ef01c3affbf76053ef0585f7003d'),
  ('cpiuris2025::8839c6ccd22290c443519960cf2f70cd', 'doutrina', 'cp_iuris', 'Direito Administrativo — Políticas Públicas e Ações Governamentais', '## Políticas Públicas e Ações Governamentais

Resumo do artigo III do IURIS sobre políticas públicas e ações governamentais.

### Conceitos
- **Colônias de Povoamento**: Estabelecimento de comunidades agrícolas
- **Posseiros Urbanos**: Pessoas que ocupam terrenos urbanos com permissão do proprietário
- **Casa Populares**: Residências construídas por entidades públicas ou privadas para populações carentes
- **Valorização Extraordinária de Terras**: Aumento de valor das terras e águas devido a obras públicas
- **Proteção do Solo**: Medidas para preservar a qualidade do solo e evitar sua degradação

### Referências legais
- Art. III da Lei X
- Súmula Y da STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre políticas públicas

### Dicas de prova
- Entenda a diferença entre colônias de povoamento e posseiros urbanos
- Conheça as características das casas populares e suas implicações jurídicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.352 (2)", "page_number": 352, "discipline": "Direito Administrativo", "legal_refs": ["Art. III da Lei X", "Súmula Y da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre políticas públicas"], "confidence": 0.8, "extracted_at": "2026-05-25T10:46:27.344379+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=352", "doc_key": "8839c6ccd22290c443519960cf2f70cd"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2469339f05036e0f544ef25d08ff357c96b27fb9f420c23f41c25802d92211e0'),
  ('cpiuris2025::557d7bb8211b91ea5dc782b03a8c4f7d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação e Parcelamento Compulsório', '## Desapropriação e Parcelamento Compulsório

A desapropriação pode ser feita por interesse social para fins urbanísticos, com competência do município. O proprietário deve promover o adequado aproveitamento do solo, sob pena de parcelamento ou edificação compulsórias.

### Conceitos
- **Desapropriação**: Ato pelo qual o Poder Público expropriar imóveis para fins públicos.
- **Parcelamento Compulsório**: Obrigação do proprietário de parcelar ou edificar um imóvel não utilizado ou subutilizado
- **Edificação Compulsória**: Obrigação do proprietário de construir um empreendimento no local onde o imóvel está localizado

### Referências legais
- Art. 5º, § 3º e § 4º da Estatuto da Cidade (Lei nº 10.257/01)
- Art. 182, § 4º do CFR/88
- Art. 207 da Lei nº 10.257/01

### Dicas de prova
- Entenda a noção de desapropriação e parcelamento compulsório.
- Conheça as condições e prazos para implementação da obrigação do proprietário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.353", "page_number": 353, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, § 3º e § 4º da Estatuto da Cidade (Lei nº 10.257/01)", "Art. 182, § 4º do CFR/88", "Art. 207 da Lei nº 10.257/01"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T10:47:29.273631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=353", "doc_key": "557d7bb8211b91ea5dc782b03a8c4f7d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c5baaa99685aaaf3412f887dc022faa803c4ee2de3d9b3dae10d915ecb8334fe'),
  ('cpiuris2025::d32918b357a5aaf829c28576f794083c', 'doutrina', 'cp_iuris', 'Direito Administrativo — IPTU Progressivo no Tempo e Desapropriação', '## IPTU Progressivo no Tempo e Desapropriação

O IPTU progressivo no tempo é aplicado em caso de não cumprimento das obrigações de parcelamento, edificação ou utilização compulsórios. Em cinco anos, o Município pode proceder à desapropriação do imóvel com pagamento em títulos da dívida pública.

### Conceitos
- **IPTU**: Imposto sobre a propriedade predial e territorial urbana
- **Parcelamento**: Obrigação de parcelar o imóvel para construção ou utilização
- **Edificação**: Obrigação de edificar o imóvel
- **Utilização**: Obrigação de utilizar o imóvel de forma específica
- **Desapropriação**: Procedimento pelo qual o Estado expropria um imóvel para fins públicos
- **Títulos da dívida pública**: Documentos que representam o débito do Estado com o governo

### Referências legais
- Art. 5º, §2º; Art. 6º; Art. 7º; Art. 8º do EC

### Dicas de prova
- Entenda a relação entre IPTU progressivo no tempo e desapropriação
- Conheça as obrigações compulsórias para parcelamento, edificação e utilização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.354 (1)", "page_number": 354, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, §2º; Art. 6º; Art. 7º; Art. 8º do EC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T10:48:22.299951+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=354", "doc_key": "d32918b357a5aaf829c28576f794083c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '539f645fe665274ef619e703262c07dc0028ebaecc8ccd726016dde2453e06d1'),
  ('cpiuris2025::3a60a7abc6de48bfed09b5f127410256', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação Confiscatória/ Expropriação', '## Desapropriação Confiscatória/ Expropriação

A desapropriação confiscatória é uma modalidade sancionatória que não envolve o pagamento de indenização, sendo regulada pela Lei n.º 8.257/91.

### Conceitos
- **Desapropriação**: Ato pelo qual o Estado expropria imóveis para fins públicos.
- **Confiscatória**: Modalidade de desapropriação que não envolve o pagamento de indenização.
- **Expropriação**: Ato pelo qual o Estado expropria imóveis para fins públicos, geralmente com o objetivo de realizar uma obra ou investimento.
- **Indenização**: Pagamento feito ao proprietário do imóvel em decorrência da desapropriação.
- **Lei n.º 8.257/91**: Lei que regula a desapropriação confiscatória.
- **Poder Público**: O Estado ou suas entidades, como o Município.
- **Procedimento licitatório**: Processo em que se realiza a concorrência para a concessão de um direito ou serviço.

### Referências legais
- Art. 243 da CFR/88
- Lei n.º 8.257/91

### Dicas de prova
- Entenda a diferença entre desapropriação e confiscatória.
- Conheça as obrigações do adquirente de imóvel após a desapropriação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.354 (2)", "page_number": 354, "discipline": "Direito Administrativo", "legal_refs": ["Art. 243 da CFR/88", "Lei n.º 8.257/91"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T10:49:15.744824+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=354", "doc_key": "3a60a7abc6de48bfed09b5f127410256"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '672d08849072bf73dea992eccd3310941a6c3dfa899bc8420998100c0834403f'),
  ('cpiuris2025::586264db9f63ee52a14840196ad38009', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação', '## Desapropriação

A desapropriação é o ato pelo qual a União, Estados, Distrito Federal ou Municípios expropriam propriedades para fins de utilidade pública ou interesse social, sem indenização ao proprietário.

### Conceitos
- **Desapropriação**: Ato pelo qual a União, Estados, Distrito Federal ou Municípios expropriam propriedades
- **Utilidade pública**: Fim social ou econômico que justifica a expropriação de uma propriedade
- **Interesse social**: Fim social que justifica a expropriação de uma propriedade
- **Indenização**: Pagamento feito ao proprietário pela União, Estados, Distrito Federal ou Municípios após a expropriação
- **Confisco**: Ato pelo qual a União, Estados, Distrito Federal ou Municípios tomam posse de um bem apreendido em decorrência de crime
- **Reforma agrária**: Programa que visa redistribuir terras rurais para pequenos agricultores
- **Habitação popular**: Programa que visa construir habitações para pessoas de baixa renda

### Referências legais
- Art. 243 da CR/88
- Art. 2º do Decreto-Lei 3.365/41

### Jurisprudência
- RE 635336
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre utilidade pública e interesse social
- Conheça as exceções à competência da União, Estados, Distrito Federal ou Municípios para declarar desapropriação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.355 (1)", "page_number": 355, "discipline": "Direito Administrativo", "legal_refs": ["Art. 243 da CR/88", "Art. 2º do Decreto-Lei 3.365/41"], "jurisprudence": ["RE 635336", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T10:50:28.214064+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=355", "doc_key": "586264db9f63ee52a14840196ad38009"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '291e7dd112acdb06cd5f579fd3ae30a6f7b93f04114116bbbc0d9397309dcb4c'),
  ('cpiuris2025::6f20251f8bc88555c82b01da2de2a27f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Decretos e Leis com Efeitos Concretos', '## Decretos e Leis com Efeitos Concretos

Resumo objetivo: Decretos e leis com efeitos concretos são atos administrativos em sentido material, podendo ser impugnados via Mandado de Segurança. São atos formais, mas não abstratos.

### Conceitos
- **Decretos e Leis**: Atos administrativos com efeitos concretos
- **Efeitos Concretos**: Caracterização de atos administrativos como atos formais, mas não abstratos
- **Mandado de Segurança**: Meio processual para impugnar atos administrativos
- **Atos Administrativos**: Ações do Estado que têm efeitos sobre os cidadãos

### Referências legais
- Art. 5º da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- {''tip'': ''Distinção entre atos administrativos formais e abstratos''}
- {''tip'': ''Importância do Mandado de Segurança na impugnação de atos administrativos''}', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.355 (2)", "page_number": 355, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T10:51:06.463159+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=355", "doc_key": "6f20251f8bc88555c82b01da2de2a27f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b7181e3847644736bd97166cb9fcd032f63868e91f622c377ebfe72080057b06'),
  ('cpiuris2025::e95a15de6aef876ac7b43bcbced7a0e6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação', '## Desapropriação

A declaração de desapropriação não suprima a propriedade do particular, estabelecendo o valor da indenização e regulamentando as benfeitorias necessárias, úteis ou voluptuárias.

### Conceitos
- **Declaração de Desapropriação**: Ato pelo qual o Estado declara a utilidade pública de um bem
- **Indenização**: Pagamento feito pelo poder público ao proprietário do bem em desapropriação
- **Benfeitorias Necessárias**: Mudanças necessárias para permitir a realização da atividade pública
- **Benfeitorias Úteis**: Mudanças úteis, mas não necessárias, para permitir a realização da atividade pública
- **Benfeitorias Voluptuárias**: Mudanças desnecessárias e sem valor para a realização da atividade pública

### Referências legais
- Art. 26, § 1º do DL 3.365/41
- Art. 2º, § 4º da Lei n.º 8629/93
- Súmula Nº 23 STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre desapropriação de imóveis

### Dicas de prova
- Diferencie entre benfeitorias necessárias, úteis e voluptuárias
- Entenda o prazo decadencial para a fase executória da desapropriação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.356", "page_number": 356, "discipline": "Direito Administrativo", "legal_refs": ["Art. 26, § 1º do DL 3.365/41", "Art. 2º, § 4º da Lei n.º 8629/93", "Súmula Nº 23 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre desapropriação de imóveis"], "confidence": 0.8, "extracted_at": "2026-05-25T10:52:07.180024+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=356", "doc_key": "e95a15de6aef876ac7b43bcbced7a0e6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd994e99c9e86c853fab4f377a341ed3a0e95060382550179cbf5380188c1aba4'),
  ('cpiuris2025::f98da15309d790cbea3956fe8cd8b170', 'doutrina', 'cp_iuris', 'Direito Administrativo — Imissão Provisória na Posse', '## Imissão Provisória na Posse

A imissão provisória na posse é concedida ao expropriante se presentes dois requisitos: declaração de urgência e depósito do valor, independentemente da citação do réu.

### Conceitos
- **Declaração de Urgência**: Obrigação de apresentar declaração de urgência para justificar a necessidade da imissão provisória.
- **Depósito do Valor**: O expropriante deve depositar o valor correspondente à imissão provisória, independentemente da citação do réu.
- **Citação do Réu**: Não é necessário realizar a citação do réu para conceder a imissão provisória.
- **Prazo Improrrogável**: O expropriante tem 120 dias para requerer a imissão provisória após a apresentação da declaração de urgência.
- **Concordância do Expropriado**: Se o expropriado concorda com a oferta, a decisão concedente da imissão provisória implicará na aquisição da propriedade pelo expropriante.
- **Registro da Propriedade**: A imissão provisória é registrada no registro de imóveis competente.
- **Renúncia ao Direito de Questionar o Preço**: O expropriado não pode renunciar ao seu direito de questionar o preço ofertado em juízo.

### Referências legais
- DL 3.365/41, Art. 15; DL 3.365/41, Art. 34-A

### Jurisprudência
- RE 123456

### Dicas de prova
- Observar a presença dos requisitos necessários para a imissão provisória na posse.
- Distinguir entre declaração de urgência e citação do réu.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.357 (1)", "page_number": 357, "discipline": "Direito Administrativo", "legal_refs": ["DL 3.365/41, Art. 15; DL 3.365/41, Art. 34-A"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T10:53:25.124712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=357", "doc_key": "f98da15309d790cbea3956fe8cd8b170"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e247a14e591abd921356ac2ab043dbe1a7da4634af57c4bf16a72bbbed0c9c34'),
  ('cpiuris2025::26a649460323a043aae79e25253df1cf', 'doutrina', 'cp_iuris', 'Direito Administrativo — Competência para a fase executória', '## Competência para a fase executória

A fase executória é competente para os atos de transferência da propriedade, desde a negociação até a finalização do processo judicial expropriatório.

### Conceitos
- **Fase Executória**: Etapa da execução dos atos de transferência da propriedade
- **Competência Administrativa**: A competência para proceder a fase executória é exercida pelos entes da Administração Pública Direta, Indireta, Concessionários e Permissionários

### Referências legais
- Art. 42 da Lei nº 6.938/74
- ...

### Jurisprudência
- Súmula 652 do STF

### Dicas de prova
- Entenda a competência para a fase executória e os entes que a exercem.
- Reconheça a inconstitucionalidade mencionada na súmula 652 do STF.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.357 (2)", "page_number": 357, "discipline": "Direito Administrativo", "legal_refs": ["Art. 42 da Lei nº 6.938/74", "..."], "jurisprudence": ["Súmula 652 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T10:53:56.909614+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=357", "doc_key": "26a649460323a043aae79e25253df1cf"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd11e2cf3dd2e3107dbb5156ac9829eb5f4e3c67d3ee86d9aeffb05aec5a95c48'),
  ('cpiuris2025::15dcf2396a5591a5309b3a5763b8b276', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação', '## Desapropriação

A desapropriação é um ato do Poder Público que envolve a tomada de posse de propriedade para fins de utilidade pública. Existem duas vias para a desapropriação: administrativa e judicial.

### Conceitos
- **Desapropriação**: Ato do Poder Público que envolve a tomada de posse de propriedade para fins de utilidade pública.
- **Via Administrativa**: Fase em que o acordo entre o Poder Público e o proprietário evita a ação de desapropriação no Poder Judiciário.
- **Via Judicial**: Fase em que não há acordo, e a ação é ajuizada para solucionar o conflito de interesses entre o Poder Público e o Proprietário.

### Referências legais
- Art. 9º DL 3.365/41
- Enunciado 3 do CJF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre a via administrativa e judicial
- Entendimento do artigo 9º do Decreto-Lei n. 3.365/1941
- Alegações válidas e inválidas no processo de desapropriação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.358 (1)", "page_number": 358, "discipline": "Direito Administrativo", "legal_refs": ["Art. 9º DL 3.365/41", "Enunciado 3 do CJF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T10:54:48.329149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=358", "doc_key": "15dcf2396a5591a5309b3a5763b8b276"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'eff07639725276fb7a859b46abcc6237e4537db1d8ff817e5ace1fe8a3624532'),
  ('cpiuris2025::647cc6a03d59315133483766bd201393', 'doutrina', 'cp_iuris', 'Direito Administrativo — Ação Somente no DF', '## Ação Somente no DF

A ação somente pode ser ajuizada no Distrito Federal se o réu tiver domicílio no DF. Caso contrário, não pode ser ajuizada pela União.

### Conceitos
- **ação administrativa**: juízo que é exercido pelo Estado em relação a um cidadão
- **domicílio**: local onde alguém tem sua residência ou habitação
- **citação**: notificação oficial para que alguém compareça a um tribunal ou ajuite uma ação
- **desapropriação**: ação do Estado para tomar posse de um imóvel
- **utilidade pública**: interesse público que justifica a aquisição de um bem

### Referências legais
- Art. 16 do Decreto-Lei 3.365/1941
- Art. 10, § 1º, I do CPC
- Art. 42 do Decreto-Lei 3.365/1941

### Jurisprudência
- RE 86.933
- REsp 1.404.085-CE

### Dicas de prova
- Entenda a noção de ação administrativa e sua relação com o domicílio do réu.
- Conheça as regras sobre citação em processos judiciais, especialmente em desapropriações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.358 (2)", "page_number": 358, "discipline": "Direito Administrativo", "legal_refs": ["Art. 16 do Decreto-Lei 3.365/1941", "Art. 10, § 1º, I do CPC", "Art. 42 do Decreto-Lei 3.365/1941"], "jurisprudence": ["RE 86.933", "REsp 1.404.085-CE"], "confidence": 0.8, "extracted_at": "2026-05-25T10:55:46.118755+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=358", "doc_key": "647cc6a03d59315133483766bd201393"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7beb3a00989af7ad9698992f67a971bbbd913a620125ee7df424fbc3f1e23a64'),
  ('cpiuris2025::99d5696db95d9f8aad678184269dd0d1', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação', '## Desapropriação

A desapropriação é um ato do Estado que envolve a tomada de propriedade de bens públicos ou privados, com o objetivo de atender a interesses públicos. A desapropriação pode ser feita por meio de mediação ou arbitragem, após a oferta da indenização ao proprietário.

### Conceitos
- **Mediação**: Procedimento que envolve a negociação entre as partes para chegar a um acordo
- **Arbitragem**: Procedimento que envolve a resolução de disputas por meio de uma decisão imparcial
- **Indenização**: Pagamento feito ao proprietário do bem desapropriado
- **Hierarquia Federativa**: Relação entre os Estados, Municípios e Distrito Federal no âmbito federal

### Referências legais
- Art. 2º, § 2º do DL 3.365/41
- Súmula Nº 157 STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre mediação e arbitragem
- Entender a importância da autorização legislativa na desapropriação
- Conhecer as exceções à regra de desapropriação de bens públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.359", "page_number": 359, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º, § 2º do DL 3.365/41", "Súmula Nº 157 STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T10:56:39.548354+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=359", "doc_key": "99d5696db95d9f8aad678184269dd0d1"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9da71d8b8ca9eb7695513149939c107b9288e50d8e64637f6a9e8c446df95bef'),
  ('cpiuris2025::1caa6392ece2cc4f0b51f4b74a6ec6ee', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação e Direitos Conexas', '## Desapropriação e Direitos Conexas

Resumo do texto sobre desapropriação de bens, incluindo exceções e direitos conexos.

### Conceitos
- **Desapropriação**: Ato pelo qual o Estado expropria um bem para fins públicos.
- **Exceção à desapropriação de cadáveres**: Caso em que a desapropriação é permitida quando o cadáver tem caráter econômico, como em casos históricos e de pesquisa.
- **Bens da União**: Não podem ser desapropriados de acordo com o art. 2º, § 2º do DL 3.365/41.
- **Reforma Agrária**: A pequena e média propriedade rural não pode ser desapropriada para fins de reforma agrária, desde que seu proprietário não possua outra propriedade.
- **Área expropriada**: Área abrangida pela desapropriação para desenvolvimento da obra ou valorização extraordinária.
- **Área deixada para o proprietário**: Área remanescente que se torna insuscetível de exploração econômica após a desapropriação.
- **Direito de Extensão**: Direito do expropriado para exigir que a desapropriação e a indenização alcancem a totalidade do bem quando o remanescente resultar esvaziado de seu conteúdo econômico.
- **Revenda de terceiros**: Permitida ao expropriante vender a área expropriada a terceiros pelo valor atualizado, após a realização da obra.

### Referências legais
- Art. 2º, § 2º do DL 3.365/41

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a exceção à desapropriação de cadáveres e os direitos conexos.
- Conheça as regras para a desapropriação de bens da União e áreas expropriadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.360", "page_number": 360, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º, § 2º do DL 3.365/41"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T10:57:54.955553+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=360", "doc_key": "1caa6392ece2cc4f0b51f4b74a6ec6ee"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f90046b052e88ac32633cd1358499ab2a3c0ef6378ea3029993a8a77bead1e22'),
  ('cpiuris2025::f46f9a1084deceb3029a6b3f1a495107', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação e Retrocessão', '## Desapropriação e Retrocessão

A desapropriação é um procedimento administrativo que pode ser desistido em caso de perda de motivos públicos. A retrocessão é direito do antigo proprietário em casos de tredestinação ilícita.

### Conceitos
- **Desapropriação**: procedimento administrativo para expropriar imóveis por necessidade pública, utilidade pública ou interesse social
- **Retrocessão**: direito do antigo proprietário de exigir retomada do bem ou pagamento de indenização em caso de tredestinação ilícita
- **Tredestinação**: destinação desconforme com o plano inicialmente previsto

### Referências legais
- Art. 76, § 1º, da Lei Complementar n. 76/93

### Jurisprudência
- REsp 1.937.626/RO
- STJ. 1ª Turma

### Dicas de prova
- Entenda a diferença entre desapropriação e retrocessão
- Conheça o conceito de tredestinação e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.361 (1)", "page_number": 361, "discipline": "Direito Administrativo", "legal_refs": ["Art. 76, § 1º, da Lei Complementar n. 76/93"], "jurisprudence": ["REsp 1.937.626/RO", "STJ. 1ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-25T10:58:52.693080+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=361", "doc_key": "f46f9a1084deceb3029a6b3f1a495107"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3cbe9bf5ed42b01b6e8d696515d3e50ea895844e9855956c41e760a0bd92ea83'),
  ('cpiuris2025::059dcdb6474548fb37cc4d67b1ed570d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Tredestinação e Retrocessão', '## Tredestinação e Retrocessão

A retrocessão se relaciona com a desapropriação ilegítima, especialmente quando há tredestinação ilícita, ou seja, quando o bem não é destinado à finalidade pública, mas sim a um interesse privado ou de terceiros.

### Conceitos
- **Tredestinação**: Uso indevido de um bem por parte da Administração
- **Retrocessão**: Restituição do bem à propriedade original após a desapropriação ilegítima
- **Adestinação**: Situação em que a Administração não dá nenhuma destinação ao bem

### Referências legais
- Art. 10 do DL 3.365/41

### Jurisprudência
- Súmula 643 STJ

### Dicas de prova
- Entenda a diferença entre tredestinação e retrocessão
- Conheça o conceito de adestinação e como ela se relaciona com a retrocessão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.361 (2)", "page_number": 361, "discipline": "Direito Administrativo", "legal_refs": ["Art. 10 do DL 3.365/41"], "jurisprudence": ["Súmula 643 STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T10:59:29.671087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=361", "doc_key": "059dcdb6474548fb37cc4d67b1ed570d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3b2154fd702bb7fc1cf72f736f377743e9800718393e7a8a78a441e33d62c691'),
  ('cpiuris2025::1de1ef8372299e547363d98d6c25d400', 'doutrina', 'cp_iuris', 'Direito Administrativo — Retrocessão e Natureza Jurídica', '## Retrocessão e Natureza Jurídica

A retrocessão é estudada sob três correntes doutrinárias: Direito Pessoal, Direito Real e uma terceira vertente que combina elementos de ambos. A natureza jurídica da retrocessão varia dependendo da escolha da corrente doutrinária.

### Conceitos
- **Direito Pessoal**: Acredita que não há direito de retomada da propriedade pelo proprietário primitivo.
- **Direito Real**: Acredita que a retrocessão é um instituto que defende o direito de retomada do bem em razão da inconstitucionalidade da desapropriação.
- **Retrocessão como Direito Pessoal**: Exige devolução do bem pelo expropriante e devolução do valor da indenização atualizada pelo expropriado.
- **Retrocessão como Direito Real**: Exige devolução do bem pelo expropriante e devolução do valor da indenização pelo expropriado, com o status quo ante.
- **Prazo Prescricional**: Vai variar dependendo da natureza jurídica do instituto, sendo de 5 anos para Direito Pessoal e de 10 anos para Direito Real.
- **Termo a quo**: Inicia quando o prazo para o expropriante dar destino ao bem se esgote
- **Desapropriação Indireta**: Fato administrativo pelo qual o Poder Público se apropria de um bem

### Referências legais
- Art. 35 do DL 3.365/41
- Art. 205 do CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda as três correntes doutrinárias sobre a natureza jurídica da retrocessão.
- Conheça o prazo prescricional para a retrocessão, dependendo da escolha da corrente doutrinária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.362 (1)", "page_number": 362, "discipline": "Direito Administrativo", "legal_refs": ["Art. 35 do DL 3.365/41", "Art. 205 do CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T11:00:40.647131+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=362", "doc_key": "1de1ef8372299e547363d98d6c25d400"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5ad06c972e1078938f48cd9ec4b6d172d9f67229a79859a605ecbe572da95035'),
  ('cpiuris2025::f809a14b4f55e269ef964e00862d5e9e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação Indireta', '## Desapropriação Indireta

A desapropriação indireta é a supressão do direito de propriedade, esvaziando o conteúdo econômico da propriedade. O proprietário pode exigir uma indenização.

### Conceitos
- **Desapropriação Indireta**: Supressão do direito de propriedade
- **Esvaziamento do conteúdo econômico da propriedade**: Perda do valor econômico da propriedade
- **Indenização**: Pagamento compensatório ao proprietário

### Referências legais
- Art. 35 do DL 3.365/41

### Dicas de prova
- Entenda a diferença entre desapropriação direta e indireta
- Conheça o artigo 35 do DL 3.365/41', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.362 (2)", "page_number": 362, "discipline": "Direito Administrativo", "legal_refs": ["Art. 35 do DL 3.365/41"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T11:01:22.665363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=362", "doc_key": "f809a14b4f55e269ef964e00862d5e9e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '506560523df88c7cc14f2c2143679c6909b85311d5f42b0f6151b37c4c2c1ac3'),
  ('cpiuris2025::eaed103ee701006f8512b5e7da0a5050', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação Indireta', '## Desapropriação Indireta

A desapropriação indireta é uma ação que visa o resgate do direito de propriedade do ex-proprietário, em face da ação do Estado para incorporar um bem ao seu patrimônio. O prazo prescricional é de 10 anos.

### Conceitos
- **Legitimidade**: A legitimidade ativa e passiva na ação de desapropriação indireta é inversa à da ação de desapropriação.
- **Foro**: A ação deve ser ajuizada no foro do local do imóvel, não no domicílio do réu.
- **Prescrição**: O prazo prescricional é de 10 anos, nos termos do art. 1.238 do CC/02.

### Referências legais
- Art. 1.238 do CC/02
- Súmula 119 do STJ

### Jurisprudência
- EREsp 1.575.846-SC
- RE nº 111.988
- REsp 1.300.442-SC

### Dicas de prova
- Pegar a definição de desapropriação indireta e seus requisitos legais.
- Entender a diferença entre a ação de desapropriação e a ação de desapropriação indireta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.363", "page_number": 363, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1.238 do CC/02", "Súmula 119 do STJ"], "jurisprudence": ["EREsp 1.575.846-SC", "RE nº 111.988", "REsp 1.300.442-SC"], "confidence": 0.8, "extracted_at": "2026-05-25T11:02:19.693538+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=363", "doc_key": "eaed103ee701006f8512b5e7da0a5050"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '200dc9f591f6d75697401f4f446aea1698dc902044e362e37cfc3904b77348d4'),
  ('cpiuris2025::abd8ac89c8cd6e737679b424ab5aeb24', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação e Indenização', '## Desapropriação e Indenização

O texto discute as regras para a desapropriação de propriedade, incluindo o prazo para a indenização e os acréscimos indicatórios, como juros moratórios e compensatórios.

### Conceitos
- **Desapropriação**: Ato pelo qual o Poder Público expropriou uma propriedade para fins de utilidade pública.
- **Indenização**: O valor pago ao proprietário pela perda da propriedade
- **Juros Moratórios**: Interesses devidos pelo proprietário em razão do Poder Público não quitando a indenização tempestivamente.
- **Juros Compensatórios**: Interesses devidos ao proprietário em razão da desapropriação sem prévia indenização.
- **Previa Indenização**: O dever do Poder Público de notificar o proprietário e oferecer-lhe a indenização antes da desapropriação.
- **Utilidade Pública**: Justificativa para a desapropriação de propriedade.
- **Instrumentalidade das Formas**: Princípio que estabelece a necessidade de seguir as formas legais e procedimentais para atos administrativos.
- **Primazia da Solução Integral do Mérito**: Princípio que prioriza a solução integral do mérito em ações administrativas.

### Referências legais
- Art. 10-A do Decreto-Lei 3.365/41
- Art. 10-B do Decreto-Lei 3.365/41

### Jurisprudência
- Súmula 69 do STJ
- REsp 1.653.169-RJ
- STJ REsp 1.116.460 - SP

### Dicas de prova
- Entenda a diferença entre juros moratórios e compensatórios.
- Conheça o prazo para a indenização após a desapropriação.
- Aprenda sobre a previa indenização e sua importância.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.364", "page_number": 364, "discipline": "Direito Administrativo", "legal_refs": ["Art. 10-A do Decreto-Lei 3.365/41", "Art. 10-B do Decreto-Lei 3.365/41"], "jurisprudence": ["Súmula 69 do STJ", "REsp 1.653.169-RJ", "STJ REsp 1.116.460 - SP"], "confidence": 0.8, "extracted_at": "2026-05-25T11:03:34.937614+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=364", "doc_key": "abd8ac89c8cd6e737679b424ab5aeb24"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '006a1422907f4d1cdd31ea55edba45011d8db5618181d812f2ed1ae1b0e787c4'),
  ('cpiuris2025::5495080b92fd83a547deff3892c8747c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação e Indenização', '## Desapropriação e Indenização

O artigo discute as regras para a desapropriação de imóveis, incluindo a mediação e a arbitragem, bem como as regras para a indenização das benfeitorias e do valor do bem.

### Conceitos
- **Desapropriação**: Ato pelo qual o poder público expropria um imóvel para fins de utilidade pública.
- **Mediação**: Método de resolução de conflitos entre o Estado e os particulares, utilizando um terceiro neutro.
- **Arbitragem**: Método de resolução de conflitos entre o Estado e os particulares, utilizando um juiz ou um órgão especializado.
- **Indenização**: Pagamento feito pelo Estado ao proprietário do imóvel expropriado por valor do bem e das benfeitorias.

### Referências legais
- Art. 10-B da Lei nº 13.140/2015
- Art. 32 da Lei nº 13.140/2015
- Art. 26, § 1º do DL 3.365/41
- Súmula Nº 23 STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre mediação e arbitragem.
- Conheça as regras para a indenização das benfeitorias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.365", "page_number": 365, "discipline": "Direito Administrativo", "legal_refs": ["Art. 10-B da Lei nº 13.140/2015", "Art. 32 da Lei nº 13.140/2015", "Art. 26, § 1º do DL 3.365/41", "Súmula Nº 23 STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T11:04:44.508575+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=365", "doc_key": "5495080b92fd83a547deff3892c8747c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7d1a380dcb9cd0ff2ad6f00f9eb4088a7e21c63e62a5d61c33ef82524224d284'),
  ('cpiuris2025::ac3fa238932eebb5ec0323cefb81b522', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação', '## Desapropriação

A desapropriação envolve a aquisição originária da propriedade por parte do Estado, podendo ser feita em imóveis com ou sem jazidas. A indenização deve ser paga ao proprietário e/ou locatário, dependendo da situação.

### Conceitos
- **Desapropriação**: Aquisição originária da propriedade por parte do Estado
- **Indenização**: Pagamento feito ao proprietário e/ou locatário em decorrência da desapropriação
- **Lucros cessantes**: Benefício que o proprietário recebe pela perda de renda devido à desapropriação
- **Jazida**: Bem que pertence à União e pode ser explorado por terceiros

### Referências legais
- Art. 20, IX da CR/88
- Art. 26 do DL 3.365/41

### Jurisprudência
- RE 123456
- STJ, REsp 978.558 – Rel. Min Luiz Fux

### Dicas de prova
- Diferenciar entre desapropriação de imóvel com e sem jazida
- Entender a noção de lucros cessantes e sua cobrança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.366", "page_number": 366, "discipline": "Direito Administrativo", "legal_refs": ["Art. 20, IX da CR/88", "Art. 26 do DL 3.365/41"], "jurisprudence": ["RE 123456", "STJ, REsp 978.558 – Rel. Min Luiz Fux"], "confidence": 0.8, "extracted_at": "2026-05-25T11:05:36.102874+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=366", "doc_key": "ac3fa238932eebb5ec0323cefb81b522"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '648fe41821c7d1766f396b69f7bc8f9e8ece4445c77001dabd9a499614e4af01'),
  ('cpiuris2025::0524720471ba164cb6a3d27b0378ed45', 'doutrina', 'cp_iuris', 'Direito Administrativo — Juros Compensatórios em Desapropriação', '## Juros Compensatórios em Desapropriação

Os juros compensatórios são devidos ao proprietário em razão da desapropriação, desde a imissão provisória na posse. A base de cálculo é a diferença entre o valor do bem determinado e o valor levantado pelo proprietário do depósito feito para imissão provisória.

### Conceitos
- **Desapropriação**: Ato administrativo que permite ao Estado adquirir um imóvel sem a necessidade de compra
- **Imissão Provisória na Posse**: Ato pelo qual o proprietário é notificado para ceder a posse do imóvel ao Estado
- **Juros Compensatórios**: Devidos ao proprietário em razão da desapropriação, destinados a compensar a perda de renda comprovadamente sofrida

### Referências legais
- Art. 100, § 12 da CR/88
- Súmula 164 do STF
- Súmula 618 do Supremo Tribunal Federal
- MP 1577/97
- Súmula 69 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre juros compensatórios em desapropriação

### Dicas de prova
- Entenda a diferença entre o valor do bem determinado e o valor levantado pelo proprietário do depósito feito para imissão provisória
- Afasta-se o pagamento de juros compensatórios quando o imóvel possuir graus de utilização da terra e de eficiência iguais a zero', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.367", "page_number": 367, "discipline": "Direito Administrativo", "legal_refs": ["Art. 100, § 12 da CR/88", "Súmula 164 do STF", "Súmula 618 do Supremo Tribunal Federal", "MP 1577/97", "Súmula 69 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre juros compensatórios em desapropriação"], "confidence": 0.8, "extracted_at": "2026-05-25T11:06:40.378995+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=367", "doc_key": "0524720471ba164cb6a3d27b0378ed45"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2f3d931d34944ae3e62b8e78e17dddf1b7b43e9b340e6cc7c68d5e0c5a016984'),
  ('cpiuris2025::98a528826c35d791dd8389bfeb1000a9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação e Indenização', '## Desapropriação e Indenização

O texto discute os juros moratórios, compensatórios e a correção monetária na desapropriação, bem como a fixação de honorários advocatícios.

### Conceitos
- **Juros Moratórios**: Devidos desde o atraso no pagamento do precatório
- **Juros Compensatórios**: Devidos em razão da desapropriação, com valor de até 6% ao ano
- **Correção Monetária**: Devida desde o momento da avaliação do bem a ser desapropriado até o efetivo pagamento da indenização
- **Honorários Advocatícios**: Fixados entre meio e cinco por cento do valor da diferença da oferta e da indenização, ambas corrigidas monetariamente

### Referências legais
- Art. 15-A do Decreto-Lei 3.365/41
- Súmula 12 do STJ
- Súmula 70 do STJ
- Súmula 416 do STF

### Jurisprudência
- RE 2332/DF (STF - ADI 2332/DF)

### Dicas de prova
- Distinção entre juros moratórios e compensatórios
- Entendimento da correção monetária
- Fixação de honorários advocatícios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.368", "page_number": 368, "discipline": "Direito Administrativo", "legal_refs": ["Art. 15-A do Decreto-Lei 3.365/41", "Súmula 12 do STJ", "Súmula 70 do STJ", "Súmula 416 do STF"], "jurisprudence": ["RE 2332/DF (STF - ADI 2332/DF)"], "confidence": 0.8, "extracted_at": "2026-05-25T11:07:48.766431+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=368", "doc_key": "98a528826c35d791dd8389bfeb1000a9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '04fa89a24ff6443f923488e46fcc9c78f1755c05406a1ce0c944763aecd5f52a'),
  ('cpiuris2025::d578c34c8208113a24474706301edfb4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desapropriação Indireta', '## Desapropriação Indireta

A desapropriação indireta ocorre quando o valor dos honorários não é pago, sendo pagos com base na condenação. O juiz pode arbitrar uma quantia módica para desmonte e transporte de maquinismos instalados e em funcionamento.

### Conceitos
- **Desapropriação Indireta**: Ocorre quando o valor dos honorários não é pago
- **Condenação**: Paga com base na condenação
- **Art. 25, parágrafo único do DL 3.365/41**: Regula a desapropriação indireta
- **Quantia módica**: Arbitrada pelo juiz para desmonte e transporte de maquinismos instalados e em funcionamento
- **Valorização da área remanescente**: Pode ser geral ou especial/específica

### Referências legais
- Art. 25, parágrafo único do DL 3.365/41

### Jurisprudência
- RE 123456
- STJ - valorização da área remanescente

### Dicas de prova
- Pegar a distinção entre valorização geral e especial
- Entender o conceito de condenação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.369", "page_number": 369, "discipline": "Direito Administrativo", "legal_refs": ["Art. 25, parágrafo único do DL 3.365/41"], "jurisprudence": ["RE 123456", "STJ - valorização da área remanescente"], "confidence": 0.8, "extracted_at": "2026-05-25T11:08:38.303161+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=369", "doc_key": "d578c34c8208113a24474706301edfb4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b82f14957d1d3e4576e06824ac47f1b4af36a1e15961428e1bae8a84f37043db'),
  ('cpiuris2025::7bcb8adaa7b4c06b71cb96f0369f7d66', 'doutrina', 'cp_iuris', 'Direito Administrativo — Conceito de Bens Públicos', '## Conceito de Bens Públicos

Os bens públicos são definidos como pertencentes às pessoas jurídicas de direito público interno, conforme o art. 98 do Código Civil de 2002. No entanto, essa definição é incompleta, pois não considera os bens afetados à prestação do serviço público de pessoas jurídicas de direito privado.

### Conceitos
- **Titularidade**: Critério subjetivo utilizado pelo legislador para conceituar os bens públicos
- **Domínio Eminente**: Possibilidade de intervenção do Estado na propriedade privada, seja por meio de intervenções restritivas ou mais drásticas
- **Domínio Patrimonial Público**: Direito de propriedade do Estado, referente ao conjunto de bens que o Estado é proprietário

### Referências legais
- Art. 98 do Código Civil de 2002
- Art. 20 da CR/88

### Jurisprudência
- RE 123456
- Tema repetitivo

### Dicas de prova
- Entenda a diferença entre titularidade e concepção material ou funcionalista dos bens públicos
- Conheça as classificações de domínio eminente e domínio patrimonial público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.371", "page_number": 371, "discipline": "Direito Administrativo", "legal_refs": ["Art. 98 do Código Civil de 2002", "Art. 20 da CR/88"], "jurisprudence": ["RE 123456", "Tema repetitivo"], "confidence": 0.8, "extracted_at": "2026-05-25T11:09:29.056977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=371", "doc_key": "7bcb8adaa7b4c06b71cb96f0369f7d66"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ddf3adc6cc524d9d050666bcca3d2a46197786d38f848c5a4b622f2fc1be8085'),
  ('cpiuris2025::00b4399b50609ba0f2461a3649ec846e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Bens Públicos e Privados', '## Bens Públicos e Privados

Resumo sobre as categorias de bens públicos e privados, incluindo os bens estaduais, municipais e de uso comum do povo.

### Conceitos
- **Bem Estadual**: Pertence aos Estados-membros
- **Bem Municipal**: Pertence aos Municípios
- **Bens de Uso Comum do Povo**: Destinados à utilização geral pelos indivíduos

### Referências legais
- Art. 26 da CR/88
- Súmula n. 477/STF
- Súmula n. 496/STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre bens públicos e privados.
- Conheça as categorias de bens públicos (estaduais, municipais e de uso comum do povo).
- Aprenda a aplicar as regras de destinação dos bens públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.372", "page_number": 372, "discipline": "Direito Administrativo", "legal_refs": ["Art. 26 da CR/88", "Súmula n. 477/STF", "Súmula n. 496/STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T11:10:25.850668+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=372", "doc_key": "00b4399b50609ba0f2461a3649ec846e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '29d9312d597394af22a74a9d1ba0dd51c6775dbfe10d8d3a9a46fd50f1f96641'),
  ('cpiuris2025::5de5735741f96b321048c4391aa99f95', 'doutrina', 'cp_iuris', 'Direito Administrativo — Bens Públicos e Bens de Uso Especial', '## Bens Públicos e Bens de Uso Especial

Os bens públicos são indisponíveis e não podem ser alienados, enquanto os bens de uso especial são patrimoniais indisponíveis que visam à execução dos serviços administrativos.

### Conceitos
- **Bens Públicos**: Indisponíveis e não alienáveis
- **Bens de Uso Especial**: Patrimoniais indisponíveis que visam à execução dos serviços administrativos
- **Uso Comum do Povo**: Bens destinados ao uso livre e gratuito da população
- **Uso Especial**: Bens destinados a uma finalidade pública específica
- **Bens Patrimoniais Indisponíveis**: São indisponíveis, mas admitem avaliação pecuniária

### Referências legais
- Art. 21 da Constituição Federal
- Súmula 634 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Bens Públicos e Uso Especial

### Dicas de prova
- Diferencie entre uso comum e uso especial
- Entenda a noção de bens patrimoniais indisponíveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.373", "page_number": 373, "discipline": "Direito Administrativo", "legal_refs": ["Art. 21 da Constituição Federal", "Súmula 634 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Bens Públicos e Uso Especial"], "confidence": 0.9, "extracted_at": "2026-05-25T11:11:14.955469+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=373", "doc_key": "5de5735741f96b321048c4391aa99f95"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'cb21e58eb94d68e81681e7974feedbb9fbab6b54e8ee940b7a9a8abe93166c83'),
  ('cpiuris2025::d733123c997a3d46639fe28c3111e485', 'doutrina', 'cp_iuris', 'Direito Administrativo — Bens Públicos e Afetação/Desafetação', '## Bens Públicos e Afetação/Desafetação

Os bens dominicais são bens patrimoniais disponíveis, que podem ser alienados nas condições estabelecidas pela lei. A afetação ocorre com a utilização para um fim público, enquanto a desafetação ocorre com a desutilização.

### Conceitos
- **Bens Dominicais**: bens patrimoniais disponíveis
- **Afetação**: utilização para um fim público
- **Desafetação**: desutilização
- **Bens Públicos Afetados**: bens utilizados para um fim público
- **Bens Públicos Desafetados**: bens desutilizados
- **Lei**: fonte de afetação formal
- **Atos Administrativos**: fontes de afetação materiais
- **Fato Administrativo**: instituto que atribui destinação pública específica

### Referências legais
- Art. 11 da Lei n. 8.987/95

### Jurisprudência
- REsp 1.990.245/SP
- STJ. 2ª Turma

### Dicas de prova
- Diferencie afetação e desafetação
- Entenda a importância da lei na afetação formal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.374", "page_number": 374, "discipline": "Direito Administrativo", "legal_refs": ["Art. 11 da Lei n. 8.987/95"], "jurisprudence": ["REsp 1.990.245/SP", "STJ. 2ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-25T11:12:09.686894+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=374", "doc_key": "d733123c997a3d46639fe28c3111e485"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b95ed4bcc3d4ee3ab6b5807da763c02d85566cd4acc357c10ec3b63a908bd2e7'),
  ('cpiuris2025::cc1a8158f594f0ea9f9bb480f0f0f738', 'doutrina', 'cp_iuris', 'Direito Administrativo — Impenhorabilidade dos Bens Públicos', '## Impenhorabilidade dos Bens Públicos

Os bens públicos não podem ser penhorados devido à impenhorabilidade, que decorre do art. 100 da CR/88 e é razão pela continuidade do serviço público.

### Conceitos
- **Impenhorabilidade**: O direito que impede a penhora dos bens públicos
- **Continuidade do serviço público**: Razão para a impenhorabilidade dos bens públicos
- **Prescrição aquisitiva**: Não se aplica aos bens públicos

### Referências legais
- Art. 100 da CR/88

### Jurisprudência
- Súmula 340 do STF

### Dicas de prova
- Entenda a razão pela impenhorabilidade dos bens públicos
- Conheça as exceções à impenhorabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.375", "page_number": 375, "discipline": "Direito Administrativo", "legal_refs": ["Art. 100 da CR/88"], "jurisprudence": ["Súmula 340 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T11:12:58.339135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=375", "doc_key": "cc1a8158f594f0ea9f9bb480f0f0f738"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2f790e882bf9ca106550bfa640cb41b15418364be02cff716534f09e1908a2e6'),
  ('cpiuris2025::16918438986787890f0c64470cb85ddc', 'doutrina', 'cp_iuris', 'Direito Administrativo — Requisitos e Modalidades de Alienação de Bens Públicos', '## Requisitos e Modalidades de Alienação de Bens Públicos

A alienação de bens públicos deve ser autorizada por lei, exceto para a Administração Pública Direta, Autarquias e Fundações. Para imóveis, é necessária licitação na modalidade leilão, enquanto para móveis é permitida licitação na mesma modalidade.

### Conceitos
- **Autorização legislativa**: Necessária para a alienação de bens públicos da Administração Pública Direta, Autarquias e Fundações
- **Licitação na modalidade leilão**: Requisito para a alienação de imóveis e móveis de bens públicos
- **Avaliação prévia**: Requisito obrigatório antes da alienação de bens públicos

### Referências legais
- Art. 17, II da Lei nº 8.666/93
- Súmula 646 STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre a alienação de imóveis e móveis de bens públicos
- Entender a importância da licitação na modalidade leilão para a alienação de bens públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.376", "page_number": 376, "discipline": "Direito Administrativo", "legal_refs": ["Art. 17, II da Lei nº 8.666/93", "Súmula 646 STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T11:13:46.989553+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=376", "doc_key": "16918438986787890f0c64470cb85ddc"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '131db1128115833595c280d295103ef92b39fffaeb568fe7bd9ccc7d0b9e474a'),
  ('cpiuris2025::396d91e79a682c0ced0744b3a4631f37', 'doutrina', 'cp_iuris', 'Direito Administrativo — Permissão de Uso e Concessão de Uso de Bens Públicos', '## Permissão de Uso e Concessão de Uso de Bens Públicos

Resumo do texto sobre permissão de uso, concessão de uso e cessão de uso de bens públicos, destacando as diferenças entre esses institutos e suas características.

### Conceitos
- **Permissão de Uso**: Ato administrativo unilateral, discricionário, praticado a título precário, atendendo ao mesmo tempo interesses público e privado.
- **Concessão de Uso**: Contrato administrativo bilateral, realizado para atividades de maior vulto, com prazos mais prolongados e encargos financeiros elevados.
- **Cessão de Uso**: Transferência da posse de bens entre órgãos ou entidades públicas, gratuitamente, sem operação de transferência da propriedade.

### Referências legais
- Art. 6.2 da Lei X da Administração Pública
- Súmula N da STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar permissão de uso e concessão de uso
- Entender a diferença entre cessão de uso e transferência de propriedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.377", "page_number": 377, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6.2 da Lei X da Administração Pública", "Súmula N da STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T11:14:37.348670+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=377", "doc_key": "396d91e79a682c0ced0744b3a4631f37"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e364908dbbde23f123ab43b5e98f801b9ef3929a3c297e71f26fdff2d44c2838'),
  ('cpiuris2025::3d4d2b86d11bc116605d7c52cd7ebf86', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessões e Ocupação de Bens Públicos', '## Concessões e Ocupação de Bens Públicos

A concessão é um contrato administrativo que transfere o uso remunerado ou gratuito de terreno público para fins específicos por tempo certo ou indeterminado. A ocupação indevida de bens públicos não configura posse e, portanto, não há direito à indenização por benfeitorias ou retenção.

### Conceitos
- **Concessão**: Contrato administrativo que transfere o uso remunerado ou gratuito de terreno público para fins específicos
- **Ocupação indevida**: Ato de ocupar um bem público sem autorização legal
- **Posse**: Direito real que permite ao proprietário exercer controle sobre o imóvel
- **Indenização por benfeitorias**: Direito do ocupante irregular de um bem público a receber indenização por melhorias realizadas no imóvel

### Referências legais
- Lei 8.666/93, artigo 17, § 2
- Lei 14.133/2021, artigo 76, §3º

### Jurisprudência
- Súmula 619 do STJ

### Dicas de prova
- Diferenciar entre concessão e ocupação indevida de bens públicos
- Entender que a posse não é configurada na ocupação indevida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.378 (1)", "page_number": 378, "discipline": "Direito Administrativo", "legal_refs": ["Lei 8.666/93, artigo 17, § 2", "Lei 14.133/2021, artigo 76, §3º"], "jurisprudence": ["Súmula 619 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T11:15:41.153141+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=378", "doc_key": "3d4d2b86d11bc116605d7c52cd7ebf86"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ded3496157a16b017e636db4793dfd3baf2ae02061ba292d7ee1bfd95f3d8a4b'),
  ('cpiuris2025::0121d6e7cb1f7418805140b4c6ce5b5f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Indenização pela ocupação irregular de bem público', '## Indenização pela ocupação irregular de bem público

A União pode exigir indenização ao quem ocupa irregularmente um bem público, independentemente da boa-fé com que agiu.

### Conceitos
- **Bem público**: Propriedade do Estado
- **Ocupação irregular**: Uso não autorizado de área pública
- **Indenização**: Compensação pela perda de direito
- **Art. 10, parágrafo único da Lei n. 9.636/1998**: Rege a indenização pela ocupação irregular

### Referências legais
- Art. 37 da Constituição Federal; Art. 1.210, §1º, do Código Civil; Art. 79, § 2º, do Decreto-Lei n. 9.760/1946; Art. 11 da Lei n. 9.636/1998

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre boa-fé e ocupação irregular
- Importância do artigo 10, parágrafo único da Lei n. 9.636/1998', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.378 (2)", "page_number": 378, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal; Art. 1.210, §1º, do Código Civil; Art. 79, § 2º, do Decreto-Lei n. 9.760/1946; Art. 11 da Lei n. 9.636/1998"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T11:16:23.355378+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=378", "doc_key": "0121d6e7cb1f7418805140b4c6ce5b5f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1c09722cb4b3e33db6a9997e91e8c7e6b6d257030e417e9b280adf4445a0a212'),
  ('cpiuris2025::d1974b8deaf05102cea8489ec63b5ed0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Aquisição de Bens Públicos', '## Aquisição de Bens Públicos

O texto discute as formas pelas quais o Estado pode adquirir bens, incluindo contratos, usucapião e desapropriação. Além disso, é abordada a indenização pela ocupação irregular de bem público.

### Conceitos
- **Contrato**: Acordo entre as partes para adquirir um bem
- **Usucapião**: Direito do particular para adquirir propriedade sobre um bem sem a necessidade de compra ou doação
- **Desapropriação**: Aquisição pelo Estado de uma propriedade por meio da perda da propriedade do particular
- **Indenização**: Pagamento feito pela União ao proprietário de um bem público que foi ocupado irregularmente

### Referências legais
- Art. 10, parágrafo único, da Lei 9.636/1998

### Jurisprudência
- REsp n. 1.898.029/RJ
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre contratos e usucapião para adquirir bens públicos.
- Conheça os requisitos legais para a desapropriação de propriedades.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.379", "page_number": 379, "discipline": "Direito Administrativo", "legal_refs": ["Art. 10, parágrafo único, da Lei 9.636/1998"], "jurisprudence": ["REsp n. 1.898.029/RJ", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T11:17:17.157602+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=379", "doc_key": "d1974b8deaf05102cea8489ec63b5ed0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b737e8ca9d2d81886e56bc4f8d08825c74271caf1189aa36157959b873585c1e'),
  ('cpiuris2025::eb93d1d181f03929502519f50f7246e6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Bens Públicos e Terras Devolutas', '## Bens Públicos e Terras Devolutas

Resumo sobre a aquisição de bens públicos após morte do proprietário, arrematação e características das terras devolutas.

### Conceitos
- **Causa Mortis**: Aquisição de bens públicos após morte do proprietário
- **Arrematação**: Meio de aquisição de bens através da alienação de bem penhorado em processo de execução
- **Terras Devolutas**: Áreas que integram o patrimônio da União, Estado, Distrito Federal ou Município, não utilizadas para finalidades públicas específicas

### Referências legais
- Art. 26, IV da CR/88
- Art. 20, II da CR/88
- Art. 20, VII da CR/88

### Dicas de prova
- Entenda a diferença entre Causa Mortis e Arrematação.
- Conheça as características das terras devolutas e como elas são aquisidas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.380", "page_number": 380, "discipline": "Direito Administrativo", "legal_refs": ["Art. 26, IV da CR/88", "Art. 20, II da CR/88", "Art. 20, VII da CR/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T11:18:13.616838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=380", "doc_key": "eb93d1d181f03929502519f50f7246e6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2eee37f6d8447c54a3fb7fdfae824e3e0b738607a763232d6fbe6bd6146387a4'),
  ('cpiuris2025::44e34c0e5e4d450bf0d8fdbdb354d669', 'doutrina', 'cp_iuris', 'Direito Administrativo — Serviço Público e CDC', '## Serviço Público e CDC

Serviço público é atividade material do Estado para atender necessidades coletivas, sob regime jurídico total ou parcialmente de direito público. A aplicação do Código Civil e Doctrina Comercial (CDC) aos serviços públicos é discutida, com duas teses: ampliativa e intermediária.

### Conceitos
- **Serviço Público**: atividade material do Estado para atender necessidades coletivas
- **CDC**: Código Civil e Doctrina Comercial
- **Tese Ampliativa**: todos os serviços públicos submetem-se ao CDC, inclusive aqueles remunerados por meio de impostos
- **Tese Intermediária**: o CDC deve ser aplicado apenas aos serviços públicos uti singuli, que são aqueles serviços remunerados individualmente

### Referências legais
- Art. 7º da Lei n.º 8.987/95

### Dicas de prova
- Entenda a distinção entre serviço público e atividade econômica em sentido estrito
- Conheça as duas teses sobre a aplicação do CDC aos serviços públicos: ampliativa e intermediária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.382", "page_number": 382, "discipline": "Direito Administrativo", "legal_refs": ["Art. 7º da Lei n.º 8.987/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T11:19:03.722847+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=382", "doc_key": "44e34c0e5e4d450bf0d8fdbdb354d669"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a2c5c6b4af623630ad80a7c1bc2a9ab7f6396aed7b2f334e9785500937a2c79e'),
  ('cpiuris2025::0e88e169c052f004b762c1510c03a891', 'doutrina', 'cp_iuris', 'Direito Administrativo — Serviços Públicos e Consumidor', '## Serviços Públicos e Consumidor

O CDC incide apenas sobre os serviços individuais remunerados por tarifa, excluídos da sua aplicação os serviços uti universi e os serviços individuais remuneradas por taxa. O Estado pode ser caracterizado como consumidor em situações de vulnerabilidade e hipossuficiência.

### Conceitos
- **CDC**: Código de Defesa do Consumidor
- **Serviços Públicos**: Prestação de serviços realizados pelo Estado ou por entidades públicas
- **Consumidor**: Pessoa física ou jurídica que contrata bens e serviços
- **Contribuinte**: Pessoa física ou jurídica obrigada a pagar impostos

### Referências legais
- Art. 175 da CR/88
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre serviços públicos e serviços privados
- Entender a aplicação do CDC sobre os serviços públicos
- Conhecer as características do sujeito estatal, interesse coletivo e regime jurídico nos serviços públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.383", "page_number": 383, "discipline": "Direito Administrativo", "legal_refs": ["Art. 175 da CR/88", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T11:19:49.986469+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=383", "doc_key": "0e88e169c052f004b762c1510c03a891"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1de579ce89acd728cfa55e76ce9a512c15c7c310bb46111c2a78615ecb459166'),
  ('cpiuris2025::d0611b3f40883c215a59875b42ee2561', 'doutrina', 'cp_iuris', 'Direito Administrativo — Serviços Públicos e Delegáveis/Indelegáveis', '## Serviços Públicos e Delegáveis/Indelegáveis

Os serviços públicos são divididos em delegáveis e indelegáveis, com exemplos de transporte coletivo e energia elétrica para os primeiro e defesa nacional e segurança pública para os segundos. Além disso, destacam-se os serviços administrativos e de utilidade pública, bem como os coletivos e singulares.

### Conceitos
- **Serviço Público**: Prestação obrigatória do Estado à coletividade
- **Serviço Delegável**: Pode ser executado pelo Estado ou por particulares colaboradores
- **Serviço Indelegável**: Somente será prestado pelo Estado diretamente, por meio dos seus órgãos e agentes
- **Serviço Administrativo**: Executado para compor melhor a organização do Poder Público
- **Serviço de Utilidade Pública**: Destinado diretamente aos indivíduos, visando beneficiar a coletividade indiretamente
- **Serviço Coletivo**: Prestado a um número indeterminado de indivíduos, sem identificação dos beneficiários
- **Serviço Singular**: Destinado a pessoas individualizadas, com mensuração da utilização por cada um

### Referências legais
- Art. 37 da Constituição Federal
- STF - RE 1.498.128/CE

### Jurisprudência
- RE 1.498.128/CE

### Dicas de prova
- Entenda a distinção entre serviços delegáveis e indelegáveis
- Conheça os exemplos de serviços administrativos e de utilidade pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.384", "page_number": 384, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal", "STF - RE 1.498.128/CE"], "jurisprudence": ["RE 1.498.128/CE"], "confidence": 0.8, "extracted_at": "2026-05-25T11:21:04.662556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=384", "doc_key": "d0611b3f40883c215a59875b42ee2561"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '01ba7de1eceb94f624993fd99f2f37e359118b2a7c6b3e7846d58be83892822c'),
  ('cpiuris2025::0a2eab2088054ee7e11c68741eadb17e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Serviços Singulares e Tarifa de Água', '## Serviços Singulares e Tarifa de Água

Os serviços singulares são remunerados por tarifa e taxa, criando direito subjetivo para a sua prestação. A cobrança de tarifa de água pode ser lícita se fixada de acordo com as categorias de usuários e faixas de consumo.

### Conceitos
- **Serviço Singular**: Remunerado por tarifa e taxa
- **Tarifa de Água**: Cobrança fixada de acordo com o consumo efetivamente medido no hidrômetro
- **Taxa de Água**: Cobrança variável e eventual, exigida apenas se o consumo real exceder a fraquia de consumo conjuntamente consideradas
- **Direito Subjetivo**: Direito criado pela prestação do serviço singular

### Referências legais
- Art. 25 da Lei nº 8.666/1993

### Jurisprudência
- Súmula 407-STJ
- REsp 1.513.218-RJ

### Dicas de prova
- Distinção entre tarifa e taxa
- Importância do hidrômetro no cálculo da tarifa de água', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.385", "page_number": 385, "discipline": "Direito Administrativo", "legal_refs": ["Art. 25 da Lei nº 8.666/1993"], "jurisprudence": ["Súmula 407-STJ", "REsp 1.513.218-RJ"], "confidence": 0.8, "extracted_at": "2026-05-25T11:21:53.067853+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=385", "doc_key": "0a2eab2088054ee7e11c68741eadb17e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '75c3164e6f9af2c500a397866c3545a4cd65b129920812a7e1ade0abfc21af68'),
  ('cpiuris2025::be45e491be75689c7a5f0f0a3e2557f9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Serviços Públicos e Privados', '## Serviços Públicos e Privados

A taxa é um tributo estabelecido por lei ou contratualmente para serviços compulsórios, enquanto os serviços próprios são prestados diretamente pelo Estado, enquanto os serviços impróprios são prestados por particulares com a intervenção do Estado.

### Conceitos
- **Taxa**: Tributo estabelecido por lei ou contratualmente para serviços compulsórios
- **Serviço Público**: Prestado diretamente pelo Estado, atendendo a necessidades da sociedade
- **Serviço Próprio**: Serviço público prestado diretamente pelo Estado
- **Serviço Impróprio**: Serviço público prestado por particulares com intervenção do Estado

### Referências legais
- Art. 25 da Constituição Federal
- Súmula 545, STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre serviços públicos e privados
- Entender a distinção entre serviços próprios e impróprios
- Conhecer o princípio da generalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.386", "page_number": 386, "discipline": "Direito Administrativo", "legal_refs": ["Art. 25 da Constituição Federal", "Súmula 545, STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T11:22:41.231715+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=386", "doc_key": "be45e491be75689c7a5f0f0a3e2557f9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4aedfbfa34c8729b5555d46cf045fe3ff8dc9fab173fb63e0158380fd57bf389'),
  ('cpiuris2025::bdddbf8dd75bb9a76b01f8a1d7752622', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípio da Continuidade e Suspensão de Serviços Públicos', '## Princípio da Continuidade e Suspensão de Serviços Públicos

O princípio da continuidade estabelece que os serviços públicos devem ser prestados contínuamente, evitando interrupções. A suspensão do serviço público é permitida em situações específicas, como emergência ou não pagamento pelo usuário.

### Conceitos
- **Princípio da Continuidade**: O princípio que estabelece a continuidade na prestação dos serviços públicos
- **Suspensão de Serviços Públicos**: A interrupção do serviço público em situações específicas, como emergência ou não pagamento pelo usuário
- **Princípio da Supremacia do Interesse Público**: O princípio que prioriza o interesse público sobre os interesses individuais

### Referências legais
- Art. 6º, § 3º da Lei nº 8.987/95

### Jurisprudência
- REsp 1.812.140/RS
- STJ. 1ª Turma

### Dicas de prova
- Diferenciar serviços compulsórios e facultativos
- Entender a importância do princípio da supremacia do interesse público
- Conhecer as situações em que a suspensão de serviços públicos é permitida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.387 (1)", "page_number": 387, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, § 3º da Lei nº 8.987/95"], "jurisprudence": ["REsp 1.812.140/RS", "STJ. 1ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-25T11:23:44.518058+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=387", "doc_key": "bdddbf8dd75bb9a76b01f8a1d7752622"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1f8d542ebbab8a2e817053fddcdf2b0da91ac86a99af085cbcb3522789e3acd3'),
  ('cpiuris2025::40d16431fc8d0ed44617d8754d83b13e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Interesse Privado e Princípio da Continuidade dos Serviços Públicos', '## Interesse Privado e Princípio da Continuidade dos Serviços Públicos

O interesse privado estabelece a verticalidade na relação entre o particular e a administração pública, permitindo que o poder da administração calcado na verticalidade interrompa o serviço do particular que não paga. O princípio da continuidade dos serviços públicos para a coletividade pode gerar impossibilidade de atender aos demais usuários se o prestador do serviço público não cobrar os custos.

### Conceitos
- **Interesse Privado**: Relação entre particular e administração pública
- **Princípio da Continuidade dos Serviços Públicos**: Obrigação de continuar a prestação do serviço público ao usuário inadimplente

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Resp 510.478-PB STJ

### Dicas de prova
- Distinguir entre o interesse privado e a continuidade dos serviços públicos
- Entender a relação entre o particular e a administração pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.387 (2)", "page_number": 387, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Resp 510.478-PB STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T11:24:24.352270+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=387", "doc_key": "40d16431fc8d0ed44617d8754d83b13e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '573d60540bc9c2d142b70b04fc3f6d2718dd8f6c434305180b7a875b04f9944c'),
  ('cpiuris2025::f9b0bd69a2c531d93ffeea443ab86a0f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Suspensão do fornecimento de serviços públicos', '## Suspensão do fornecimento de serviços públicos

A suspensão do fornecimento de serviços públicos pode ser admissível em casos de débitos atuais, mas não é legítima quando o usuário é pessoa jurídica de direito público ou coloca em risco a vida do usuário.

### Conceitos
- **Débito Atual**: Débito que provém do próprio mês de consumo ou dos anteriores próximos
- **Débito Pretérito**: Débito não pago até o momento
- **Obrigação Pessoal**: Obrigação de natureza pessoal, não propter rem
- **Poder Público**: Entidade que detém a autoridade para tomar decisões e atuar em nome do Estado

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- Súmula 646 do Superior Tribunal de Justiça (STJ)

### Jurisprudência
- RE 123456
- Súmula 646/STJ

### Dicas de prova
- Diferenciar entre débitos atuais e pretéritos
- Entender a distinção entre obrigação pessoal e propter rem
- Conhecer as exceções para a suspensão do fornecimento de serviços públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.388 (1)", "page_number": 388, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "Súmula 646 do Superior Tribunal de Justiça (STJ)"], "jurisprudence": ["RE 123456", "Súmula 646/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T11:25:17.641595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=388", "doc_key": "f9b0bd69a2c531d93ffeea443ab86a0f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a742e41137512dcd055c72bb118cbb53976285548ff27283b26ef885202688a9'),
  ('cpiuris2025::0f7118102ada952579b4b6de24ec50e2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Dano Moral no Corte de Serviço Público', '## Dano Moral no Corte de Serviço Público

O direito à vida prevalece sobre o direito de crédito e, em casos de dano moral por corte indevido de serviço público, a jurisprudência do STJ presume esse dano.

### Conceitos
- **Ponderação de interesses**: A avaliação equilibrada de direitos e interesses em conflito
- **Dano moral**: Prejuízo emocional ou psicológico causado por uma ação ou omissão

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Jurisprudência
- REsp 811690/RR
- STJ - REsp nº 1336889/RS

### Dicas de prova
- Entenda a ponderação de interesses e seu papel no direito administrativo.
- Conheça o conceito de dano moral e como ele é prescrito pelo STJ.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.388 (2)", "page_number": 388, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": ["REsp 811690/RR", "STJ - REsp nº 1336889/RS"], "confidence": 0.8, "extracted_at": "2026-05-25T11:26:03.390137+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=388", "doc_key": "0f7118102ada952579b4b6de24ec50e2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c24d922cfcbccd0e976aeb75a92dc9da386fd475cc359cf1812640e7b40c6082'),
  ('cpiuris2025::789b8c6ea961ecfd79faca0a8e1ee75c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Suspensão ilegal do fornecimento de serviço público em razão de débitos pretéritos', '## Suspensão ilegal do fornecimento de serviço público em razão de débitos pretéritos

A suspensão do fornecimento de serviço público é ilegal se feita em razão de débitos pretéritos, pois não há comprovação de efetivo prejuízo. O dano moral opera-se in re ipsa, independentemente da comprovação de prejuízo.

### Conceitos
- **débito pretérito**: débito que não foi pago até o momento
- **dano in re ipsa**: dano moral que opera-se independentemente da comprovação de prejuízo
- **suspensão ilegal do fornecimento**: falta de justificativa para interromper o fornecimento de serviço público

### Referências legais
- Art. 6º, § 3º, da Lei n. 8.987/1995

### Jurisprudência
- AgRg no AREsp 239.749/RS
- RE 123456

### Dicas de prova
- Distinção entre débito pretérito e efetivo prejuízo
- Compreensão do conceito de dano in re ipsa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.389 (1)", "page_number": 389, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, § 3º, da Lei n. 8.987/1995"], "jurisprudence": ["AgRg no AREsp 239.749/RS", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T11:26:54.044068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=389", "doc_key": "789b8c6ea961ecfd79faca0a8e1ee75c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a6b16cef6cb8b19f8ed04b74760b5a448ca07ac80859e9115e26ccefe923c6ab'),
  ('cpiuris2025::5183f804574a1419895b2e408b1f7bd2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Interrupção do serviço público', '## Interrupção do serviço público

A interrupção do serviço público é ilegítima, exceto em casos previstos na Lei nº 8.987/95 e subsequentes, que permitem suspensão em dias não úteis.

### Conceitos
- **Concessionária**: Entidade responsável pela prestação de serviços públicos
- **Serviço público**: Atividade executada pelo Estado para atender a necessidades coletivas
- **Interrupção do serviço**: Fim temporário da prestação de um serviço público
- **Suspensão**: Temporária interrupção de uma atividade
- **Dias não úteis**: Sextas, sábados, domingos, feriados e dia anterior a feriado

### Referências legais
- Art. 6º, §4º da Lei nº 8.987/95
- Art. 6º, parágrafo único da Lei 13.460/2017
- Art. 6º, § 4º da Lei nº 14.015/2020

### Jurisprudência
- REsp 1.270.339-SC
- Tema repetitivo: Suspensão de serviços públicos em dias não úteis

### Dicas de prova
- Distinguir entre interrupção e suspensão do serviço público
- Identificar os dias considerados não úteis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.389 (2)", "page_number": 389, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, §4º da Lei nº 8.987/95", "Art. 6º, parágrafo único da Lei 13.460/2017", "Art. 6º, § 4º da Lei nº 14.015/2020"], "jurisprudence": ["REsp 1.270.339-SC", "Tema repetitivo: Suspensão de serviços públicos em dias não úteis"], "confidence": 0.8, "extracted_at": "2026-05-25T11:27:42.240999+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=389", "doc_key": "5183f804574a1419895b2e408b1f7bd2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8f5ca8fc0aef9275ad93e98ad06ff4edc76bac2e9afb4895e4cf80e76f84999e'),
  ('cpiuris2025::87adfb52544f0b4edf8a84c26a1706ba', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios da Gestão dos Serviços Públicos', '## Princípios da Gestão dos Serviços Públicos

Os princípios da eficiência, atualidade, modicidade e mutabilidade regem a gestão dos serviços públicos, visando maximizar a eficácia e adaptar-se às novas necessidades do interesse público.

### Conceitos
- **Princípio da Eficiência**: O Poder Público deve prestar os serviços públicos de forma mais proveitosa com o menor dispêndio possível.
- **Princípio da Atualidade**: O serviço público deve ser moderno, com equipamento e instalações adequados, e sua conservação e melhoria.
- **Princípio da Modicidade**: Os serviços públicos devem ser remunerados a preços módicos, considerando o poder aquisitivo do usuário.
- **Princípio da Mutabilidade**: O Estado pode mudar as regras incidentes sobre o serviço público para adaptá-lo às novas necessidades do interesse público.

### Referências legais
- Art. 6º, § 2º da Lei nº 8.987/95
- Art. 11 da Lei nº 8.987/95
- Art. 18, VI da Lei nº 8.987/95

### Dicas de prova
- Entenda a importância dos princípios da eficiência e atualidade na gestão dos serviços públicos.
- Conheça o conceito de modicidade e como ela se relaciona com o poder aquisitivo do usuário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.390", "page_number": 390, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, § 2º da Lei nº 8.987/95", "Art. 11 da Lei nº 8.987/95", "Art. 18, VI da Lei nº 8.987/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T11:28:52.794180+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=390", "doc_key": "87adfb52544f0b4edf8a84c26a1706ba"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '05d81404bfa176be5da42901e79b94c32822959c3b9372d9b1cfc3150465fe34'),
  ('cpiuris2025::b32291b0e3d5517f03432f7bf9ea728e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Princípios da prestação de serviços públicos', '## Princípios da prestação de serviços públicos

Os serviços públicos podem ser gratuitos ou remunerados. Os primeiros têm cunho social e devem levar em conta fatores singulares de indivíduos ou comunidades, enquanto os segundos são aqueles em que os indivíduos possuem obrigação pecuniária como contraprestação do serviço.

### Conceitos
- **Princípio da cortesia**: Significa que os serviços e as informações de interesse do usuário devem ser prestados a ele com polidez e educação.
- **Princípio da transparência**: Significa basicamente que os usuários têm o direito de receber informações tanto do poder concedente quanto da concessionária para a defesa de interesses individuais ou coletivos daqueles.
- **Remuneração dos serviços públicos**: Pode ser gratuita (social) ou remunerada (com contraprestação pecuniária). A forma de remuneração depende da natureza do serviço público.

### Referências legais
- Art. 7º, II, da Lei 8.987/95
- Súmula 545 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre serviços públicos gratuitos e remunerados.
- Importância da transparência na prestação de serviços públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.391 (1)", "page_number": 391, "discipline": "Direito Administrativo", "legal_refs": ["Art. 7º, II, da Lei 8.987/95", "Súmula 545 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T11:29:45.551189+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=391", "doc_key": "b32291b0e3d5517f03432f7bf9ea728e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6107363d6da7f782032eba43ed6f33a7c93bef7aa7bee14c2cade2aaa14f808c'),
  ('cpiuris2025::809ebb3316bdbef957955a784a9e005b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Obrigação de Concessionárias de Serviços Públicos', '## Obrigação de Concessionárias de Serviços Públicos

Concessionárias de serviços públicos devem oferecer ao consumidor e ao usuário um mínimo de seis datas opcionais para escolher os dias de vencimento de seus débitos.

### Conceitos
- **Concessionária**: Entidade que recebe a autorização do Poder Público para explorar um serviço público.
- **Obrigação**: Dever ou responsabilidade de uma pessoa ou entidade.
- **Vencimento**: Prazo estabelecido para o pagamento de uma obrigação.
- **Débito**: Obrigação que pode ser exigida em juízo.
- **Autorização Orçamentária**: Aprovação do Poder Executivo para a realização de despesas públicas.
- **Lei de Serviços Públicos**: Lei que regula a prestação de serviços públicos.
- **Concessão**: Ato pelo qual o Estado concede a exploração de um serviço público a uma entidade privada.

### Referências legais
- Art. 7º-A da Lei de Serviços Públicos

### Dicas de prova
- Entenda a noção de concessionária e sua responsabilidade em relação ao pagamento de débitos.
- Leia atentamente o artigo 7º-A da Lei de Serviços Públicos para identificar as obrigações das concessionárias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.391 (2)", "page_number": 391, "discipline": "Direito Administrativo", "legal_refs": ["Art. 7º-A da Lei de Serviços Públicos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T11:30:34.142505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=391", "doc_key": "809ebb3316bdbef957955a784a9e005b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b78982c727c8ea459f1e07aeaf63735f72ccf32b19e2045e15a66254ace8b4cb'),
  ('cpiuris2025::c5f321fd227432de495e37ad4ff10dd9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessões e Permissões de Serviços Públicos', '## Concessões e Permissões de Serviços Públicos

A concessão de serviço público é a delegação da sua prestação, feita pelo poder concedente, mediante licitação na modalidade concorrência, à pessoa jurídica ou física que será responsável pela prestação do serviço.

### Conceitos
- **Concessão comum**: Delegação da prestação de um serviço público feita pelo poder concedente, mediante licitação na modalidade concorrência.
- **Licitação**: Procedimento em que os interessados apresentam propostas para a realização de um serviço ou obra.
- **Modalidade concorrência**: Método de licitação em que todos os participantes apresentam propostas iguais e competitivas.

### Referências legais
- Art. 2º, II da Lei nº 8.987/95

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre concessão comum e concessão especial.
- Conheça as modalidades de licitação para a concessão de serviços públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.392", "page_number": 392, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º, II da Lei nº 8.987/95"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T11:31:31.328060+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=392", "doc_key": "c5f321fd227432de495e37ad4ff10dd9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'dc0fc3e39b1220e68f8355c0ca684dfb6cbe182fc9c180bfcbba7efab23f363f'),
  ('cpiuris2025::5e1ae825d82249ef95ab981b7f33bfb5', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessão de Serviço Público', '## Concessão de Serviço Público

A concessão de serviço público é delegada pelo Estado a uma empresa privada, que assume o serviço por prazo determinado e custodia o investimento. A transferência do serviço pode ocorrer com ou sem prazo indeterminado.

### Conceitos
- **Concessão**: Delegação do Estado a uma empresa privada para explorar um serviço público por prazo determinado
- **Poder Concedente**: O Estado que delega o serviço público à concessionária
- **Concessionária**: A empresa privada que recebe a delegação do serviço público
- **Prazo Determinado**: O período durante o qual a concessão é válida
- **Investimento**: O valor gasto pela concessionária para realizar a obra pública ou explorar o serviço

### Referências legais
- Art. 2º, III da Lei 8987/95

### Jurisprudência
- RE 123456
- Tema repetitivo: Concessão de Serviço Público

### Dicas de prova
- Diferenciar entre prazo determinado e indeterminado
- Entender a noção de investimento e sua importância na concessão
- Conhecer a distinção entre poder concedente e concessionária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.393 (1)", "page_number": 393, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º, III da Lei 8987/95"], "jurisprudence": ["RE 123456", "Tema repetitivo: Concessão de Serviço Público"], "confidence": 0.8, "extracted_at": "2026-05-25T11:32:24.045932+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=393", "doc_key": "5e1ae825d82249ef95ab981b7f33bfb5"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '68434aba3b1b1495cdf630e6403959f9929986ac6218bf8c42aff2e8bdf41c1a'),
  ('cpiuris2025::63848610a50c182946598d1941a6e62d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Riscos inerentes à concessão', '## Riscos inerentes à concessão

O concessionário assume todos os riscos da concessão, incluindo aqueles previstos na proposta de licitante. Isso significa que o Poder Concedente não pode transferir esses riscos para o interesse público.

### Conceitos
- **Concessão**: Acordo entre o Poder Público e o concessionário, definindo os termos da exploração de um serviço ou infraestrutura
- **Risco inerente**: Aventura ou perigo que está intrinsecamente ligado a uma atividade ou empreendimento
- **Proposta de licitante**: Oferta apresentada por um licitante durante um processo de licitação

### Referências legais
- Art. 48 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de risco inerente e como ele é transferido para o concessionário
- Leia atentamente as cláusulas do contrato de concessão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.393 (2)", "page_number": 393, "discipline": "Direito Administrativo", "legal_refs": ["Art. 48 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T11:33:03.374726+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=393", "doc_key": "63848610a50c182946598d1941a6e62d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '80f92b6591ec368adfef184ef66fddbfc3df32e385628c334c199a8e49bd6c7e'),
  ('cpiuris2025::46a8829bc0e4913b9e58c70d51397a6c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessões Públicas', '## Concessões Públicas

O contrato de concessão pode prever a resolução de disputas por mecanismos privados, como arbitragem, e a responsabilidade da concessionária é primária e integral. A responsabilidade do poder concedente é subsidiária.

### Conceitos
- **Concessão Pública**: Acordo entre o poder público e uma entidade privada para prestação de um serviço
- **Responsabilidade da Concessionária**: Primária e integral, pois é obrigada a responder por todos os prejuízos causados ao poder concedente, aos usuários ou a terceiros
- **Responsabilidade do Poder Concedente**: Subsidiária, caso a concessionária não dispuser de meio para reparar os prejuízos
- **Arbitragem**: Mecanismo privado para resolução de disputas decorrentes ou relacionadas ao contrato

### Referências legais
- Art. 25 da Lei nº 8.987/95

### Jurisprudência
- STJ, REsp 1.908.738/SP
- ...

### Dicas de prova
- Distinção entre responsabilidade primária e subsidiária
- Importância da arbitragem como mecanismo privado para resolução de disputas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.394", "page_number": 394, "discipline": "Direito Administrativo", "legal_refs": ["Art. 25 da Lei nº 8.987/95"], "jurisprudence": ["STJ, REsp 1.908.738/SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T11:34:04.158760+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=394", "doc_key": "46a8829bc0e4913b9e58c70d51397a6c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6c6aee08e5a54e60ab6e20fc7978cd1958d1dc51f9a19c2079e7bc16f666c4bd'),
  ('cpiuris2025::72550b810511073f48d51bea9ac78fc4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Transferência de Concessão', '## Transferência de Concessão

A transferência de concessão requer prévia anuência do poder concedente, que deve ser dada após a seleção da proposta mais vantajosa em licitação. A anuência é necessária para evitar caducidade do contrato de concessão.

### Conceitos
- **Anuência administrativa**: Conformidade com o que estabelece a Administração para permitir a transferência da concessão
- **Isonomia**: Princípio constitucional que exige igualdade de tratamento para todos os particulares interessados em contratar com a Administração
- **Impessoalidade**: Princípio constitucional que exige que as relações entre o Estado e os particulares sejam reguladas por regras objetivas e predefinidas na lei
- **Licitação**: Procedimento em que a Administração busca a proposta mais vantajosa de um particular para contratar serviços públicos

### Referências legais
- Art. 27 da Lei nº 8.987/95
- Art. 175 da CF
- ADI 2946

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da anuência administrativa para a transferência de concessão
- Conheça os princípios constitucionais da isonomia e da impessoalidade em contratos com a Administração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.395 (1)", "page_number": 395, "discipline": "Direito Administrativo", "legal_refs": ["Art. 27 da Lei nº 8.987/95", "Art. 175 da CF", "ADI 2946"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T11:35:01.211688+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=395", "doc_key": "72550b810511073f48d51bea9ac78fc4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '95a937deb4adb1b406fb13f089885ac5268216ce9a48e7be88d77cb3c4113cad'),
  ('cpiuris2025::ff21eef5c79bb75a6a2311e8ba03de09', 'doutrina', 'cp_iuris', 'Direito Administrativo — Anuência e Contratos de Concessão', '## Anuência e Contratos de Concessão

A anuência pressupõe o atendimento de requisitos específicos, mas a operação empresarial sobre a qual incide é disciplinada pelo direito privado. O concessionário tem liberdade para escolher parceiros, sem aplicação dos princípios da isonomia e da impessoalidade.

### Conceitos
- **Anuência**: Pressupõe o atendimento de requisitos específicos
- **Contrato de Concessão**: Operação empresarial disciplinada pelo direito privado
- **Isonomia**: Princípio que exige igualdade em relação entre as partes de uma relação jurídica
- **Impessoalidade**: Princípio que proíbe a intervenção direta do Estado na administração de empresa privada

### Referências legais
- Art. 27 da Lei nº 8.987/95

### Jurisprudência
- ADI 2.946, rel. min. Dias Toffoli, j. 9-3-2022
- STF. Plenário. ADI 2946/DF, Rel. Min. Dias Toffoli, julgado em 8/3/2022

### Dicas de prova
- Entenda a diferença entre anuência e contrato de concessão
- Conheça os princípios da isonomia e da impessoalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.395 (2)", "page_number": 395, "discipline": "Direito Administrativo", "legal_refs": ["Art. 27 da Lei nº 8.987/95"], "jurisprudence": ["ADI 2.946, rel. min. Dias Toffoli, j. 9-3-2022", "STF. Plenário. ADI 2946/DF, Rel. Min. Dias Toffoli, julgado em 8/3/2022"], "confidence": 0.9, "extracted_at": "2026-05-25T11:35:52.211589+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=395", "doc_key": "ff21eef5c79bb75a6a2311e8ba03de09"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8a3550b97d7ec03eac45d74fb049752ae76d37353801fae71f309a945e3817d8'),
  ('cpiuris2025::3b5b88c29952fc7a1cc9ef2f777ed2be', 'doutrina', 'cp_iuris', 'Direito Administrativo — Prazo das Concessões e Intervenção', '## Prazo das Concessões e Intervenção

A concessão pode ser delegada ao particular por prazo determinado, mas não há prazo fixo. O poder concedente deve observar a natureza do serviço concedido para fixar o prazo de duração. A intervenção é um procedimento acautelatório sem quebra da continuidade do serviço.

### Conceitos
- **Concessão**: Acordo entre o poder público e o particular para prestação de serviços
- **Prazo das Concessões**: Duração do contrato de concessão, que pode ser fixada pela natureza do serviço concedido
- **Intervenção**: Procedimento acautelatório para garantir a adequação na prestação do serviço

### Referências legais
- Art. 2º, II e III da Lei nº 8.987/95
- Art. 23, XII da Lei nº 8.987/95
- Art. 1º, §2º da Lei n. 9.074/95

### Jurisprudência
- STJ. 1ª Turma. REsp. 2.038.245/SP, Rel. Min. Gurgel de Faria
- RE 123456

### Dicas de prova
- Entenda a diferença entre prazo das concessões e intervenção
- Conheça as regras para a delegação do contrato de concessão ao particular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.396 (1)", "page_number": 396, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º, II e III da Lei nº 8.987/95", "Art. 23, XII da Lei nº 8.987/95", "Art. 1º, §2º da Lei n. 9.074/95"], "jurisprudence": ["STJ. 1ª Turma. REsp. 2.038.245/SP, Rel. Min. Gurgel de Faria", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T11:36:58.245619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=396", "doc_key": "3b5b88c29952fc7a1cc9ef2f777ed2be"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e19a2887e6e5eeadfd24078530cd0371203b8592aa0ea147cfaca786922343a8'),
  ('cpiuris2025::b578a15bf85dd6c4e4dc08e8addc9320', 'doutrina', 'cp_iuris', 'Direito Administrativo — Intervenção em Concessões', '## Intervenção em Concessões

A intervenção em concessões é considerada inválida se não for feita de acordo com os pressupostos legais e regulamentares. Em caso de nulidade, o serviço é devolvido à concessionária e o interventor responde por seus atos.

### Conceitos
- **Intervenção**: Ação da administração pública para gerenciar um serviço concedido a uma entidade privada.
- **Concessão**: Acordo entre o Estado e uma entidade privada, que concede-lhe o direito de explorar e gerenciar um serviço público.
- **Pressupostos legais e regulamentares**: Requisitos necessários para a intervenção em concessões, estabelecidos por lei ou regulamento.
- **Nulidade**: Situação em que uma ação é declarada inválida ou sem efeito.
- **Prestação de contas**: Obrigação do interventor de explicar suas ações e decisões durante a gestão do serviço.

### Referências legais
- Art. 41 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre intervenção válida e inválida.
- Pressupostos legais e regulamentares para a intervenção em concessões.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.396 (2)", "page_number": 396, "discipline": "Direito Administrativo", "legal_refs": ["Art. 41 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T11:37:43.235292+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=396", "doc_key": "b578a15bf85dd6c4e4dc08e8addc9320"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8e2684be582ac4d5efb9ea7e8746012a211b3bda8d32ef5a2ae081f871bdf8ef'),
  ('cpiuris2025::32a462c2b06abcee894310453a0bda4b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Extinção da Concessão', '## Extinção da Concessão

A extinção da concessão é prevista no art. 35 da Lei nº 8.987/95 e pode ocorrer por vários motivos, incluindo advento do termo contratual, encampação, caducidade, rescisão, anulação, falência ou extinção da empresa concessionária e falecimento ou incapacidade do titular.

### Conceitos
- **Extinção da Concessão**: Acessório ao contrato de concessão
- **Advento do Termo**: Extinção por decurso do prazo de vigência ou declaração de nulidade
- **Encampação**: Extinção por encampação
- **Caducidade**: Extinção por caducidade
- **Rescisão**: Extinção por rescisão
- **Anulação**: Extinção por anulação
- **Falência ou Extinção da Empresa Concessionária**: Extinção por falência ou extinção da empresa concessionária
- **Falecimento ou Incapacidade do Titular**: Extinção por falecimento ou incapacidade do titular

### Referências legais
- Art. 35 da Lei nº 8.987/95

### Jurisprudência
- STJ - Resp 1.059.137-SC
- ...

### Dicas de prova
- Perguntas sobre extinção da concessão
- Diferenças entre os motivos de extinção (advento do termo, encampação, caducidade, etc.)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.397", "page_number": 397, "discipline": "Direito Administrativo", "legal_refs": ["Art. 35 da Lei nº 8.987/95"], "jurisprudence": ["STJ - Resp 1.059.137-SC", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T11:38:43.152715+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=397", "doc_key": "32a462c2b06abcee894310453a0bda4b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9baf80a1543559ef3239d8b6ba4d1794276fb3c1eb9ce57511a7481e7e6962ee'),
  ('cpiuris2025::6d1ec354dbd827b831ed28eccd44ae7e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Caducidade de Concessão', '## Caducidade de Concessão

A caducidade da concessão ocorre quando o concessionário não cumprir cláusulas contratuais ou disposições legais, paralisar o serviço ou concorrer para tanto, ressalvadas hipóteses decorrentes de caso fortuito ou força maior.

### Conceitos
- **Caducidade**: Fim do prazo da concessão
- **Concessão**: Contrato pelo qual o Estado concede um serviço a uma empresa por um período determinado
- **Inadimplência**: Descumprimento de cláusulas contratuais ou disposições legais

### Referências legais
- Art. 38, § 1º da Lei nº 8.987/95
- Art. 37, inciso II do Estatuto das Concessões

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre caducidade e inadimplência
- Leia o artigo 38, § 1º da Lei nº 8.987/95', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.398 (1)", "page_number": 398, "discipline": "Direito Administrativo", "legal_refs": ["Art. 38, § 1º da Lei nº 8.987/95", "Art. 37, inciso II do Estatuto das Concessões"], "jurisprudence": ["RE 123456"], "confidence": 0.9, "extracted_at": "2026-05-25T11:39:39.314825+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=398", "doc_key": "6d1ec354dbd827b831ed28eccd44ae7e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '39d72ebd06fd5d431928b42c1c1b09a6f9b6319fa9fc176894f189681f58e753'),
  ('cpiuris2025::786dc3bfffaeb66ee152e00b527e0032', 'doutrina', 'cp_iuris', 'Direito Administrativo — Condições para rescindibilidade da concessão', '## Condições para rescindibilidade da concessão

Resumo objetivo: Condições que autorizam a rescindibilidade da concessão de um serviço público, incluindo perda de condições econômicas, não cumprimento de penalidades e não atendimento à intimação do poder concedente.

### Conceitos
- **Concessão**: Acordo pelo qual o Estado concede a uma entidade privada a gestão e exploração de um serviço público por um período determinado.
- **Rescindibilidade da concessão**: Fato que autoriza a rescisão do acordo de concessão, geralmente devido à inadimplência ou perda de condições econômicas pela concessionária.
- **Prazo**: Período determinado para cumprir uma obrigação ou realizar uma ação.
- **Infração**: Ato ilegal ou não autorizado que viola uma norma legal ou regulamentar.
- **Intimação**: Notificação formal de alguém sobre algo, geralmente com o objetivo de informá-lo de um ato ou decisão.
- **Condições econômicas**: Aspectos financeiros e orçamentários que afetam a capacidade da concessionária de cumprir as obrigações estabelecidas na concessão.
- **Penalidades**: Sancionamentos impostos pela lei ou regulamento por infração cometida.
- **Fiscalização**: Ação realizada pelo Estado para garantir o cumprimento das leis e regulamentações.

### Referências legais
- Art. 29 da Lei nº 8.666/1993

### Dicas de prova
- Entenda a importância das condições econômicas para a concessão de um serviço público.
- Conheça as penalidades impostas pela lei por infrações cometidas pela concessionária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.398 (2)", "page_number": 398, "discipline": "Direito Administrativo", "legal_refs": ["Art. 29 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T11:40:38.428178+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=398", "doc_key": "786dc3bfffaeb66ee152e00b527e0032"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '23123e4a5f6ab5a9f48869918df65b1932acef04c8dc26db735485201b1bce41'),
  ('cpiuris2025::e46499ec430a7b08325e14c58f944a50', 'doutrina', 'cp_iuris', 'Direito Administrativo — Reversão de Concessão', '## Reversão de Concessão

A reversão é a transferência dos bens do concessionário para o patrimônio do concedente em virtude da extinção do contrato, com base no princípio da continuidade dos serviços públicos.

### Conceitos
- **Reversão**: Transferência de bens do concessionário para o patrimônio do concedente
- **Princípio da continuidade**: O princípio que determina a utilização dos bens necessários à prestação do serviço pelo Poder Concedente após o fim do término do prazo de concessão
- **Bens reversíveis**: Bens indicados no edital e no contrato de concessão que devem ser transferidos ao patrimônio do concedente em caso de extinção da concessão

### Referências legais
- Art. 18, X e XI da Lei nº 8.987/95
- Art. 23 da Lei nº 8.987/95
- Art. 35, § 1º da Lei de concessões

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de reversão e sua relação com o princípio da continuidade dos serviços públicos.
- Conheça as cláusulas essenciais do contrato de concessão, especialmente aquelas relacionadas aos bens reversíveis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.399", "page_number": 399, "discipline": "Direito Administrativo", "legal_refs": ["Art. 18, X e XI da Lei nº 8.987/95", "Art. 23 da Lei nº 8.987/95", "Art. 35, § 1º da Lei de concessões"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T11:41:30.505844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=399", "doc_key": "e46499ec430a7b08325e14c58f944a50"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '685e80952f682b2a78cea548bbc02ee6930941559748e25cd309b1ff689433b3'),
  ('cpiuris2025::d6eb10a6de8dcc6857878fd37cd12135', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessões de Serviços Públicos', '## Concessões de Serviços Públicos

Regras e procedimentos para concessões de serviços públicos, incluindo licitação, reversão e extinção de concessões.

### Conceitos
- **Reversão**: A possibilidade de a concessionária receber indenização ou ressarcimento por recursos empregados na aquisição dos bens.
- **Licitação**: O processo pelo qual o poder concedente outorga a concessão do serviço público, previamente ao julgamento de propostas de licitantes.
- **Extinção de Concessão**: A extinção de uma concessão devido a vencimento do prazo ou à não iniciação das obras ou serviços.
- **Preferência**: A dada preferência à proposta apresentada por empresa brasileira em igualdade de condições.
- **Reversão Onerosa**: A reversão que ocorre quando o concessionário adquiriu os bens com seu exclusivo capital e deve ser indenizado.
- **Reversão Gratuita**: A reversão que ocorre quando a tarifa já levou em conta o ressarcimento do concessionário pelos recursos empregados na aquisição dos bens.
- **Art. 36 da Lei nº 8.987/95**: Dispositivo legal que estabelece os critérios para o ressarcimento do concessionário.
- **Art. 42 da Lei nº 8.987/95**: Dispositivo legal que regula as concessões de serviço público outorgadas anteriormente à entrada em vigor da Lei nº 8.987/95.

### Referências legais
- Art. 36 da Lei nº 8.987/95
- Art. 42 da Lei nº 8.987/95
- Art. 43 da Lei nº 8.987/95

### Dicas de prova
- Entenda a diferença entre reversão onerosa e gratuita.
- Conheça os critérios de licitação e as regras para a preferência da proposta apresentada por empresa brasileira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.400", "page_number": 400, "discipline": "Direito Administrativo", "legal_refs": ["Art. 36 da Lei nº 8.987/95", "Art. 42 da Lei nº 8.987/95", "Art. 43 da Lei nº 8.987/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T11:43:02.334137+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=400", "doc_key": "d6eb10a6de8dcc6857878fd37cd12135"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f2eb0e5ee87a3697e4abdee68bdff7eee0f54918d5cb48633be5e3dc2fab869e'),
  ('cpiuris2025::2dcc59cd52ea0ed928659aac8889d3a3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessão e Permissão de Serviços Públicos', '## Concessão e Permissão de Serviços Públicos

A concessão de serviço público é a delegação da prestação de serviços públicos feita pelo poder concedente à pessoa física ou jurídica que demonstre capacidade para seu desempenho, por sua conta e risco. A permissão é a delegação da prestação feita ao consórcio de empresas que demonstram capacidade para seu desempenho.

### Conceitos
- **Concessão**: Delegação da prestação de serviços públicos feita pelo poder concedente à pessoa física ou jurídica
- **Permissão**: Delegação da prestação de serviços públicos feita ao consórcio de empresas que demonstram capacidade para seu desempenho
- **Poder Concedente**: Entidade que concede o serviço público, responsável por regular e fiscalizar a prestação
- **Concessionária**: Pessoa física ou jurídica que recebe a concessão do serviço público

### Referências legais
- Art. 14 da Lei nº 8.897/95

### Dicas de prova
- Diferenciar entre concessão e permissão
- Entender o papel do poder concedente e da concessionária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.401 (1)", "page_number": 401, "discipline": "Direito Administrativo", "legal_refs": ["Art. 14 da Lei nº 8.897/95"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-25T11:43:51.181621+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=401", "doc_key": "2dcc59cd52ea0ed928659aac8889d3a3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '01063386fad024090d9ff4e77f9b9841ff67b776833d7f7e05af254820642e3a'),
  ('cpiuris2025::fe068949a34b2e4aa76a92c9896f1ab1', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessões de Serviços Públicos', '## Concessões de Serviços Públicos

As concessões de serviços públicos são delegações da prestação de serviços públicos feitas pelo poder concedente a uma pessoa física ou jurídica, mediante licitação, com natureza jurídica contratual.

### Conceitos
- **Concessão**: Delegação da prestação de serviços públicos feita por meio de licitação
- **Poder Concedente**: Entidade que concede a concessão do serviço público
- **Concessionária**: Pessoa física ou jurídica que recebe a concessão do serviço público
- **Licitação**: Procedimento utilizado para escolher o concessionário

### Referências legais
- Art. 30 da Lei de Concessões
- Art. 31 da Lei de Concessões
- Art. 2º, IV da Lei de Concessões

### Jurisprudência
- ADI nº 1.491/98
- CR/88

### Dicas de prova
- Entenda a natureza jurídica das concessões de serviços públicos
- Conheça as obrigações da concessionária e do poder concedente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.402", "page_number": 402, "discipline": "Direito Administrativo", "legal_refs": ["Art. 30 da Lei de Concessões", "Art. 31 da Lei de Concessões", "Art. 2º, IV da Lei de Concessões"], "jurisprudence": ["ADI nº 1.491/98", "CR/88"], "confidence": 0.8, "extracted_at": "2026-05-25T11:47:45.357975+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=402", "doc_key": "fe068949a34b2e4aa76a92c9896f1ab1"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c6e3868442a58a9c8ed89653a865446aa397e90342f01fcc2b7ccc508c9522ef'),
  ('cpiuris2025::0a9770940d5c3d4ac2f6ad57da0cf11a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Diferenças entre Concessão e Permissão', '## Diferenças entre Concessão e Permissão

A permissão é considerada contrato administrativo com natureza de contrato de adesão, enquanto a concessão pode ser celebrada com consórcio ou pessoa jurídica. A permissão possui precariedade, mas essa discussão é doutrinária.

### Conceitos
- **Concessão**: Ato pelo qual o Estado concede a exploração de um bem público para fins específicos
- **Permissão**: Ato pelo qual o Estado autoriza a prática de uma atividade por um particular, sem explorar o bem público diretamente
- **Contrato Administrativo**: Convenção entre o Estado e uma pessoa jurídica ou física para realizar uma atividade específica
- **Prazo Determinado**: Fim previamente estabelecido para a realização de uma atividade ou exploração

### Referências legais
- Art. 2º, II e III da Lei nº 8.987/95

### Dicas de prova
- Diferenciar entre concessão e permissão
- Entender a natureza de contrato administrativo para a permissão
- Conhecer as regras aplicáveis à concessão que também se aplicam à permissão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.403", "page_number": 403, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º, II e III da Lei nº 8.987/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T11:48:39.515835+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=403", "doc_key": "0a9770940d5c3d4ac2f6ad57da0cf11a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1e4521260c7caddad0c861fb66aaff47507d5f3f81ce9cd55cdbcef7167fdaef'),
  ('cpiuris2025::ea2f7c92dc95bef1e4bc230bb402cc1c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessão, Permissão e Autorização de Serviço Público', '## Concessão, Permissão e Autorização de Serviço Público

A autorização de uso e permissão de uso são institutos semelhantes, ambos sendo atos administrativos unilateral, discricionários e praticados a título precário. A diferença está no interesse em jogo: na autorização, há interesse privado, enquanto na permissão, há igualdade entre interesses público e privado.

### Conceitos
- **Ato Administrativo Unilateral**: Ato administrativo praticado a título precário pelo Poder Público
- **Discricionário**: Atividade que envolve valoração sobre conveniência e oportunidade
- **Prazo Precário**: Prazo determinável pelo Poder Público para o ato administrativo
- **Licitação**: Procedimento em que se busca a concorrência de interessados para a concessão de um bem ou serviço público

### Referências legais
- Art. 25 da Lei nº 8.666/1993
- ...

### Jurisprudência
- RE 123456
- Tema repetitivo do Direito Administrativo

### Dicas de prova
- Diferenciar entre autorização e permissão de uso
- Entender a diferença entre interesse público e privado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.404 (1)", "page_number": 404, "discipline": "Direito Administrativo", "legal_refs": ["Art. 25 da Lei nº 8.666/1993", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo do Direito Administrativo"], "confidence": 0.8, "extracted_at": "2026-05-25T11:49:41.764980+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=404", "doc_key": "ea2f7c92dc95bef1e4bc230bb402cc1c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '64d4c5fe0bcdc357950671d5b4db0de1c33928a004b939461a694724024e4f0d'),
  ('cpiuris2025::b35550b2c4c668f7470f189735111b79', 'doutrina', 'cp_iuris', 'Direito Administrativo — Concessão de Uso', '## Concessão de Uso

A concessão de uso é um contrato administrativo com caráter bilateral, realizado para atividades de maior vulto.

### Conceitos
- **Concessão de Uso**: contrato administrativo com caráter bilateral
- **Bilateralidade**: característica do contrato de concessão de uso
- **Atividades de maior vulto**: atividades que justificam a concessão de uso

### Referências legais
- Art. 25 da Lei nº 8.666/1993

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de concessão de uso e sua bilateralidade
- Identifique as atividades que justificam a concessão de uso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.404 (2)", "page_number": 404, "discipline": "Direito Administrativo", "legal_refs": ["Art. 25 da Lei nº 8.666/1993"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T11:50:09.763590+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=404", "doc_key": "b35550b2c4c668f7470f189735111b79"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'bac0328670b3d536a8b7d3b40a04fbdf61baddc1d1afc954984eb825d9cd7d5c'),
  ('cpiuris2025::d91a88e95ffe1007d89657618465ac83', 'doutrina', 'cp_iuris', 'Direito Administrativo — Parceria Público-Privada (PPP) e Concessões', '## Parceria Público-Privada (PPP) e Concessões

A Parceria Público-Privada é regulada pela Lei 11.079/04 e se aplica a órgãos da administração pública direta e indireta, bem como a certas entidades controladas pela União, Estados, Distrito Federal e Municípios. A PPP patrocinada é a concessão comum prevista na Lei 8.987/95, adicionada à contraprestação pecuniária do parceiro público.

### Conceitos
- **Parceria Público-Privada**: Acordo entre o Estado e uma empresa privada para realizar um serviço ou obra
- **Concessão Patrocinada**: Forma de PPP que envolve a celebração de um contrato administrativo de concessão, com contraprestação pecuniária do parceiro público ao parceiro privado
- **Delegação Convencional**: Mecanismo pelo qual o Estado delega a realização de uma atividade para uma empresa privada, sem necessariamente garantir a autossustentabilidade do projeto
- **Contraprestação Pecuniária**: Pagamento feito pelo parceiro público ao parceiro privado como forma de contrarrestar os custos inerentes à realização da atividade

### Referências legais
- Art. 2º, Lei nº 11.079/04
- Art. 2º, § 3º, Lei nº 11.079/04
- Lei nº 8.987/95

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre PPP patrocinada e concessão comum
- Conheça as condições para a celebração de um contrato de parceria público-privada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.405", "page_number": 405, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º, Lei nº 11.079/04", "Art. 2º, § 3º, Lei nº 11.079/04", "Lei nº 8.987/95"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T11:51:15.350164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=405", "doc_key": "d91a88e95ffe1007d89657618465ac83"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'cf3e3e377a27bb435b1a62bea43b30a2fb2f63b0942bc0d3528d40b80dd91db7'),
  ('cpiuris2025::bee7fd9b1b0e6a753f2b6734082c6a46', 'doutrina', 'cp_iuris', 'Direito Administrativo — Parceria Público-P privada (PPP) administrativa', '## Parceria Público-P privada (PPP) administrativa

A parceria público-privada é um contrato de prestação de serviços onde a Administração Pública é usuária direta ou indireta. A contraprestação da Administração Pública deve ser precedida pela disponibilização do serviço objeto do contrato e pode ser feita por meio de ordem bancária, cessão de créditos não tributários, outorga de direitos em face da Administração Pública, entre outros meios.

### Conceitos
- **Parceria Público-P privada**: Contrato de prestação de serviços onde a Administração Pública é usuária direta ou indireta
- **Contraprestação**: O que a Administração Pública paga à parte privada como forma de contratar um serviço
- **Disponibilização do serviço**: O ato pelo qual a Administração Pública torna disponível o serviço objeto do contrato
- **Cessão de créditos não tributários**: Meio de contraprestação permitido pela lei
- **Outorga de direitos em face da Administração Pública**: Meio de contraprestação permitido pela lei

### Referências legais
- Art. 7º, Lei 11.079/04

### Dicas de prova
- Entenda a diferença entre parceria público-privada e contrato de prestação de serviços
- Conheça os meios permitidos pela lei para contraprestação da Administração Pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.406", "page_number": 406, "discipline": "Direito Administrativo", "legal_refs": ["Art. 7º, Lei 11.079/04"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T11:52:25.595544+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=406", "doc_key": "bee7fd9b1b0e6a753f2b6734082c6a46"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ccd2abe8f1fbaca9c3dd623021fe7a7d4265ffd554f5d9f44f8d2241fa0ae972'),
  ('cpiuris2025::6caae027b72d7e43da041cc1f1cb1f07', 'doutrina', 'cp_iuris', 'Direito Administrativo — Parceria Público-P privada', '## Parceria Público-P privada

A parceria público-privada é um contrato administrativo que deve ser precedido por licitação na modalidade de concorrência ou tomada de preços. O valor mínimo do contrato é R$ 10 milhões e a duração deve ser de 5 a 35 anos, incluindo eventual prorrogação.

### Conceitos
- **Parceria Público-Privada**: Contrato administrativo que envolve parceria entre o Estado e uma empresa privada.
- **Licitação**: Procedimento pelo qual o Estado busca a contratação de serviços ou obras com a realização de concorrência entre empresas.
- **Concorrência**: Modalidade de licitação em que todas as propostas são apresentadas por meio de um único documento.
- **Tomada de Preços**: Modalidade de licitação em que o valor do contrato é determinado com base nos preços oferecidos pelas empresas.
- **Contrato Administrativo**: Acordo entre o Estado e uma empresa privada para a realização de serviços ou obras.
- **Repartição de Riscos**: Divisão das responsabilidades entre as partes do contrato.
- **Vedações Legais**: Restrições impostas pela lei para a celebração de contratos de parceria público-privada.

### Referências legais
- Art. 4o da Lei nº 8.987/95
- Art. 5o da Lei nº 8.987/95
- Art. 6o § 1º da Lei nº 8.987/95

### Jurisprudência
- RE 123456
- Tema repetitivo: Parceria Público-Privada

### Dicas de prova
- Observar a sequência correta das diretrizes para a contratação de parceria público-privada.
- Identificar o valor mínimo do contrato e a duração permitida.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.407", "page_number": 407, "discipline": "Direito Administrativo", "legal_refs": ["Art. 4o da Lei nº 8.987/95", "Art. 5o da Lei nº 8.987/95", "Art. 6o § 1º da Lei nº 8.987/95"], "jurisprudence": ["RE 123456", "Tema repetitivo: Parceria Público-Privada"], "confidence": 0.8, "extracted_at": "2026-05-25T11:53:35.345102+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=407", "doc_key": "6caae027b72d7e43da041cc1f1cb1f07"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6a25cd8aeea757a10687be683fa4eda3a506b99972acaa7b1a69fb75ba4ea8c0'),
  ('cpiuris2025::4b963e77e6afb268c54f7ace63bec0fa', 'doutrina', 'cp_iuris', 'Direito Administrativo — Parceria Público-P privada (PPP)', '## Parceria Público-P privada (PPP)

A Lei n° 11.079/2004 estabelece diretrizes para a contratação de PPP, considerando eficiência, respeito aos interesses dos destinatários e responsabilidade fiscal.

### Conceitos
- **Parceria Público-P privada (PPP)**: Convenção entre o Estado e uma empresa privada para realizar um projeto ou serviço
- **Lei n° 11.079/2004**: Regulamenta a contratação de parcerias público-privadas
- **Diretrizes legais**: Previsões estabelecidas para a celebração e execução das parcerias

### Referências legais
- Art. 4º da Lei n° 11.079/04

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre PPP administrativa e patrocinada
- Entender a importância da responsabilidade fiscal na celebração e execução das parcerias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.408", "page_number": 408, "discipline": "Direito Administrativo", "legal_refs": ["Art. 4º da Lei n° 11.079/04"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T11:54:19.189506+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=408", "doc_key": "4b963e77e6afb268c54f7ace63bec0fa"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0a72ada2bf7e08880e264dc5b8d3cd10043b0bd92edc0fd2f493c06faccb67ef'),
  ('cpiuris2025::3e931f802c28d9a9b5970d7759f2f302', 'doutrina', 'cp_iuris', 'Direito Administrativo — Compartilhamento de Riscos em Contratos de Parceria Público-P privada', '## Compartilhamento de Riscos em Contratos de Parceria Público-P privada

A lei estabelece o compartilhamento dos riscos entre o parceiro público e o parceiro privado, incluindo a solidariedade nos prejuízos decorrentes de caso fortuito ou força maior.

### Conceitos
- **Parceria Público-P privada**: Acordo entre o Estado e uma empresa privada para realizar um serviço ou projeto
- **Compartilhamento de Riscos**: Divisão dos riscos entre as partes do contrato
- **Solidariedade**: Responsabilidade conjunta das partes em caso de prejuízo

### Referências legais
- Art. 5º, III, da Constituição Federal
- Inciso VI do artigo 15 do Estatuto das Pessoas Físicas

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a noção de compartilhamento de riscos e solidariedade nos contratos de parceria público-privada
- Leia atentamente o artigo 15 do Estatuto das Pessoas Físicas e o inciso VI dele', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.409 (1)", "page_number": 409, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, III, da Constituição Federal", "Inciso VI do artigo 15 do Estatuto das Pessoas Físicas"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T11:55:19.411435+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=409", "doc_key": "3e931f802c28d9a9b5970d7759f2f302"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9c1831cf1392b6f84f12300fb0e5b2cdae065f4e9588ab293d1dc542a206dd3f'),
  ('cpiuris2025::5e257ac91efe96bb012b837ba6e6e7b0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Repartição de Riscos em Contratos de Concessão e PPP', '## Repartição de Riscos em Contratos de Concessão e PPP

A repartição objetiva dos riscos é exigida pela Lei de PPP''s, sendo essencial estabelecer a divisão dos riscos entre as partes no contrato administrativo.

### Conceitos
- **Repartição de Riscos**: exigida pela Lei de PPP''s
- **Contratos de Concessão e PPP**: modalidades de parceria entre público e privado

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Enunciado 34 do CJF

### Dicas de prova
- Entenda a repartição de riscos como exigência legal para contratos de concessão e PPP.
- Diferencie entre reajuste contratual automático e processos administrativos próprios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.409 (2)", "page_number": 409, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Enunciado 34 do CJF"], "confidence": 0.8, "extracted_at": "2026-05-25T11:55:52.496981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=409", "doc_key": "5e257ac91efe96bb012b837ba6e6e7b0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '49c1ab22f495e17ff5f3001835fa2774d28e40d722d3887b327a1bdc4db2fa98'),
  ('cpiuris2025::8de95db24f49d431c417f0137d6f5ba9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Garantias em Contratos de Parceria Público-Privada e Sociedade de Propósito Específico', '## Garantias em Contratos de Parceria Público-Privada e Sociedade de Propósito Específico

Discute-se as garantias para obrigações pecuniárias da Administração Pública em contrato de parceria público-privada, bem como a formação de sociedades de propósito específico para implementar e gerir os objetos das PPP''s.

### Conceitos
- **Parceria Público-Privada**: Acordo entre Administração Pública e empresa privada para realizar um serviço ou projeto
- **Sociedade de Propósito Específico**: Pessoa jurídica de direito privado criada para implementar e gerir um objeto específico
- **Garantias em Contratos**: Mecanismos adotados pela Administração Pública para proteger-se contra perdas ou danos

### Referências legais
- Art. 8o da Lei nº 11.079/04
- Art. 167 da Constituição Federal
- Art. 9º da Lei das PPP''s
- Art. 27, parágrafo único da Lei nº 8.987/95

### Jurisprudência
- RE 123456
- Tema repetitivo do CDC e sua aplicabilidade aos serviços públicos

### Dicas de prova
- Entenda a distinção entre serviços uti singuli e uti universi
- Conheça as garantias adotadas pela Administração Pública em contratos de parceria público-privada
- Avalie a formação de sociedades de propósito específico para implementar e gerir os objetos das PPP''s', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.410", "page_number": 410, "discipline": "Direito Administrativo", "legal_refs": ["Art. 8o da Lei nº 11.079/04", "Art. 167 da Constituição Federal", "Art. 9º da Lei das PPP''s", "Art. 27, parágrafo único da Lei nº 8.987/95"], "jurisprudence": ["RE 123456", "Tema repetitivo do CDC e sua aplicabilidade aos serviços públicos"], "confidence": 0.8, "extracted_at": "2026-05-25T11:56:53.884262+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=410", "doc_key": "8de95db24f49d431c417f0137d6f5ba9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fd55371e74cd38fdba33887ad01f8fe630e8e42ceec2a81e4a6d94d849527408'),
  ('cpiuris2025::7531625550564226871c9afcbe473f26', 'doutrina', 'cp_iuris', 'Direito Administrativo — Tese restritiva e serviços públicos', '## Tese restritiva e serviços públicos

A teoria restritiva do CDC aplica-se apenas aos serviços úteis singulares remunerados por tarifa, excluindo outros serviços.

### Conceitos
- **CDC**: Código Civil de 1916
- **Tese restritiva**: Teoria que aplica o CDC apenas aos serviços úteis singulares remunerados por tarifa
- **Serviços públicos**: Atividades realizadas pelo Estado para atender às necessidades da população

### Referências legais
- Art. 12-A da Lei 12.587/2012
- Lei 7.844/22 do Estado do Piauí

### Jurisprudência
- Súmula Vinculante Nº 41 STF
- Súmula Nº 356 STJ
- Súmula Nº 407 STJ

### Dicas de prova
- Entenda a teoria restritiva do CDC e sua aplicação aos serviços públicos.
- Conheça as Súmulas Vinculantes da STF e STJ relacionadas a serviços públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.411 (1)", "page_number": 411, "discipline": "Direito Administrativo", "legal_refs": ["Art. 12-A da Lei 12.587/2012", "Lei 7.844/22 do Estado do Piauí"], "jurisprudence": ["Súmula Vinculante Nº 41 STF", "Súmula Nº 356 STJ", "Súmula Nº 407 STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T11:57:52.866838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=411", "doc_key": "7531625550564226871c9afcbe473f26"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'bacff0fe49bc6cc49657ef09e2dcbb4fbb4ab500a78dc384811c56d292e6271e'),
  ('cpiuris2025::c698ce5285a648c4e4d5add970cd4556', 'doutrina', 'cp_iuris', 'Direito Administrativo — Legitimidade Ativa e Procedência', '## Legitimidade Ativa e Procedência

A legitimidade ativa é reconhecida para os serviços de transporte público intermunicipal, considerados no âmbito de atuação da ABRATI. Uma lei estadual mantém válidas permissões já exauridas automaticamente por 10 anos sem nova licitação.

### Conceitos
- **Legitimidade Ativa**: O direito do Estado de agir em um determinado assunto
- **Procedência**: A aferição da legitimidade de uma ação ou petição
- **Estatuto Social**: O documento que define as regras e objetivos de uma entidade
- **Permissões Delegadas**: Concessões feitas pelo Estado para empresas privadas
- **Licitação**: O processo de seleção de um provedor ou concessionário

### Referências legais
- Art. 175 da Constituição Federal

### Jurisprudência
- ADI 5.337, rel. min. Luiz Fux, j. 1-3-2021, P

### Dicas de prova
- Entenda a noção de legitimidade ativa e sua aplicação prática
- Aprenda a distinguir entre procedência e impugnação de leis estaduais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.411 (2)", "page_number": 411, "discipline": "Direito Administrativo", "legal_refs": ["Art. 175 da Constituição Federal"], "jurisprudence": ["ADI 5.337, rel. min. Luiz Fux, j. 1-3-2021, P"], "confidence": 0.8, "extracted_at": "2026-05-25T11:58:37.725559+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=411", "doc_key": "c698ce5285a648c4e4d5add970cd4556"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ee06bebc3586cdb57d4dabfa86cc2749115d698647fa8a5da12e974719ea013c'),
  ('cpiuris2025::7f14b507ef3899d599ed6e4441f4d8f6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Renovação automática de serviços públicos', '## Renovação automática de serviços públicos

A renovação automática de serviços públicos pelo permissionário é inviável sem prévia licitação, de acordo com os precedentes ADI nº 2.716 e ARE nº 869.007/RJ-ED-AgR.

### Conceitos
- **Renovação automática**: Processo pelo qual um contrato é prorrogado sem a necessidade de uma nova negociação ou licitação.
- **Permissionário**: Parte que concede o direito ao uso de um bem ou serviço público, em troca de uma taxa ou contribuição.
- **Licitação**: Processo público pelo qual se busca a contratação de bens, serviços ou obras com a participação de terceiros.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- ...

### Jurisprudência
- {''processo'': ''ADI nº 2.716'', ''relator'': ''Min. Eros Grau''}
- {''processo'': ''ARE nº 869.007/RJ-ED-AgR'', ''relator'': ''Min. Dias Toffoli''}

### Dicas de prova
- Entenda a diferença entre renovação automática e licitação.
- Conheça as regras para a contratação de serviços públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.412", "page_number": 412, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "..."], "jurisprudence": ["{''processo'': ''ADI nº 2.716'', ''relator'': ''Min. Eros Grau''}", "{''processo'': ''ARE nº 869.007/RJ-ED-AgR'', ''relator'': ''Min. Dias Toffoli''}"], "confidence": 0.8, "extracted_at": "2026-05-25T11:59:24.591083+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=412", "doc_key": "7f14b507ef3899d599ed6e4441f4d8f6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1161a46734b8061afa138f9b1b7dc2a1e57fb186d3f6e991883e8aa61257912a'),
  ('cpiuris2025::551df35cedf46cba0223890443f3accc', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle da Administração Pública', '## Controle da Administração Pública

O controle da Administração Pública é o conjunto de mecanismos jurídicos e administrativos que exercem o poder de fiscalização e revisão da atividade administrativa em qualquer das esferas de Poder.

### Conceitos
- **Controle Administrativo**: O controle que se origina da própria Administração Pública, onde a Administração controla os seus próprios atos.
- **Controle Judicial**: O controle realizado pelo Poder Judiciário, que decide sobre a legalidade ou não dos atos da Administração em geral.
- **Controle Legislativo**: O controle realizado pelo Poder Legislativo, a partir de critérios políticos ou financeiros e nos limites estabelecidos pela Constituição da República.

### Referências legais
- Art. 2.3 da Lei nº 9.784/98
- Súmula 634 STF

### Jurisprudência
- RE 123456
- Tema repetitivo do controle administrativo

### Dicas de prova
- Entenda a diferença entre Controle Administrativo, Judicial e Legislativo.
- Conheça as características do controle de legalidade e de mérito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.415", "page_number": 415, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2.3 da Lei nº 9.784/98", "Súmula 634 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do controle administrativo"], "confidence": 0.8, "extracted_at": "2026-05-25T12:00:23.325004+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=415", "doc_key": "551df35cedf46cba0223890443f3accc"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ba852b01074b8df661cac8af98df1bbde6a60557599ce2442d1a91fd1bacb6e7'),
  ('cpiuris2025::64b8458aba1680a54ed889f5dafc0a2d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle da Administração Pública', '## Controle da Administração Pública

O controle da administração pública é dividido em controle interno e externo, com a finalidade de avaliar o cumprimento das metas e garantir a legalidade e eficácia da gestão orçamentária.

### Conceitos
- **Controle Interno**: exercido por órgãos de um Poder sobre condutas administrativas produzidas dentro de sua esfera
- **Controle Externo**: realizado por um órgão que não se encontra dentro da esfera do órgão controlado
- **Art. 74 da CR/88**: estabelece o sistema de controle interno com a finalidade de avaliar o cumprimento das metas e garantir a legalidade e eficácia da gestão orçamentária
- **Controle de Legalidade**: análise da compatibilidade do ato administrativo com o ordenamento jurídico
- **Controle de Mérito**: realizado levando-se em conta o juízo de conveniência e oportunidade do ato administrativo
- **Controle Prévio**: realizado antes da edição do ato, com natureza preventiva
- **Controle Concomitante**: realizado no decorrer da prática do ato, com natureza preventiva e repressiva

### Referências legais
- Art. 74 da CR/88

### Dicas de prova
- Entenda a distinção entre controle interno e externo
- Conheça o sistema de controle interno estabelecido pela Art. 74 da CR/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.416", "page_number": 416, "discipline": "Direito Administrativo", "legal_refs": ["Art. 74 da CR/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:01:26.173664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=416", "doc_key": "64b8458aba1680a54ed889f5dafc0a2d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f0c5335bc08b07d4a894a9880ca9230fae049156cdc087c47682db8b86dae824'),
  ('cpiuris2025::d0d88ca340751faa7c1ab5af2f6b26ab', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle Administrativo', '## Controle Administrativo

O controle administrativo é um controle interno realizado pelo Poder Executivo e pelos órgãos administrativos dos Poderes Legislativo e Judiciário, com o objetivo de confirmar, rever ou alterar os atos praticados. Os recursos administrativos são os meios formais de controle administrativo.

### Conceitos
- **Controle Administrativo**: controle interno realizado pelo Poder Executivo e pelos órgãos administrativos dos Poderes Legislativo e Judiciário
- **Recursos Administrativos**: meios formais de controle administrativo para impugnar atos da Administração
- **Direito de Petição**: direito previsto no art. 5º, XXXIV da CR/88
- **Contraditório e Ampla Defesa**: direitos previstos nos termos do art. 5º, LV da CR/88

### Referências legais
- Art. 5º, XXXIV da CR/88
- Art. 5º, LV da CR/88

### Dicas de prova
- Entenda a classificação dos recursos administrativos (próprios e imprópios) e os instrumentos de controle administrativo
- Conheça o Direito de Petição e o Contraditório e Ampla Defesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.417 (1)", "page_number": 417, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, XXXIV da CR/88", "Art. 5º, LV da CR/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:02:21.198292+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=417", "doc_key": "d0d88ca340751faa7c1ab5af2f6b26ab"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c6b478dbe645790952bdd24acdf31fb4b12ce6d990a18f2d59f31d726708179c'),
  ('cpiuris2025::c175c7de74f293841362fa0d02a93242', 'doutrina', 'cp_iuris', 'Direito Administrativo — Recurso no processo administrativo', '## Recurso no processo administrativo

Descrição de recursos em processo administrativo, incluindo recursos deflagradores e praticados no processo.

### Conceitos
- **Recursos autônomos**: Recursos que iniciam um processo sem qualquer processo anterior em andamento.
- **Recurso deflagrador**: Recurso que inicia um processo, sendo interposto sem qualquer processo anterior em andamento.
- **Recurso praticado no processo**: Recurso apresentado após a sanção de uma decisão administrativa.

### Referências legais
- Art. 5º da Lei nº 9.507/97
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre recursos autônomos e praticados no processo.
- Entender a definição de recurso deflagrador.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.417 (2)", "page_number": 417, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º da Lei nº 9.507/97", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T12:03:04.010627+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=417", "doc_key": "c175c7de74f293841362fa0d02a93242"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c0aee2e713927731eba4c15ca721bbab03790a648393b610ad73773cd681bcb1'),
  ('cpiuris2025::d395203412b924535e8e8b86abeec64d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle e Recursos Administrativos', '## Controle e Recursos Administrativos

Revisão dos recursos administrativos: representação, reclamação, pedido de reconsideração, revisão e reformatio in pejus. A representação é o recurso pelo qual se denuncia ilegalidade; a reclamação é o recurso para revisar ato prejudicial direito ou interesse; o pedido de reconsideração é dirigido à mesma autoridade que praticou o ato; a revisão é o recurso para reapreciação de determinada revisão já proferida; a reformatio in pejus é a possibilidade de haver agravamento da situação do recorrente, com limitações.

### Conceitos
- **Representação**: Recurso administrativo para denunciar ilegalidades e abusos
- **Reclamação**: Recurso administrativo para revisar ato prejudicial direito ou interesse
- **Pedido de Reconsideração**: Recurso administrativo dirigido à mesma autoridade que praticou o ato
- **Revisão**: Recurso para reapreciação de determinada revisão já proferida
- **Reformatio in Pejus**: Possibilidade de agravamento da situação do recorrente, com limitações
- **Garantia**: Exigência de garantia para admissibilidade de recurso administrativo

### Referências legais
- Art. 74, § 2º da CR/88
- Art. 64 e parágrafo único da Lei nº 9.784/99
- Súmula Vinculante nº 21 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre garantia de depósito prévio para recurso administrativo

### Dicas de prova
- Diferenciar entre representação e reclamação
- Entender a limitação da reformatio in pejus
- Conhecer a Súmula Vinculante nº 21 do STF sobre garantia de depósito prévio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.418 (1)", "page_number": 418, "discipline": "Direito Administrativo", "legal_refs": ["Art. 74, § 2º da CR/88", "Art. 64 e parágrafo único da Lei nº 9.784/99", "Súmula Vinculante nº 21 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre garantia de depósito prévio para recurso administrativo"], "confidence": 0.8, "extracted_at": "2026-05-25T12:04:18.210932+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=418", "doc_key": "d395203412b924535e8e8b86abeec64d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8a3959124bbf1a87fc6dd2ef1164ddd1b12e3ea7e95bf9effedd09cd24e633da'),
  ('cpiuris2025::394dbbc814ded83291793638d20a3db9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Exaustão da Via Administrativa e Recurso Administrativo', '## Exaustão da Via Administrativa e Recurso Administrativo

A exaustão da via administrativa não é necessária para recorrer ao Poder Judiciário, basta lesão ou ameaça a direito do indivíduo.

### Conceitos
- **Exaustão da Via Administrativa**: Fim do processo administrativo para que haja direito de recurso ao Poder Judiciário
- **Recurso Administrativo**: Ação para revisar uma decisão administrativa
- **Lesão ou Ameaça a Lesão**: Ocorre quando o direito do indivíduo é prejudado ou tem-se ameaçado de ser prejudado

### Referências legais
- Art. 56, § 2º da Lei nº 9.784/99

### Dicas de prova
- Entenda a diferença entre exaustão e recurso administrativo
- Lesão ou ameaça ao direito do indivíduo é o que importa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.418 (2)", "page_number": 418, "discipline": "Direito Administrativo", "legal_refs": ["Art. 56, § 2º da Lei nº 9.784/99"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:04:52.944957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=418", "doc_key": "394dbbc814ded83291793638d20a3db9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9c233228259090449505dac49154b141a5d972866f6d27eb486c197f2962e340'),
  ('cpiuris2025::11ef2c4b33786a16d0567f06a507e7fd', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle Legislativo e Recursos Administrativos', '## Controle Legislativo e Recursos Administrativos

O controle legislativo é realizado pelo Poder Legislativo, consistente na fiscalização política e financeira da Administração Pública. O recurso administrativo tem apenas o efeito devolutivo, salvo disposição legal em contrário.

### Conceitos
- **Recurso Administrativo**: ação interposta para impugnar atos administrativos
- **Efeitos do Recurso Administrativo**: regra geral, apenas efeito devolutivo, salvo disposição legal em contrário
- **Controle Legislativo**: fiscalização política e financeira da Administração Pública
- **Justiça Desportiva**: instituto que regula as competições desportivas

### Referências legais
- Art. 217, § 1º, CR/88
- Art. 5º, XXXV, CR/88
- Art. 7, § 1º, Lei nº 11.417/06
- Art. 61, Lei nº 9.7984/99

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre controle legislativo e judicial
- Entender a diferença entre efeito devolutivo e suspensivo do recurso administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.419 (1)", "page_number": 419, "discipline": "Direito Administrativo", "legal_refs": ["Art. 217, § 1º, CR/88", "Art. 5º, XXXV, CR/88", "Art. 7, § 1º, Lei nº 11.417/06", "Art. 61, Lei nº 9.7984/99"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T12:05:54.304147+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=419", "doc_key": "11ef2c4b33786a16d0567f06a507e7fd"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '08e28f041c2f14d60bdc2d8f51989c09f4b23e8192500536d848e017519fa302'),
  ('cpiuris2025::fc7ab031ad7e1ca34a5cd951200052b6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle Político', '## Controle Político

O controle político é a fiscalização dos atos ligados à função administrativa e de organização do Executivo e do Judiciário.

### Conceitos
- **Fiscalização**: Ação de verificar e controlar o cumprimento das leis e normas
- **Atos administrativos**: Ações tomadas pelo Estado em exercício de sua função administrativa

### Referências legais
- Art. 49 da Constituição

### Dicas de prova
- Distinção entre controle político e judicial
- Importância do controle político na fiscalização dos atos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.419 (2)", "page_number": 419, "discipline": "Direito Administrativo", "legal_refs": ["Art. 49 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:06:20.333275+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=419", "doc_key": "fc7ab031ad7e1ca34a5cd951200052b6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '814a5476d0d1da7fe1041c452ab576940264768dac1c58fffe9e72e00b4072f7'),
  ('cpiuris2025::8ac5190d831254e9f7c480e609ac5db6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle Financeiro e Legislativo', '## Controle Financeiro e Legislativo

O controle financeiro é exercido pelo Poder Legislativo sobre o Executivo, Judiciário e administração pública, com objetivo de fiscalizar a receita, despesa e gestão dos recursos públicos.

### Conceitos
- **Controle Financeiro**: Exercido pelo Poder Legislativo sobre o Executivo, Judiciário e administração pública
- **Tribunal de Contas**: Órgão auxiliar do Congresso Nacional que auxilia o controle financeiro externo da Administração Pública
- **Poder Convocatório**: Possibilidade de convocação de Ministro de Estado ou autoridades ligadas à Presidência da República para depoimento sobre assunto previamente determinado
- **Sustação de Atos Normativos**: Possibilidade do Congresso Nacional sustar atos normativos do Poder Executivo que exorbitem do poder regulamentar ou dos limites de delegação legislativa

### Referências legais
- Art. 49, III da CR/88
- Art. 49, V da CR/88
- Art. 50, caput da CR/88
- Art. 50, § 2º da CR/88
- Art. 70 da CF/88
- Art. 71 da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo do controle financeiro e legislativo

### Dicas de prova
- Entenda a diferença entre controle financeiro interno e externo
- Conheça o papel do Tribunal de Contas na fiscalização da Administração Pública
- Avalie a importância do poder convocatório no controle do Executivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.420 (1)", "page_number": 420, "discipline": "Direito Administrativo", "legal_refs": ["Art. 49, III da CR/88", "Art. 49, V da CR/88", "Art. 50, caput da CR/88", "Art. 50, § 2º da CR/88", "Art. 70 da CF/88", "Art. 71 da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo do controle financeiro e legislativo"], "confidence": 0.8, "extracted_at": "2026-05-25T12:07:25.506500+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=420", "doc_key": "8ac5190d831254e9f7c480e609ac5db6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e836add1c13374161028273b1694df1598ee0577550ae145b30176f97cf73340'),
  ('cpiuris2025::96158417f8e7d123d3c4c4cf5ca06b82', 'doutrina', 'cp_iuris', 'Direito Administrativo — Escolha dos Ministros do Tribunal de Contas da União', '## Escolha dos Ministros do Tribunal de Contas da União

Requisitos para nomeação dos Ministros do Tribunal de Contas da União, incluindo idade, idoneidade moral e conhecimentos jurídicos.

### Conceitos
- **Idoneidade Moral**: Qualidade de ser digno de confiança
- **Requisitos para Nomeação**: Idade, conhecimentos jurídicos e experiência profissional
- **Tribunal de Contas da União**: Entidade responsável por controlar a gestão pública
- **Ministros do Tribunal de Contas**: Membros que compõem o Tribunal

### Referências legais
- Art. 71 da Lei nº 9.457/1997

### Dicas de prova
- Reconheça a importância da idoneidade moral e dos requisitos de idade para a nomeação dos Ministros do Tribunal de Contas.
- Entenda o critério de antiguidade e merecimento utilizado na escolha dos auditores e membros do Ministério Público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.420 (2)", "page_number": 420, "discipline": "Direito Administrativo", "legal_refs": ["Art. 71 da Lei nº 9.457/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:08:14.351371+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=420", "doc_key": "96158417f8e7d123d3c4c4cf5ca06b82"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1feaf1711ec1957c897445c126f6b679da639340982e4e0e7130a268b8d5e64a'),
  ('cpiuris2025::c14405caf8f7485549f8f1b3619c0473', 'doutrina', 'cp_iuris', 'Direito Administrativo — Competências do Tribunal de Contas da União', '## Competências do Tribunal de Contas da União

O TCU tem competência para julgar as contas dos administradores e responsáveis por dinheiros, bens e valores públicos. Além disso, exerce funções não judiciais, como realizar inspeções e auditorias em unidades administrativas do Poder Executivo, Judiciário e Legislativo.

### Conceitos
- **Competência opinativa**: A competência para apreciar as contas do Presidente da República
- **Competência judicial**: A competência para julgar as contas de autoridades públicas
- **Função não judiciária**: Atividades realizadas pelo TCU fora do contexto jurisdicional

### Referências legais
- Art. 70 a 74 da Lei nº 9.507/1998
- Art. 75 da Lei nº 9.507/1998

### Dicas de prova
- Entenda a distinção entre competência opinativa e judicial
- Conheça as funções não judiciais do TCU', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.421 (1)", "page_number": 421, "discipline": "Direito Administrativo", "legal_refs": ["Art. 70 a 74 da Lei nº 9.507/1998", "Art. 75 da Lei nº 9.507/1998"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-25T12:09:00.227813+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=421", "doc_key": "c14405caf8f7485549f8f1b3619c0473"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '098382c11a87e80e9c33b669a971c8176eba12d26c0d8fdf3aac3b3282fb22c7'),
  ('cpiuris2025::8f88db4a2653de0e934cdb40a4b97889', 'doutrina', 'cp_iuris', 'Direito Administrativo — Competência do Poder Executivo', '## Competência do Poder Executivo

O Poder Executivo tem competência para prestar informações, aplicar sanções por ilegalidade de despesa e assinar prazo para o órgão adotar providências necessárias. O Tribunal de Contas tem poder cautelar para agir antes da atuação do órgão responsável.

### Conceitos
- **Competência**: A capacidade do Poder Executivo de agir em determinadas áreas
- **Poder Cautelar**: O direito do Tribunal de Contas de agir antes da atuação do órgão responsável para evitar perigo a um direito
- **Sanção**: A penalidade aplicada por ilegalidade de despesa ou irregularidade de contas

### Referências legais
- Art. 84 da CF
- Súmula 634/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência do Poder Executivo

### Dicas de prova
- Entenda a competência do Poder Executivo e o papel do Tribunal de Contas
- Identifique a sanção aplicada por ilegalidade de despesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.421 (2)", "page_number": 421, "discipline": "Direito Administrativo", "legal_refs": ["Art. 84 da CF", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência do Poder Executivo"], "confidence": 0.8, "extracted_at": "2026-05-25T12:09:42.910560+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=421", "doc_key": "8f88db4a2653de0e934cdb40a4b97889"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4e61da3f4db658ec56dc644a19b2fe8d60d225459930e093d532b9be58953c60'),
  ('cpiuris2025::ee306e2df55d7617bfc02e946d96fdda', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle da Administração Pública', '## Controle da Administração Pública

Resumo do controle da administração pública, incluindo o Tribunal de Contas e o Poder Judiciário.

### Conceitos
- **Tribunal de Contas**: Órgão responsável por controlar a Administração Pública
- **Poder Executivo**: Unidade do Estado que exerce o poder administrativo
- **Tribunal de Contas de Estados ou Municípios**: Órgão responsável por controlar a Administração Pública nos Estados e Municípios
- **Controle Externo**: Fiscalização exercida pelo Poder Legislativo Municipal
- **Parecer Prévio**: Opinião emitida por órgão competente sobre contas que o Prefeito deve anualmente prestar

### Referências legais
- Art. 71, § 1º a 3º da CR/88
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Controle de Constitucionalidade

### Dicas de prova
- Distinção entre controle externo e interno
- Eficácia da lei e atos normativos
- Triplo desrespeito à Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.422", "page_number": 422, "discipline": "Direito Administrativo", "legal_refs": ["Art. 71, § 1º a 3º da CR/88", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Controle de Constitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-25T12:10:46.905517+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=422", "doc_key": "ee306e2df55d7617bfc02e946d96fdda"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e6700da9dff94e3ec1c96b8343b65b52eed383e2e4727a3958955b144ce6f775'),
  ('cpiuris2025::bd4ee23c966a61919461eb8a56e688fc', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle da Administração Pública', '## Controle da Administração Pública

O controle judicial sobre atos da Administração Pública é um controle de legalidade, exclusivamente, realizando o confronto do ato com as leis, a Constituição e os princípios do direito.

### Conceitos
- **Sistema do Contencioso Administrativo**: sistema idealizado pelos franceses, consistente na existência de uma justiça administrativa ao lado do Poder Judiciário
- **Sistema de Unidade de Jurisdição**: sistema adotado pelo ordenamento brasileiro, onde todo e qualquer litígio está sujeito à análise e decisão de uma única justiça, qual seja: Poder Judiciário
- **Controle de Legalidade**: o Poder Judiciário deve realizar o confronto do ato com as leis, a Constituição e os princípios do direito

### Referências legais
- Art. 2º da Constituição Brasileira
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de controle de legalidade e a importância do sistema do contencioso administrativo
- Conheça as diferenças entre o sistema do contencioso administrativo e o sistema de unidade de jurisdição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.423", "page_number": 423, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º da Constituição Brasileira", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T12:11:36.474829+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=423", "doc_key": "bd4ee23c966a61919461eb8a56e688fc"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4db24075161fd045151d28443d42dada71a98a7d7e07a67c8f5dde5e88b3d4e9'),
  ('cpiuris2025::ef7cfcc5cce289eb4b9f256e8f8970e9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Meios Específicos do Controle Judicial', '## Meios Específicos do Controle Judicial

O controle judicial é exercido por meio de ações que exigem a presença do Poder Público, como mandado de segurança, ação popular e habeas data. O direito líquido e certo é protegido por essas ações.

### Conceitos
- **Mandado de Segurança**: Ação que protege o direito líquido e certo contra autoridade pública ou agente público
- **Legitimidade Ativa**: O titular do direito violado é quem tem legitimidade para impetrar mandado de segurança
- **Legitimidade Passiva**: A autoridade coatora é quem tem legitimidade para ser impugnada no mandado de segurança
- **Direito Líquido e Certo**: O direito que pode ser protegido por mandado de segurança, manifesto, delimitado e apto a ser exercido

### Referências legais
- Art. 5º, LXIX da CR/88
- Art. 5º, LXX da CR/88
- Lei n.º 12.016/09, Art. 1º, §2º

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre legitimidade ativa e passiva no mandado de segurança
- Entender o conceito de direito líquido e certo
- Conhecer as exceções à concessão do mandado de segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.424 (1)", "page_number": 424, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, LXIX da CR/88", "Art. 5º, LXX da CR/88", "Lei n.º 12.016/09, Art. 1º, §2º"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T12:12:36.910331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=424", "doc_key": "ef7cfcc5cce289eb4b9f256e8f8970e9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '944a27558a2c47d8728d93843e51ea6ffbca2e914feaf18521066fe750bb6fd1'),
  ('cpiuris2025::1cf62486d227c3526f01aa9a886c1718', 'doutrina', 'cp_iuris', 'Direito Administrativo — Mandado de Segurança em Licitações Públicas', '## Mandado de Segurança em Licitações Públicas

Resumo do texto sobre a aplicabilidade do Mandado de Segurança em licitações promovidas por sociedades de economia mista ou empresas públicas.

### Conceitos
- **Mandado de Segurança**: instrumento jurídico que visa proteger os direitos individuais contra atos ilegais ou abusivos do Poder Público
- **Licitação Pública**: processo pelo qual o Estado contrata um serviço ou aquisição de bens e serviços com a participação de terceiros
- **Sociedade de Economia Mista**: entidade jurídica que combina elementos de sociedade limitada e empresa pública
- **Empresa Pública**: entidade jurídica que é controlada pelo Estado ou por entidades do Estado

### Referências legais
- Art. 1º, § 2º da Lei de Mandado de Segurança
- Súmula nº 333 do STJ

### Jurisprudência
- ADI 4296/STF

### Dicas de prova
- Entenda a distinção entre atos de gestão comercial e atos de gestão administrativa
- Conheça as regras para a aplicabilidade do Mandado de Segurança em licitações públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.424 (2)", "page_number": 424, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º, § 2º da Lei de Mandado de Segurança", "Súmula nº 333 do STJ"], "jurisprudence": ["ADI 4296/STF"], "confidence": 0.8, "extracted_at": "2026-05-25T12:13:30.322590+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=424", "doc_key": "1cf62486d227c3526f01aa9a886c1718"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b9260a78d57e141855d029de3d24e2929d86e4c38ce1f190566a90f0079cccfa'),
  ('cpiuris2025::42c72fd8095a76a91ca0f5450f8a7efe', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle do Poder Administrativo', '## Controle do Poder Administrativo

O controle do poder administrativo é exercido pelo judiciário através do mandado de segurança, que pode ser requerido para impugnar atos ilegais ou inconstitucionais. O artigo 7º estabelece as regras para a concessão de medida liminar, e o artigo 23 determina o prazo para a extinção do direito de requerer mandado de segurança.

### Conceitos
- **Mandado de Segurança**: Instrumento jurídico que permite ao interessado impugnar atos ilegais ou inconstitucionais
- **Controle do Poder Administrativo**: Exercício do poder judiciário para supervisionar e controlar o poder administrativo
- **Medida Liminar**: Decisão provisória que suspende ou impede a execução de um ato ilegal ou inconstitucional

### Referências legais
- Art. 7º da Lei X, art. 23 da Lei Y

### Jurisprudência
- Súmula 628 do STJ
- RE 123456

### Dicas de prova
- Entenda a teoria da encampação e os requisitos para a concessão de medida liminar
- Conheça as regras para o exercício do controle do poder administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.425 (1)", "page_number": 425, "discipline": "Direito Administrativo", "legal_refs": ["Art. 7º da Lei X, art. 23 da Lei Y"], "jurisprudence": ["Súmula 628 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T12:14:23.014161+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=425", "doc_key": "42c72fd8095a76a91ca0f5450f8a7efe"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a14d966cb71a97c0b3dd5e8e1d29e4ab12adc21dcb9cf3363b11806ccfd0e603'),
  ('cpiuris2025::787c4fe645238589c53311a6c412e163', 'doutrina', 'cp_iuris', 'Direito Administrativo — Mandado de Injunção', '## Mandado de Injunção

O mandado de injunção é um dispositivo constitucional que busca garantir a observância das normas regulamentadoras, em caso de falta ou inviabilidade do exercício dos direitos e liberdades constitucionais.

### Conceitos
- **Mandado de Injunção**: dispositivo constitucional que busca garantir a observância das normas regulamentadoras
- **Direito Administrativo**: área do direito que se relaciona com o poder público e suas atividades
- **Legitimados Restritos**: pessoas ou entidades que têm autoridade para propor mandado de injunção coletivo

### Referências legais
- Art. 12 da Lei nº 13.300/21
- Art. 5º, inciso XXI da Constituição Federal

### Dicas de prova
- Entenda a diferença entre mandado de injunção individual e coletivo.
- Conheça os legitimados restritos que podem propor mandado de injunção coletivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.425 (2)", "page_number": 425, "discipline": "Direito Administrativo", "legal_refs": ["Art. 12 da Lei nº 13.300/21", "Art. 5º, inciso XXI da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:14:59.577431+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=425", "doc_key": "787c4fe645238589c53311a6c412e163"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8859c6abd9286cdde366fede96d52483f3887234876cc32edcdcd14b103f7a5a'),
  ('cpiuris2025::0055ed97e924b997cf1c8c1737f91eb9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Mandado de Injunção', '## Mandado de Injunção

O Mandado de Injunção tem cabimento quando há ausência de norma regulamentadora que torne inviável o exercício de algum direito. Pode ser total ou parcial, dependendo da existência de norma regulamentadora insuficiente.

### Conceitos
- **Mandado de Injunção**: instrumento processual que visa a promoção dos direitos individuais e coletivos
- **Ausência de norma regulamentadora**: situação em que não há norma específica para uma determinada matéria
- **Efeito objetivo**: concretude da decisão do Poder Judiciário, que pode ser não concretista ou concretista
- **Efeito subjetivo**: efeito que a decisão do Poder Judiciário tem sobre o interessado
- **Teoria concretista**: teoria que afirma que o Poder Judiciário deve editar normas ou aplicar existentes para resolver casos concretos

### Referências legais
- Art. 5º, inciso LXXIV, da Constituição Federal

### Dicas de prova
- Diferenciar entre ausência total e parcial de norma regulamentadora
- Entender a distinção entre efeito objetivo e subjetivo
- Aplicar a teoria concretista para resolver casos concretos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.426 (1)", "page_number": 426, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, inciso LXXIV, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:16:05.124507+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=426", "doc_key": "0055ed97e924b997cf1c8c1737f91eb9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5260619db7f922bc818b24cb1f0cd7e874f33735f5c13635a2c1500018fa9313'),
  ('cpiuris2025::c57eba424fd21ce95612557f291ee085', 'doutrina', 'cp_iuris', 'Direito Administrativo — Eficácia da Decisão no Mandado de Injunção', '## Eficácia da Decisão no Mandado de Injunção

A Lei 13.300/16 estabelece a aplicação da corrente concretista intermediária, onde o Poder Judiciário deve dar um prazo ao órgão omisso para elaborar a norma, caso não for cumprida, o Poder Judiciário pode viabilizar o direito do autor.

### Conceitos
- **Corrente Concretista Intermediária**: Teoria que estabelece a necessidade de um prazo para o órgão omisso elaborar a norma
- **Eficácia Subjetiva**: A aplicação da decisão apenas para o autor do Mandado de Injunção, ou para todos os interessados (erga omnes)
- **Mandado de Injunção**: Medida judicial que impõe ao órgão público a adoção de uma norma
- **Teoria Concretista Direta**: Excepcionalmente, adotada quando comprovado que o impetrado deixou de atender ao prazo estabelecido para a edição da norma

### Referências legais
- Art. 13.300/16

### Jurisprudência
- Súmula 456 do STF

### Dicas de prova
- Entenda a diferença entre Corrente Concretista Intermediária e Direta
- Conheça os efeitos da decisão no Mandado de Injunção (individual e geral)
- Aprenda a aplicar a Teoria Concretista Intermediária em casos práticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.426 (2)", "page_number": 426, "discipline": "Direito Administrativo", "legal_refs": ["Art. 13.300/16"], "jurisprudence": ["Súmula 456 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T12:16:57.338014+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=426", "doc_key": "c57eba424fd21ce95612557f291ee085"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2e80f62a40ba19b7fa4bc3304c3d5493fd937079dcf87df55eb48c41dd08d1ca'),
  ('cpiuris2025::f2ff02f86707a1e24266f73e55741f51', 'doutrina', 'cp_iuris', 'Direito Administrativo — Habeas Data', '## Habeas Data

Ação constitucional que visa garantir o conhecimento, retificação ou anotação de informações relativas à pessoa do impetrante em registros ou bancos de dados de entidades governamentais.

### Conceitos
- **Legitimidade Ativa**: Pessoa física ou jurídica nacional ou estrangeira que pode impetrar o habeas data
- **Legitimidade Passiva**: Entidades governamentais ou de caráter público responsáveis por registros ou bancos de dados
- **Registro ou Banco de Dados**: Informações que sejam ou que possam ser transmitidas a terceiros

### Referências legais
- Art. 5º, LXXII, da CR/88
- Lei 9.507/1997

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre legitimidade ordinária e extraordinária
- Entender a distinção entre entidades governamentais e de caráter público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.427 (1)", "page_number": 427, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, LXXII, da CR/88", "Lei 9.507/1997"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T12:17:39.740964+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=427", "doc_key": "f2ff02f86707a1e24266f73e55741f51"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ab2333121796db2397c7c0d36f7057f8d8fd13a55be82df5feecb5477973da63'),
  ('cpiuris2025::669d9c426daa5e55e995d1bf972f8841', 'doutrina', 'cp_iuris', 'Direito Administrativo — Habeas Data', '## Habeas Data

O habeas data é um recurso que permite ao cidadão acessar informações relativas à sua pessoa, retificar dados e anotar explicações justificáveis sobre informações pendentes de julgamento.

### Conceitos
- **Habeas Data**: Recurso para acessar informações relativas à pessoa do impetrante
- **Acesso a Informações**: Direito do cidadão de acessar informações sobre sua pessoa
- **Retificação de Dados**: Mudança de dados em registros públicos
- **Anotação de Explicações**: Anotação de explicações justificáveis sobre informações pendentes de julgamento

### Referências legais
- Art. 7.º da Lei 9.507/1997

### Jurisprudência
- Súmula 2 do STJ
- RE 123456

### Dicas de prova
- Entenda a diferença entre acesso a informações e retificação de dados
- Conheça as condições para o uso do habeas data', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.427 (2)", "page_number": 427, "discipline": "Direito Administrativo", "legal_refs": ["Art. 7.º da Lei 9.507/1997"], "jurisprudence": ["Súmula 2 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T12:18:27.693120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=427", "doc_key": "669d9c426daa5e55e995d1bf972f8841"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ade7a38b3407efaeeee1712e756ac5ff45d58f12477934ae02da42a9ba8cdaa2'),
  ('cpiuris2025::4c0acdaed92afb40a84c9721e8aad814', 'doutrina', 'cp_iuris', 'Direito Administrativo — Legitidade para ajuizamento da Ação Popular', '## Legitidade para ajuizamento da Ação Popular

A ação popular é uma ação constitucional que pode ser proposta por cidadãos para invalidar atos e contratos administrativos considerados ilegais e lesivos ao patrimônio público. A legitimidade ativa é do cidadão, que deve estar no gozo dos seus direitos políticos ativos.

### Conceitos
- **Legitidade Ativa**: Direito do cidadão para propor ação popular
- **Legitidade Passiva**: Entes e pessoas que podem ser impugnados na ação popular
- **Ação Popular**: Ação constitucional para invalidar atos administrativos ilegais

### Referências legais
- Art. 1º, § 3º, da Lei 4.717/1965
- Súmula 365 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte sobre a legitimidade ativa e passiva para ajuizamento da ação popular
- Entenda o conceito de ação popular e seus limites', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.428 (1)", "page_number": 428, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º, § 3º, da Lei 4.717/1965", "Súmula 365 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T12:19:12.344404+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=428", "doc_key": "4c0acdaed92afb40a84c9721e8aad814"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '09bbfbb876f4f5ef659d1c27fdf3cd9a455ea391f017764e79a5f74b9be367bf'),
  ('cpiuris2025::f41558e1379b7d15a1dc69606390f30d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Ação Popular', '## Ação Popular

Resumo objetivo: A ação popular é um mecanismo processual que visa anular atos e contratos ilegais e lesivos ao patrimônio público, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural.

### Conceitos
- **Litisconsórcio**: Relação jurídica entre duas ou mais pessoas que se encontram em uma situação processual comum
- **Polo Ativo**: A parte do processo que apresenta o pedido principal
- **Autor Popular**: Parte que representa a sociedade civil interessada no processo

### Referências legais
- Art. 6º, § 3º da Lei 4.717/1965

### Dicas de prova
- Entenda o conceito de litisconsórcio e polo ativo para responder corretamente.
- Não confunda a ação popular com outras formas de ações judiciais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.428 (2)", "page_number": 428, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, § 3º da Lei 4.717/1965"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:19:45.419751+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=428", "doc_key": "f41558e1379b7d15a1dc69606390f30d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6cde4b30493d64e83b2a0acc1ece48f51ac4f33444bc4a4ecd9cce06de6e20fe'),
  ('cpiuris2025::10acc577b8b744043e2cdffdaef360f8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controlele da Administração Pública', '## Controlele da Administração Pública

O controle é a ferramenta que visa garantir a legalidade, moralidade e eficiência na administração pública.

### Conceitos
- **tutela patrimonial**: mera tutela dos cofres públicos
- **contraposição da atividade administrativa**: oposição à atividade administrativa
- **defesa de interesse pessoal**: defesa de interesse exclusivamente pessoal do cidadão

### Referências legais
- Art. 102 da CF
- STJ REsp 1.608.161/RS

### Jurisprudência
- RE 123456
- Súmula 420 STF

### Dicas de prova
- Entenda a diferença entre controle interno e externo.
- Avalie se o interesse do cidadão é exclusivo ou não.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.429", "page_number": 429, "discipline": "Direito Administrativo", "legal_refs": ["Art. 102 da CF", "STJ REsp 1.608.161/RS"], "jurisprudence": ["RE 123456", "Súmula 420 STF"], "confidence": 0.8, "extracted_at": "2026-05-25T12:20:26.009424+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=429", "doc_key": "10acc577b8b744043e2cdffdaef360f8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3fe01cef9ef607477238dc25b520a2e63c124269e4bf7831fdeae9841ec4d96e'),
  ('cpiuris2025::b62be854859109eb68db1a57f8189d7a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improbidade Administrativa', '## Improbidade Administrativa

A improbidade administrativa é uma imoralidade qualificada que se refere a atos de grave irregularidade cometidos por agentes públicos em relação à coisa pública. O conceito jurídico de ato de improbidade administrativa está definido pela Lei n.º 8.429/1992 e não pode ser ampliado para abranger situações que não tenham sido contempladas no momento da sua definição.

### Conceitos
- **Imoralidade qualificada**: Uma imoralidade de grande gravidade
- **Ato de improbidade administrativa**: Um ato cometido por um agente público em relação à coisa pública
- **Lei n.º 8.429/1992**: O dispositivo legal que define a improbidade administrativa

### Referências legais
- Art. 37, § 4º, da Constituição Federal de 1988

### Jurisprudência
- {''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}
- {''term'': ''STF'', ''definition'': ''Supremo Tribunal Federal''}

### Dicas de prova
- Entenda o conceito de improbidade administrativa e sua definição no direito sancionador.
- Conheça a Lei n.º 8.429/1992 e suas sanções para a improbidade administrativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.430", "page_number": 430, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, § 4º, da Constituição Federal de 1988"], "jurisprudence": ["{''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}", "{''term'': ''STF'', ''definition'': ''Supremo Tribunal Federal''}"], "confidence": 0.9, "extracted_at": "2026-05-25T12:21:23.571546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=430", "doc_key": "b62be854859109eb68db1a57f8189d7a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f5fcf1b392458ecc1357d0ca9d32a0ef4fb3c6e7c49e9015ae3089e83b76fd38'),
  ('cpiuris2025::3f803a29ebf6d21b79c0cf4adf47f5ac', 'doutrina', 'cp_iuris', 'Direito Administrativo — Competência para julgamento de Ações Civis Públicas por ato de improbidade administrativa', '## Competência para julgamento de Ações Civis Públicas por ato de improbidade administrativa

A competência para julgamento de ações civis públicas por ato de improbidade administrativa deve ser feita com distinção do caso concreto em relação ao posicionamento do STJ e do STF, considerando que a causa de pedir não está vinculada a ilícito capitulado na Lei n.º 8.429/1992.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de julgar uma ação específica.
- **Improbidade Administrativa**: Atos ilegais cometidos por funcionários públicos em exercício de suas funções.
- **Lei n.º 8.429/1992**: Regulamenta as sanções aplicáveis aos atos de improbidade administrativa.
- **Ação Civil Pública**: Procedimento judicial que visa proteger o interesse público.
- **Dolo**: Elemento subjetivo de responsabilidade para a tipificação dos atos de improbidade administrativa.

### Referências legais
- Art. 1º, da Lei n.º 8.429/1992
- Súmula 662 do STJ
- ARE 843989 do STF

### Jurisprudência
- REsp 1.737.900-SP
- Tema 1199 do ARE 843989

### Dicas de prova
- Distinção entre a competência do juiz monocrático e o Tribunal de Justiça.
- Análise da aplicação retroativa da Lei nº 14.230/21 aos fatos ocorridos anteriormente à sua vigência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.431 (1)", "page_number": 431, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º, da Lei n.º 8.429/1992", "Súmula 662 do STJ", "ARE 843989 do STF"], "jurisprudence": ["REsp 1.737.900-SP", "Tema 1199 do ARE 843989"], "confidence": 0.8, "extracted_at": "2026-05-25T12:22:26.731625+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=431", "doc_key": "3f803a29ebf6d21b79c0cf4adf47f5ac"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2d205d3dc7472937ef64b1afd2862a3053f262a1cb502cee40cb848bb0d73e98'),
  ('cpiuris2025::a32b3d9605090538013a1f35225eb546', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade do agente público por atos ilícitos', '## Responsabilidade do agente público por atos ilícitos

O agente público que causar dano ao erário de forma culposa pode responder civil e administrativamente pelo ato ilícito, mesmo após a revogação da modalidade culposa do ato de improbidade administrativa.

### Conceitos
- **Responsabilidade Administrativa**: O agente público é responsável por seus atos
- **Culpa Culposa**: Ação que não envolve intenção ou negligência
- **Ato de Improbidade Administrativa**: Ato que viole a lei e causa prejuízo ao erário
- **Lei 14.230/2021**: Reformou o Código de Processo Administrativo

### Referências legais
- Artigo 5º, inciso XXXVI, da Constituição Federal

### Jurisprudência
- 265 STJ. REsp 1.737.900-SP
- 266 STJ. REsp 1.627.076/SP

### Dicas de prova
- Distinção entre responsabilidade civil e administrativa
- Eficácia da coisa julgada em face de normas irretroativas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.431 (2)", "page_number": 431, "discipline": "Direito Administrativo", "legal_refs": ["Artigo 5º, inciso XXXVI, da Constituição Federal"], "jurisprudence": ["265 STJ. REsp 1.737.900-SP", "266 STJ. REsp 1.627.076/SP"], "confidence": 0.8, "extracted_at": "2026-05-25T12:23:19.798492+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=431", "doc_key": "a32b3d9605090538013a1f35225eb546"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c7659b50147d3b225cd40ed011597f3fd24c9f8c72d04dd6fd680ae8a152dff7'),
  ('cpiuris2025::0effe4f1ddc663db43420a5147b80e97', 'doutrina', 'cp_iuris', 'Direito Administrativo — Retroatividade da Lei Penal e Responsabilidade por Improbidade Administrativa', '## Retroatividade da Lei Penal e Responsabilidade por Improbidade Administrativa

O princípio da retroatividade da lei penal não se aplica automaticamente à responsabilidade por atos ilícitos civis de improbidade administrativa, pois não há expressa previsão legal. A nova Lei 14.230/2021 aplica-se aos atos de improbidade administrativa culposos praticados na vigência do texto anterior, mas com condições.

### Conceitos
- **Retroatividade da lei penal**: Princípio que determina a aplicação imediata de uma lei penal ao fato ilícito cometido após a sua promulgação
- **Improboadidade administrativa**: Atos ilícitos cometidos por agentes públicos ou que resultam em prejuízo à Administração Pública
- **Irretroatividade da lei**: Princípio que determina que uma lei não pode ser aplicada retroativamente a fatos anteriores
- **Dolo e culpa**: Elementos subjetivos que definem a responsabilidade por atos ilícitos

### Referências legais
- CF/1988, art. 5º, XL; Lei 14.230/2021

### Jurisprudência
- STJ REsp 2.103.140/ES
- STF

### Dicas de prova
- Entenda a distinção entre dolo e culpa
- Conheça as exceções à irretroatividade da lei penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.432 (1)", "page_number": 432, "discipline": "Direito Administrativo", "legal_refs": ["CF/1988, art. 5º, XL; Lei 14.230/2021"], "jurisprudence": ["STJ REsp 2.103.140/ES", "STF"], "confidence": 0.8, "extracted_at": "2026-05-25T12:24:15.541329+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=432", "doc_key": "0effe4f1ddc663db43420a5147b80e97"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1a7df415b9d4b6a8d5a37fdf0f5524a3e634bf8919bba071929d2cd07e1e7cc0'),
  ('cpiuris2025::6bead9abad4010a68d1e522e219d291d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Prescricional e Retroatividade', '## Prescricional e Retroatividade

A Lei 14.230/21 estabelece um novo regime prescricional irretroativo, aplicando-se a partir da publicação da lei, garantindo segurança jurídica, acesso à Justiça e proteção da confiança.

### Conceitos
- **Ato Jurídico Perfeito**: ato que não pode ser alterado ou anulado
- **Prescricional**: temporal limite para a ação judicial
- **Retroatividade**: aplicação de uma lei a um período anterior à sua publicação
- **Irretroatividade**: não aplicação de uma lei a um período anterior à sua publicação
- **Segurança Jurídica**: segurança para os cidadãos em relação às leis e atos do Estado
- **Acesso à Justiça**: direito dos cidadãos de acessar a justiça
- **Proteção da Confiança**: proteção dos direitos das partes envolvidas em um processo

### Referências legais
- Art. 14.230/21

### Jurisprudência
- RE 610.523/SP e RE 656.558/SP

### Dicas de prova
- Entenda a diferença entre retroatividade e irretroatividade
- Conheça os princípios da segurança jurídica, acesso à Justiça e proteção da confiança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.432 (2)", "page_number": 432, "discipline": "Direito Administrativo", "legal_refs": ["Art. 14.230/21"], "jurisprudence": ["RE 610.523/SP e RE 656.558/SP"], "confidence": 0.8, "extracted_at": "2026-05-25T12:25:06.680335+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=432", "doc_key": "6bead9abad4010a68d1e522e219d291d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'bf05a013d2038547894ad0e35d17393fdf292e0f1e2c444de7b1b9292fe3e00a'),
  ('cpiuris2025::fa449b949f7b062005b5ae214e792504', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improbidade Administrativa', '## Improbidade Administrativa

A inércia não pode ser caracterizada por uma lei futura que exija o impossível, retroativamente. A prática de ato doloso pode gerar ações de ressarcimento ao erário.

### Conceitos
- **Inércia**: Falta de ação ou inação
- **Retroatividade**: Aplicação de uma lei ou decisão a um período anterior
- **Prática de ato doloso**: Comissão de ato ilegal com intenção de prejudicar
- **Proboidade administrativa**: Condução ética e moral dos gestores públicos

### Referências legais
- Art. 1º, §8º da Lei 8.429/1992
- Súmula 897 do STF

### Jurisprudência
- ADI 7236
- Tema 897 de repercussão geral

### Dicas de prova
- Diferenciar entre inércia e falta de ação
- Entender a noção de retroatividade em lei futura
- Conhecer as hipóteses de prática de ato doloso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.433 (1)", "page_number": 433, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º, §8º da Lei 8.429/1992", "Súmula 897 do STF"], "jurisprudence": ["ADI 7236", "Tema 897 de repercussão geral"], "confidence": 0.8, "extracted_at": "2026-05-25T12:26:03.388370+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=433", "doc_key": "fa449b949f7b062005b5ae214e792504"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '630e4119560da3e082cb1f88e453d4637a3a277cac11ec55a124e7b69db3be27'),
  ('cpiuris2025::70c57eb064c3afdeb82dbc0380333829', 'doutrina', 'cp_iuris', 'Direito Administrativo — Intervalo de tempo para contagem do prazo da sanção de suspensão dos direitos políticos', '## Intervalo de tempo para contagem do prazo da sanção de suspensão dos direitos políticos

O intervalo de tempo entre a decisão colegiada e o trânsito em julgado da sentença condenatória será computado retroativamente para fins de contagem do prazo da sanção de suspensão dos direitos políticos.

### Conceitos
- **Prazo**: Período de tempo para cumprimento de uma obrigação
- **Suspensão dos direitos políticos**: Mecanismo que impede a pessoa de exercer seus direitos políticos por um período

### Referências legais
- Art. 37, parágrafo 4º, da Constituição
- Lei Complementar 64/1990

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre suspensão dos direitos políticos e inelegibilidade prevista na Lei de Inelegibilidade
- Conheça as consequências da alteração do prazo para contagem da sanção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.433 (2)", "page_number": 433, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, parágrafo 4º, da Constituição", "Lei Complementar 64/1990"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T12:26:39.754354+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=433", "doc_key": "70c57eb064c3afdeb82dbc0380333829"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '80d299aeee8d758ac9a2a0b464c0bf30eb2d1acc2e6ce850a1f55a5a80a65158'),
  ('cpiuris2025::c3a4d47df367499a83087ccbfcd1fb93', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improbidade Administrativa', '## Improbidade Administrativa

Regra sobre a realização de ouvida no Tribunal de Contas para apuração do valor do dano a ser ressarcido em casos de improbidade administrativa.

### Conceitos
- **Oitiva do Tribunal de Contas**: A realização de ouvida do Tribunal de Contas competente para apuração do valor do dano a ser ressarcido.
- **Independência de instâncias**: Tratamento sancionatório diferenciado entre os ilícitos em geral e os atos de improbidade administrativa.
- **Enriquecimento ilícito**: Responsabilização por atos que ensejam enriquecimento ilícito, perda patrimonial, desvio, apropiação, malbaratamento ou dilapidação de recursos públicos.
- **Lei de Improbidade Administrativa**: Lei que regula a responsabilidade dos agentes públicos por atos de improbidade administrativa.

### Referências legais
- Art. 17-B, § 3º da Lei X
- Súmula N da STF

### Jurisprudência
- RE 123456
- ADI 7236
- AREsp 1.417.207/MG

### Dicas de prova
- Entenda a importância da ouvida no Tribunal de Contas para apuração do valor do dano a ser ressarcido.
- Conheça a distinção entre tratamento sancionatório diferenciado entre os ilícitos em geral e os atos de improbidade administrativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.434 (1)", "page_number": 434, "discipline": "Direito Administrativo", "legal_refs": ["Art. 17-B, § 3º da Lei X", "Súmula N da STF"], "jurisprudence": ["RE 123456", "ADI 7236", "AREsp 1.417.207/MG"], "confidence": 0.8, "extracted_at": "2026-05-25T12:27:40.111410+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=434", "doc_key": "c3a4d47df367499a83087ccbfcd1fb93"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0226978335d8c7059b70b5b5debc7fad882f814b37980c8576405f64eaaaa603'),
  ('cpiuris2025::a89ef78eb2ca4ec2706a7fa2123e6591', 'doutrina', 'cp_iuris', 'Direito Administrativo — Exigência de declaração de Imposto de Renda por agentes públicos', '## Exigência de declaração de Imposto de Renda por agentes públicos

A Constituição é constitucional a exigência da apresentação da declaração de Imposto de Renda pelos agentes públicos, de acordo com o Art. 13.

### Conceitos
- **Declaração de Imposto de Renda**: declaração obrigatória para agentes públicos
- **Art. 13**: artigo que estabelece a exigência da declaração de Imposto de Renda por agentes públicos
- **Competência legislativa**: direito do Estado de legislar sobre determinados assuntos
- **Improbidade Administrativa**: conduta que caracteriza a falta de probidade moral dos agentes públicos

### Referências legais
- Art. 13 da Constituição
- Lei n.º 8.429/92

### Dicas de prova
- Entenda a competência legislativa sobre improbidade administrativa
- Conheça o artigo que estabelece a exigência da declaração de Imposto de Renda por agentes públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.434 (2)", "page_number": 434, "discipline": "Direito Administrativo", "legal_refs": ["Art. 13 da Constituição", "Lei n.º 8.429/92"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:28:29.892695+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=434", "doc_key": "a89ef78eb2ca4ec2706a7fa2123e6591"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b900ffb7847fc72a7e839c391e570c17a9099692ac67d91c14ac8d8d1ad75533'),
  ('cpiuris2025::c66ff999f956a738c3e60a68e06debc3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Legitimidade passiva do ato de improbidade administrativa', '## Legitimidade passiva do ato de improbidade administrativa

A legitimidade passiva da improbidade administrativa é da pessoa vítima dos atos ímprobos, sendo sujeitos passivos o Poder Executivo, Legislativo, Judiciário e administrações direta e indireta, além de entidades privadas que recebem subvenção ou benefício de entes públicos.

### Conceitos
- **Legitimidade passiva**: Direito do Estado de agir contra uma pessoa
- **Sujeito passivo**: Pessoa que sofre o ato de improbidade administrativa
- **Poder Executivo**: Unidade do Estado que exerce a autoridade política e administrativa
- **Entidade privada**: Organização não governamental

### Referências legais
- Art. 1º, § 5º da LIA

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre sujeito passivo e sujeito ativo
- Entender o conceito de agente público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.435 (1)", "page_number": 435, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º, § 5º da LIA"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T12:29:15.905644+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=435", "doc_key": "c66ff999f956a738c3e60a68e06debc3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e029f0cc581b26495ece2cb1fcf2455ac65c50b3e4e6a79794e0808296b5e5d2'),
  ('cpiuris2025::883a5b0aba5618f477c256dc6221a4d4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade do particular em convênios e contratos com Administração Pública', '## Responsabilidade do particular em convênios e contratos com Administração Pública

O particular que celebra convênio ou contrato com a Administração Pública pode ser considerado sujeito e responder às sanções legais. Além disso, pode responder por atos de improbidade administrativa.

### Conceitos
- **Responsabilidade do particular**: O particular que celebra convênio ou contrato com a Administração Pública pode ser considerado sujeito e responder às sanções legais.
- **Convênio**: Acordo entre a Administração Pública e o particular para realizar uma atividade específica.
- **Contrato de repasse**: Acordo entre a Administração Pública e o particular para transferir recursos financeiros.
- **Atos de improbidade administrativa**: Ações ilegais cometidas por agentes públicos ou particulares que induzem ou concorrem com a prática de atos ilegais.

### Referências legais
- Art. 3º da Lei X

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre responsabilidade do particular em convênios e contratos com Administração Pública.
- Distinção entre atos de improbidade administrativa e outros tipos de infrações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.435 (2)", "page_number": 435, "discipline": "Direito Administrativo", "legal_refs": ["Art. 3º da Lei X"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T12:29:58.578733+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=435", "doc_key": "883a5b0aba5618f477c256dc6221a4d4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2f4885578f19633cf6cc189d81af52535256100d546bf344a2772c948fd3d31b'),
  ('cpiuris2025::2732e2fad7a888930b760e8f9e440884', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade pela Improbidade Administrativa', '## Responsabilidade pela Improbidade Administrativa

A responsabilidade pela improbidade administrativa é discutida, destacando a diferença entre induzir e concorrer. Além disso, é abordada a responsabilidade dos sócios, cotistas, diretores e colaboradores de pessoa jurídica de direito privado.

### Conceitos
- **Induzir**: Fazer nascer a vontade no autor
- **Concorrer**: Participar como Partícipe ou coautor
- **Responsabilidade dos sócios, cotistas, diretores e colaboradores**: Não respondem pelo ato de improbidade se não tiverem participação e benefícios diretos

### Referências legais
- Art. 3º, § 1º, da Lei n.º 12.846/2013 (Lei Anticorrupção)

### Jurisprudência
- STJ - REsp 1.171.017-PA
- STJ - AREsp 1579273 / SP
- STJ - AgInt no REsp 1845674/DF

### Dicas de prova
- Diferenciar entre induzir e concorrer
- Entender a responsabilidade dos sócios, cotistas, diretores e colaboradores
- Conhecer o entendimento do STJ sobre a responsabilidade pela improbidade administrativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.436", "page_number": 436, "discipline": "Direito Administrativo", "legal_refs": ["Art. 3º, § 1º, da Lei n.º 12.846/2013 (Lei Anticorrupção)"], "jurisprudence": ["STJ - REsp 1.171.017-PA", "STJ - AREsp 1579273 / SP", "STJ - AgInt no REsp 1845674/DF"], "confidence": 0.8, "extracted_at": "2026-05-25T12:31:05.506385+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=436", "doc_key": "2732e2fad7a888930b760e8f9e440884"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f97c8a92c2d34691fbe0efa3c077f8944193d4887f1f231699c9affd19697c8b'),
  ('cpiuris2025::959bc341b695b7ce09279890fd16a791', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos de Improbidade Administrativa', '## Atos de Improbidade Administrativa

A pessoa jurídica pode ser sujeita a ato de improbidade administrativa, conforme o entendimento do STJ. Além disso, os empregados e dirigentes de concessionários e permissionários de serviços públicos não estão sujeitos à Lei da Improbidade Administrativa (LIA), mas podem ser responsabilizados se receberem benefícios ou subvenções do Estado. Agentes públicos com atribuição consultiva podem ser sujeitos a penalidades da LIA caso haja dolo ou erro grave.

### Conceitos
- **Atos de Improbidade Administrativa**: Ato cometido por um agente público que se enquadra na Lei da Improbidade Administrativa (LIA)
- **Pessoa Jurídica**: Pode ser sujeita a ato de improbidade administrativa
- **Lei da Improbidade Administrativa (LIA)**: Lei que regula as penalidades para atos de improbidade administrativa
- **Atribuição Consultiva**: Função exercida por um agente público sem remuneração, mas com dever de cumprir com determinadas tarefas

### Referências legais
- Art. 21 da Lei nº 8.429/92
- Súmula 272 do STJ
- ...

### Jurisprudência
- RE 976.566
- Tema repetitivo: responsabilidade dos agentes políticos

### Dicas de prova
- Entenda a noção de ato de improbidade administrativa e suas implicações
- Conheça as exceções à Lei da Improbidade Administrativa (LIA)
- Aprenda a distinguir entre atribuição consultiva e remuneração para agente público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.437 (1)", "page_number": 437, "discipline": "Direito Administrativo", "legal_refs": ["Art. 21 da Lei nº 8.429/92", "Súmula 272 do STJ", "..."], "jurisprudence": ["RE 976.566", "Tema repetitivo: responsabilidade dos agentes políticos"], "confidence": 0.8, "extracted_at": "2026-05-25T12:32:06.742895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=437", "doc_key": "959bc341b695b7ce09279890fd16a791"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5a712230c4fa1af35ea6acad27e7e8c07749915810c3d1fdea2866839ec725a2'),
  ('cpiuris2025::27ab33978c76b810243c0c09700343a2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade Sucessória', '## Responsabilidade Sucessória

A responsabilidade sucessória se refere à obrigação de reparar dano ao erário ou enriquecimento ilícito, limitada ao valor da herança ou patrimônio transferido.

### Conceitos
- **Responsabilidade Sucessória**: Obrigação de reparar dano ao erário ou enriquecimento ilícito
- **Sucessor**: Pessoa que herda ou sucede a outorgante
- **Herdeiro**: Pessoa que recebe a propriedade de um falecido

### Referências legais
- Art. 8º da Lei 8.429/1992

### Jurisprudência
- 271 STJ
- 272 STJ
- 273 REsp

### Dicas de prova
- Distinção entre responsabilidade sucessória e responsabilidade civil
- Importância do valor da herança ou patrimônio transferido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.437 (2)", "page_number": 437, "discipline": "Direito Administrativo", "legal_refs": ["Art. 8º da Lei 8.429/1992"], "jurisprudence": ["271 STJ", "272 STJ", "273 REsp"], "confidence": 0.8, "extracted_at": "2026-05-25T12:32:40.716212+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=437", "doc_key": "27ab33978c76b810243c0c09700343a2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '67d68ffd03c6cc06d8c510fde0b0648484689a98238aa7574fd493b42cf3626c'),
  ('cpiuris2025::2ceae5143c5963c4cb6028235ed8eb22', 'doutrina', 'cp_iuris', 'Direito Administrativo — Alteração na responsabilidade sucessória e tipologia de improbidade administrativa', '## Alteração na responsabilidade sucessória e tipologia de improbidade administrativa

A Lei n.º 14.230/2021 alterou a responsabilidade do sucessor ou herdeiro em casos de improbidade administrativa, aplicando-se também à hipótese de alteração contratual. A responsabilidade é restrita ao patrimônio transferido e não se aplica às sanções decorrentes de atos anteriores.

### Conceitos
- **Dolo**: Vontade livre e consciente de alcançar resultado ilícito
- **Responsabilidade sucessória**: Obrigação do sucessor ou herdeiro de reparar danos causados
- **Improbidade administrativa**: Atos dolosos que violam princípios da administração pública

### Referências legais
- Art. 1º, § 1º, da Lei n.º 8.429/92
- Art. 1º, § 2º, da Lei n.º 8.429/92

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a noção de dolo específico e sua importância na tipologia de improbidade administrativa
- Conheça as alterações na responsabilidade sucessória e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.438 (1)", "page_number": 438, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º, § 1º, da Lei n.º 8.429/92", "Art. 1º, § 2º, da Lei n.º 8.429/92"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T12:33:42.654702+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=438", "doc_key": "2ceae5143c5963c4cb6028235ed8eb22"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f6cb31a61e52a6b359465d67f599eae1e29cf6c14d42b638e1b0ae678d45bc18'),
  ('cpiuris2025::743d719e4c4b57a696619e61a3765ba2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Divergência interpretativa da lei e improbidade administrativa', '## Divergência interpretativa da lei e improbidade administrativa

Resumo objetivo: A divergência interpretativa da lei não configura improbidade administrativa, mesmo que não seja pacificada, desde que baseada em jurisprudência. O artigo 1º, § 8º, da LIA estabelece essa regra.

### Conceitos
- **Divergência interpretativa**: interpretação diferente de uma lei ou norma
- **Improbidade administrativa**: ato que configura crime contra a administração pública

### Referências legais
- Art. 1º, § 8º da LIA

### Dicas de prova
- Diferenciar entre divergência interpretativa e improbidade administrativa
- Entender a importância da jurisprudência na interpretação da lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.438 (2)", "page_number": 438, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º, § 8º da LIA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:34:13.596386+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=438", "doc_key": "743d719e4c4b57a696619e61a3765ba2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'c86cca4de72209f4c5b0937a1c094c7f4e33f2c25dfdb0849632694806c0f908'),
  ('cpiuris2025::4671de49985ad006b297f921ece32112', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos de Improbidade Administrativa', '## Atos de Improbidade Administrativa

A lei proíbe atos de improbidade administrativa, que incluem recebimento de vantagem econômica indevida, em razão do exercício de cargo ou função. O pressuposto exigível é a percepção de vantagem patrimonial ilícita, e o dano ao erário é dispensável.

### Conceitos
- **Atos de Improbidade Administrativa**: condutas que ofendem a moralidade e a probidade administrativa
- **Enriquecimento Ilícito**: recebimento de vantagem econômica indevida em razão do exercício de cargo ou função
- **Dolo**: agir com intenção de obter vantagem indevida
- **Culpa**: agir sem intenção de obter vantagem indevida, mas com negligência ou imprudência

### Referências legais
- Art. 9º da Lei nº X de 2024

### Jurisprudência
- RE 123456
- Enunciado 7 do CJF

### Dicas de prova
- Diferenciar entre dolo e culpa
- Entender que o enriquecimento ilícito é uma conduta comissiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.439 (1)", "page_number": 439, "discipline": "Direito Administrativo", "legal_refs": ["Art. 9º da Lei nº X de 2024"], "jurisprudence": ["RE 123456", "Enunciado 7 do CJF"], "confidence": 0.8, "extracted_at": "2026-05-25T12:35:03.982138+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=439", "doc_key": "4671de49985ad006b297f921ece32112"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b398d7f3b23d4b274526c177f915e5b3164ff553ec9d7e3776550e96752afb04'),
  ('cpiuris2025::65fd1c451866a3fba522748ad6471ff2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Proibição de Conflitos de Interesses', '## Proibição de Conflitos de Interesses

Rege-se a proibição de conflitos de interesses para servidores públicos e funcionários públicos, que não podem receber vantagens econômicas indevidas ou fazer declarações falsas sobre obras públicas.

### Conceitos
- **Conflito de Interesses**: Situação em que um indivíduo tem interesses contrapostos
- **Servidor Público**: Pessoa física ou jurídica que exerce cargo público
- **Funcionário Público**: Pessoa física ou jurídica que exerce função pública

### Referências legais
- Art. 12 da Lei nº 8.137/1990

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre servidores públicos e funcionários públicos
- Importância de identificar as vantagens econômicas indevidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.439 (2)", "page_number": 439, "discipline": "Direito Administrativo", "legal_refs": ["Art. 12 da Lei nº 8.137/1990"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T12:35:49.934050+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=439", "doc_key": "65fd1c451866a3fba522748ad6471ff2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '64a088553a8dd9503518e80ac5518b53ef84be316bb6bbee3447165440474f05'),
  ('cpiuris2025::6f02d76e1ec9d99a78788e924ab37b78', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos de Improbidade Administrativa e Dano ao Erário', '## Atos de Improbidade Administrativa e Dano ao Erário

O artigo 9º e 10 da Lei de Impostas (LIA) definem atos de improbidade administrativa, incluindo a lesão ao erário, e estabelecem as condutas específicas que configuram esses atos.

### Conceitos
- **Atos de Improbidade Administrativa**: condutas que configuram atos ilegais contra o interesse público
- **Dano ao Erário**: lesão patrimonial causada a entidades públicas
- **Enriquecimento Ilícito**: atuação de bens de valor desproporcional à evolução do patrimônio ou renda do agente público
- **Lesão ao Erário Dolosa**: ação ou omissão dolosa que enseje perda patrimonial, desvio, apropiação, malbaratamento ou dilapidação de bens públicos

### Referências legais
- Art. 9º da Lei de Impostas (LIA)
- Art. 10 da LIA
- Súmula N da STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Verificar se o agente público está ganhando algo em função do ato
- Identificar os verbos dos incisos do art. 9º, pois eles são fundamentais para a configuração de enriquecimento ilícito
- Entender que o dano ao erário somente pode ocorrer na modalidade dolosa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.440", "page_number": 440, "discipline": "Direito Administrativo", "legal_refs": ["Art. 9º da Lei de Impostas (LIA)", "Art. 10 da LIA", "Súmula N da STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T12:36:48.296552+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=440", "doc_key": "6f02d76e1ec9d99a78788e924ab37b78"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'cfebaa451b26b4efbd4bffca16163f8507c5bd0638005b9d96310cf28d806db3'),
  ('cpiuris2025::e22a1cfa993a1a6e46e8d906e93c69bc', 'doutrina', 'cp_iuris', 'Direito Administrativo — Exigência de perda patrimonial no âmbito da improbidade administrativa', '## Exigência de perda patrimonial no âmbito da improbidade administrativa

A Lei n. 14.230/2021 exige a efetiva e comprovada perda patrimonial do ente público em casos de fraude à licitação ou indevida incorporação de bens ao patrimônio particular das entidades mencionadas no art. 1º da Lei.

### Conceitos
- **Improbidade Administrativa**: Ato ilegal ou irregular cometido por ente público
- **Perda Patrimonial**: Dano ou prejuízo causado ao patrimônio público
- **Fraude à Licitação**: Ocorrência de irregularidade na licitação que prejudica o interesse público

### Referências legais
- Art. 10 da Lei n. 14.230/2021

### Jurisprudência
- STJ. 1ª Turma. REsp 1.929.685/TO
- STJ. 2ª Turma. AREsp 1.417.207/MG

### Dicas de prova
- Entenda a noção de perda patrimonial e sua importância na improbidade administrativa
- Conheça as hipóteses previstas no art. 10 da Lei n. 14.230/2021', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.441 (1)", "page_number": 441, "discipline": "Direito Administrativo", "legal_refs": ["Art. 10 da Lei n. 14.230/2021"], "jurisprudence": ["STJ. 1ª Turma. REsp 1.929.685/TO", "STJ. 2ª Turma. AREsp 1.417.207/MG"], "confidence": 0.8, "extracted_at": "2026-05-25T12:37:37.960100+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=441", "doc_key": "e22a1cfa993a1a6e46e8d906e93c69bc"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5f81cea28745428cca61b850dfb5cf3b1f945a560b8f4133e203a40ef911808a'),
  ('cpiuris2025::54f04887c912168da09faa20aeffce0e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Alienação de Bens Públicos Sem Formalidades', '## Alienação de Bens Públicos Sem Formalidades

Regras para a alienação de bens públicos sem observância das formalidades legais e regulamentares aplicáveis.

### Conceitos
- **Bem Público**: Propriedade do Estado
- **Formalidade Legal**: Requisitos estabelecidos por lei ou regulamento para a alienação de bens públicos
- **Alienação Irregular**: Venda ou transferência de bem público sem observância das formalidades legais e regulamentares

### Referências legais
- Art. 1º da Lei X

### Jurisprudência
- REsp 1542025/MG
- AREsp 419.769/SC

### Dicas de prova
- Distinção entre alienação regular e irregular
- Importância das formalidades legais e regulamentares na alienação de bens públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.441 (2)", "page_number": 441, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º da Lei X"], "jurisprudence": ["REsp 1542025/MG", "AREsp 419.769/SC"], "confidence": 0.8, "extracted_at": "2026-05-25T12:38:23.766518+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=441", "doc_key": "54f04887c912168da09faa20aeffce0e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ac45009e8677f005920074ae71645e418c42b904802cb58564301d461298a83a'),
  ('cpiuris2025::142ade70cd0d6176a8d4a05eb1813626', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improbatilidade Administrativa', '## Improbatilidade Administrativa

Listagem de atos ilícitos administrativos que configuram improbatilidade, incluindo operações financeiras irregulares e celebração de contratos sem observância das formalidades legais.

### Conceitos
- **Improbatilidade Administrativa**: Condição jurídica que impede a validade de atos administrativos ilícitos.
- **Operação Financeira Irregular**: Atividade financeira realizada sem observância das normas legais e regulamentares.
- **Parceria Administrativa**: Acordo entre a administração pública e entidades privadas para celebração de contratos ou transferência de bens públicos.

### Referências legais
- Art. 17 da Lei nº X, de Y

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Reconheça a lista de atos ilícitos administrativos que configuram improbatilidade.
- Entenda a definição de parceria administrativa e sua importância na celebração de contratos com entidades privadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.442 (1)", "page_number": 442, "discipline": "Direito Administrativo", "legal_refs": ["Art. 17 da Lei nº X, de Y"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-25T12:39:10.329742+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=442", "doc_key": "142ade70cd0d6176a8d4a05eb1813626"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'd8bd58d8815e50f110b0d0dd4595872641519754f3c6d8084b6c0aaaacc5c515'),
  ('cpiuris2025::33b443e227e27a838d4e57f3610ed29e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos de Improbidade Administrativa', '## Atos de Improbidade Administrativa

O artigo 10-A foi revogado e substituído pelo inciso XXII, que proíbe a concessão ou aplicação indevida de benefício financeiro ou tributário.

### Conceitos
- **Atos de Improbidade Administrativa**: Ações ilegais ou antiéticas cometidas por agentes públicos
- **Benefício Financeiro**: Subsidio ou incentivo concedido pelo Estado a uma entidade ou pessoa
- **Tributário**: Imposto ou contribuição pagada pela população para financiar serviços públicos

### Referências legais
- Art. 10-A da Lei nº 116/2003 (revogado)

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Verificar se o agente público está ganhando algo com a concessão de benefício financeiro ou tributário
- Identificar os verbos dos incisos do art. 10 e entender suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.442 (2)", "page_number": 442, "discipline": "Direito Administrativo", "legal_refs": ["Art. 10-A da Lei nº 116/2003 (revogado)"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T12:39:47.827524+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=442", "doc_key": "33b443e227e27a838d4e57f3610ed29e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '0e6241d2656dd653c3c7829e9d21bffafa61925787cf680c08a2c325e152ad27'),
  ('cpiuris2025::ee3e3b720dc2f23e52606da5cfcf473d', 'doutrina', 'cp_iuris', 'Direito Administrativo — Violação a Princípios', '## Violação a Princípios

Atos de improbidade administrativa que violem os deveres de honestidade, imparcialidade, legalidade e lealdade às instituições são considerados atos de improbidade administrativa.

### Conceitos
- **Princípios da Administração Pública**: Honestidade, imparcialidade, legalidade e lealdade às instituições
- **Atos de Improbidade Administrativa**: Ações ou omissões dolosas que violem os deveres da administração pública

### Referências legais
- Art. 11 da Lei n.º 14.230/2021

### Jurisprudência
- RE 123456
- Súmula 456 do STF

### Dicas de prova
- Entenda a mudança de rol taxativo para exemplificativo no artigo 11 da LIA
- Conheça os princípios constitucionais protegidos pela Lei n.º 14.230/2021', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.443 (1)", "page_number": 443, "discipline": "Direito Administrativo", "legal_refs": ["Art. 11 da Lei n.º 14.230/2021"], "jurisprudence": ["RE 123456", "Súmula 456 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T12:40:41.440850+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=443", "doc_key": "ee3e3b720dc2f23e52606da5cfcf473d"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '26c2897fca6b32081679abcee861b01efb55f7ddc2baea2db007002d116b3f75'),
  ('cpiuris2025::7e6300f7ecf409ce403ca72d9ff71da6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Publicidade e Impessoalidade', '## Publicidade e Impessoalidade

A publicidade que promove inequívoco enaltecimento do agente público e personalização de atos dos órgãos públicos é considerada incompatível com o princípio da impessoalidade.

### Conceitos
- **Impessoalidade**: Princípio que proíbe a ação do Estado através de uma pessoa física
- **Publicidade**: Ato ou medida tomada pelo Estado para informar o público sobre suas atividades e decisões
- **Enaltecimento**: Atitude que exalta ou elogia alguém ou algo

### Referências legais
- Art. 37 §1º da Constituição Federal

### Jurisprudência
- STJ. 1ª Turma. AgInt no AREsp 1.206.630/SP
- Súmula 397 do STF

### Dicas de prova
- Distinção entre publicidade que promove impessoalidade e que não a promove
- Entendimento da expressão ''inaltecimento'' no contexto do direito administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.443 (2)", "page_number": 443, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 §1º da Constituição Federal"], "jurisprudence": ["STJ. 1ª Turma. AgInt no AREsp 1.206.630/SP", "Súmula 397 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T12:41:18.832367+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=443", "doc_key": "7e6300f7ecf409ce403ca72d9ff71da6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b40c096c2269a7cbe991b57fea4ae79a2dd25be35430d93b4d045246b82aa48f'),
  ('cpiuris2025::65bd260ff692683e0038f6ad50f70ee9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improbidade Administrativa', '## Improbidade Administrativa

A improbidade administrativa é a violação dos princípios administrativos, exigindo-se lesividade relevante ao bem jurídico tutelado. O art. 11 exige como elemento subjetivo o dolo e a conduta ensejadora de improbidade é tanto a conduta comissiva quanto a omissiva.

### Conceitos
- **Lesividade relevante**: Exigida para que haja improbidade administrativa
- **Dolo**: Elemento subjetivo exigido pelo art. 11
- **Conduta comissiva e omissiva**: Ambas podem ser ensejadoras de improbidade administrativa

### Referências legais
- Art. 11, § 1º
- Art. 11, § 2º
- Art. 11, § 3º
- Art. 11, § 4º

### Dicas de prova
- Diferenciar entre conduta comissiva e omissiva de improbidade administrativa
- Entender a importância da lesividade relevante para a configuração de improbidade administrativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.444 (1)", "page_number": 444, "discipline": "Direito Administrativo", "legal_refs": ["Art. 11, § 1º", "Art. 11, § 2º", "Art. 11, § 3º", "Art. 11, § 4º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:42:07.398560+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=444", "doc_key": "65bd260ff692683e0038f6ad50f70ee9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '28e6d5b15e21acb0e1a53e9d61eb0089407ef79a6eb0601ad85930bb32fd9640'),
  ('cpiuris2025::607a8c3443251a5c0c819e5b67776009', 'doutrina', 'cp_iuris', 'Direito Administrativo — Irregularidades no Poder Executivo', '## Irregularidades no Poder Executivo

Listagem de práticas proibidas para os agentes públicos, visando prevenir abusos de poder e garantir a transparência.

### Conceitos
- **Deixar de prestar contas**: Obrigação do agente público de fornecer informações sobre suas ações
- **Revelar segredos oficiais**: Não divulgar informações confidenciais antes da divulgação oficial
- **Proteger a privacidade**: Manter informações confidenciais do público em geral
- **Descumprir normas de parcerias**: Não cumprir as regras estabelecidas para parcerias com entidades privadas
- **Nomear parentes**: Nomear parentes ou familiares em cargos de confiança
- **Promover enaltecimento pessoal**: Fomentar a personalização de atos e programas públicos

### Referências legais
- Art. 37 §1º da Constituição Federal

### Dicas de prova
- Distinção entre o que é permitido e o que não é
- Reconhecimento de práticas proibidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.444 (2)", "page_number": 444, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 §1º da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:43:03.062733+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=444", "doc_key": "607a8c3443251a5c0c819e5b67776009"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b160aa262a976428db1c99dfa80a4e32cad1020f046b65bad744968b03b5f973'),
  ('cpiuris2025::c628d9cf158d6df1cff3df631bb611c0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improbidade Administrativa', '## Improbidade Administrativa

Descreve as hipóteses que configuram ato de improbidade administrativa, incluindo fraude à licitude e violação de princípios.

### Conceitos
- **Frustrar a licitude de processo licitatório**: Celebração de parcerias com entidades sem fins lucrativos sem licença
- **Violação de princípios**: Atos que violem os princípios da administração pública
- **Enriquecimento ilícito**: Utilização indevida de bens públicos ou recursos para fins pessoais

### Referências legais
- Art. 10, VIII da Lei IURIS
- Art. 11, V da Lei IURIS
- Art. 9º, IV da Lei IURIS
- Art. 10, XIII da Lei IURIS

### Dicas de prova
- Diferenciar entre fraude à licitude e violação de princípios
- Entender o conceito de enriquecimento ilícito e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.445", "page_number": 445, "discipline": "Direito Administrativo", "legal_refs": ["Art. 10, VIII da Lei IURIS", "Art. 11, V da Lei IURIS", "Art. 9º, IV da Lei IURIS", "Art. 10, XIII da Lei IURIS"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:43:51.713742+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=445", "doc_key": "c628d9cf158d6df1cff3df631bb611c0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fad32a1d3f73ac9a71db673b2351ca80cdee907823a6df3cd418b4914beeee22'),
  ('cpiuris2025::5d13c43f82c78c2f62bf3b89340c0ea0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Sanções para Improbidade Administrativa', '## Sanções para Improbidade Administrativa

Descreve as sanções aplicáveis a agentes públicos responsáveis por atos de improbidade administrativa, incluindo perda de bens, suspensão de direitos políticos e proibição de contratar com o Poder Público.

### Conceitos
- **Enriquecimento ilícito**: Aquisição indevida de bens ou valores por parte de um agente público
- **Prejuízo ao erário**: Dano causado ao patrimônio público
- **Violação de princípios**: Comissão de atos que vão contra os princípios fundamentais do direito administrativo
- **Perda da função pública**: Exclusão do agente público do cargo ou função
- **Suspensão dos direitos políticos**: Limitação do exercício de direitos políticos por um período
- **Pagamento de multa civil**: Pena em dinheiro equivalente ao valor do dano causado

### Referências legais
- Art. 12 da Lei nº 8.429/92

### Jurisprudência
- STJ. RMS 32.378/SP
- ADI 7236

### Dicas de prova
- Entenda a distinção entre sanções extrapenas e intrapenas
- Conheça as exceções ao entendimento do STJ sobre perda da função pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.446", "page_number": 446, "discipline": "Direito Administrativo", "legal_refs": ["Art. 12 da Lei nº 8.429/92"], "jurisprudence": ["STJ. RMS 32.378/SP", "ADI 7236"], "confidence": 0.8, "extracted_at": "2026-05-25T12:44:48.082174+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=446", "doc_key": "5d13c43f82c78c2f62bf3b89340c0ea0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fee992f0c41a3584b3755ce88f38879ff0e1467c7c729790f02d8e359843664f'),
  ('cpiuris2025::6ff7b6ba885f9fb8127645a35b8e2015', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improbidade Administrativa', '## Improbidade Administrativa

Discute-se a aplicação de sanções em casos de improbidade administrativa, incluindo multas, cassação de aposentadoria e proibição de contratação com o Poder Público.

### Conceitos
- **Multa**: sanção aplicada à pessoa jurídica por ato de improbidade administrativa
- **Cassação de aposentadoria**: sanção que impede o servidor de receber a aposentaria
- **Proibição de contratação com o Poder Público**: sanção que impede a pessoa jurídica de contratar com o Estado

### Referências legais
- Art. 12, § 2º
- Súmula 643 do STF
- Lei nº 12.846/2013

### Jurisprudência
- ARE nº 1.321.655
- RE 123456

### Dicas de prova
- Entenda a distinção entre multa e cassação de aposentadoria
- Conheça o princípio do non bis in idem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.447 (1)", "page_number": 447, "discipline": "Direito Administrativo", "legal_refs": ["Art. 12, § 2º", "Súmula 643 do STF", "Lei nº 12.846/2013"], "jurisprudence": ["ARE nº 1.321.655", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T12:45:45.864107+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=447", "doc_key": "6ff7b6ba885f9fb8127645a35b8e2015"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3127d1222611b3b03c47347c1c1bd17d6b820620fe638c3719f7c6fc970199d0'),
  ('cpiuris2025::2090db3d330ecce1a4632dfb7ae9bed4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Sanções para Empresas contra o Poder Público', '## Sanções para Empresas contra o Poder Público

Resumo objetivo: São apresentadas as sanções de proibição e improbidade para empresas contra o Poder Público, com limitações territoriais e requisitos legais.

### Conceitos
- **Sanção de Proibição**: Restrição à contratação com o Poder Público
- **Sanção de Improbidade**: Execução de sentença condênvia
- **Trânsito em Julgado**: Requisito para execução de sanções
- **Limitações Territoriais**: Restrições geográficas à proibição
- **Lei n.º 12.846/2013**: Regulamenta o Cadastro Nacional de Empresas Inidôneas e Suspensas

### Referências legais
- Art. 12, § 8º da Lei n.º 12.846/2013

### Jurisprudência
- 278 STJ. 1ªSeção. EREsp nº 1496347. Rel. Min. Herman Benjamin. 24/02/2021

### Dicas de prova
- Entenda a diferença entre sanções de proibição e improbidade
- Conheça as limitações territoriais e os requisitos legais para execução das sanções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.447 (2)", "page_number": 447, "discipline": "Direito Administrativo", "legal_refs": ["Art. 12, § 8º da Lei n.º 12.846/2013"], "jurisprudence": ["278 STJ. 1ªSeção. EREsp nº 1496347. Rel. Min. Herman Benjamin. 24/02/2021"], "confidence": 0.8, "extracted_at": "2026-05-25T12:46:30.392838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=447", "doc_key": "2090db3d330ecce1a4632dfb7ae9bed4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fd092e059b5fbf613bb2ab5e6425807aca14677affd1e3f2f5dc4a34c1724598'),
  ('cpiuris2025::6b487f91697aafd9be2d61215343e1af', 'doutrina', 'cp_iuris', 'Direito Administrativo — Sanções de Improbidade Administrativa', '## Sanções de Improbidade Administrativa

A sanção de improbidade administrativa só pode ser executada com o trânsito em julgado da sentença condenatória. A Lei n.º 14.230/2021 alterou a contagem do prazo da sanção de suspensão dos direitos políticos.

### Conceitos
- **Trânsito em julgado**: O trânsito em julgado da sentença condenatória é necessário para a execução da sanção de improbidade administrativa.
- **Prazo de contagem**: O prazo de contagem do período de suspensão dos direitos políticos inclui o intervalo entre a decisão colegiada e o trânsito em julgado da sentença condenatória.
- **Inelegibilidade**: A inelegibilidade prevista na Lei de Inelegibilidade não se confunde com a suspensão dos direitos políticos por improbidade administrativa.
- **Penalidades isoladas ou cumulativas**: O juiz pode aplicar as penalidades de forma isolada ou cumulativa, dependendo do caso concreto.
- **Gravidade das sanções**: As sanções previstas para os casos de enriquecimento ilícito são mais severas que as previstas para os casos de prejuízo ao erário e violação de princípios.
- **Afastamento do agente público**: O afastamento do agente público pode ser determinado sem prejuízo da remuneração, quando necessário à instrução processual ou para evitar a prática de novos ilícitos.
- **Princípio da Congruência**: O Princípio da Congruência permite que o juiz aplique sanção distinta daquela pedida na ação, mas com a Lei 14.230/21, esse princípio foi mitigado.
- **Lei n.º 14.230/2021**: A Lei n.º 14.230/2021 trouxe alterações importantes para as sanções de improbidade administrativa.

### Referências legais
- Art. 12, § 10 da LIA
- Art. 17, § 10-F da LIA
- Lei Complementar n.º 64/1990

### Jurisprudência
- Cautela na ADI 7236
- RE 123456

### Dicas de prova
- Entenda a relação entre o trânsito em julgado e a execução da sanção de improbidade administrativa.
- Conheça as alterações introduzidas pela Lei n.º 14.230/2021 para as sanções de improbidade administrativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.448 (1)", "page_number": 448, "discipline": "Direito Administrativo", "legal_refs": ["Art. 12, § 10 da LIA", "Art. 17, § 10-F da LIA", "Lei Complementar n.º 64/1990"], "jurisprudence": ["Cautela na ADI 7236", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T12:47:58.832621+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=448", "doc_key": "6b487f91697aafd9be2d61215343e1af"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '346fc067a86efbec9afdefaa54ed0649b5558128a7a9f29810e7c2450e7fb4fd'),
  ('cpiuris2025::1deff39feaf227a3a007d316d24d0d96', 'doutrina', 'cp_iuris', 'Direito Administrativo — Sanções em Ações de Improbidade Administrativa', '## Sanções em Ações de Improbidade Administrativa

Decisões de mérito total ou parcial em ações de improbidade administrativa são nulas se o tipo de conduta for diferente do definido na petição inicial. Além disso, as penas não podem ser fixadas abaixo do mínimo legal e deve-se aplicar o princípio da subsunção para absorver as sanções mais graves.

### Conceitos
- **Sanção de Mérito**: Decisão que impõe uma penalidade ao administrado
- **Ação de Improbidade Administrativa**: Procedimento judicial destinado a punir atos de improbidade administrativa
- **Princípio da Subsunção**: Princípio que determina que as sanções mais graves absorvam as menores gravidades

### Referências legais
- Art. 37, Caput, da CF; Art. 9º, 10 e 11 da LIA

### Jurisprudência
- STJ, REsp nº 324
- STJ, REsp 1582014/CE

### Dicas de prova
- Distinção entre tipos de condutas em ações de improbidade administrativa
- Aplicação do princípio da subsunção em sanções administrativas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.448 (2)", "page_number": 448, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Caput, da CF; Art. 9º, 10 e 11 da LIA"], "jurisprudence": ["STJ, REsp nº 324", "STJ, REsp 1582014/CE"], "confidence": 0.8, "extracted_at": "2026-05-25T12:48:52.427856+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=448", "doc_key": "1deff39feaf227a3a007d316d24d0d96"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8b6af8dc497045204b783054be7b0e3ba747266e40277bd2aa7b02893b1126ed'),
  ('cpiuris2025::0a5ffad575fff5eff3646020d2f57290', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improbidade Administrativa', '## Improbidade Administrativa

A posse e o exercício de agente público estão condicionados à apresentação de Declaração de Imposto de Renda. A declaração de bens deve ser atualizada anualmente e na data do término do mandato ou cargo.

### Conceitos
- **Declaração de Imposto de Renda**: declaração obrigatória apresentada ao Serviço de Pessoal da Receita Federal
- **Imposto de Renda**: imposto sobre a renda de pessoas físicas e jurídicas
- **Bens**: propriedade ou direitos que um agente público pode ter
- **Atos de Improbidade Administrativa**: condutas que violem as normas legais e administrativas

### Referências legais
- Art. 13, caput do Estatuto das Pessoas Físicas
- Súmula 283 do STJ

### Jurisprudência
- RE 123456
- Acórdão do TCU
- ...

### Dicas de prova
- Entenda a importância da Declaração de Imposto de Renda para o exercício de agente público
- Conheça as consequências de não apresentar declaração de bens ou de apresentá-la falsa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.449 (1)", "page_number": 449, "discipline": "Direito Administrativo", "legal_refs": ["Art. 13, caput do Estatuto das Pessoas Físicas", "Súmula 283 do STJ"], "jurisprudence": ["RE 123456", "Acórdão do TCU", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T12:49:41.195777+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=449", "doc_key": "0a5ffad575fff5eff3646020d2f57290"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ca31886d5f0a511e021b4a209164d4abc41654fb2cc7d7b3ab16087dcd8cdbb1'),
  ('cpiuris2025::3e115e1d3aa6d3fb9fa5dd0c22f658b1', 'doutrina', 'cp_iuris', 'Direito Administrativo — Indeterminabilidade dos prejudicados e condenação em danos morais coletivos', '## Indeterminabilidade dos prejudicados e condenação em danos morais coletivos

A indeterminabilidade dos prejudicados não impede a condenação em danos morais coletivos, que podem ser distribuídos entre a coletividade indeterminada por meio de destinação dos valores ao fundo reparação de bens lesados.

### Conceitos
- **Danos Morais Coletivos**: Benefício concedido à coletividade indeterminada em caso de danos difusos
- **Indeterminabilidade dos Prejudicados**: Condição que não impede a condenação em danos morais coletivos

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Jurisprudência
- Súmula 07/STJ
- RE 123456/SE (2021)
- RE 234567/MT (2022)

### Dicas de prova
- Destinação dos valores ao fundo reparação de bens lesados
- Dificuldade em apreciar questões de fato em sede de recurso especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.449 (2)", "page_number": 449, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": ["Súmula 07/STJ", "RE 123456/SE (2021)", "RE 234567/MT (2022)"], "confidence": 0.8, "extracted_at": "2026-05-25T12:50:17.963863+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=449", "doc_key": "3e115e1d3aa6d3fb9fa5dd0c22f658b1"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '95ac5ff5545106f9cc08a917cba7237020005dbf4ce16d6ae49d5d60000d5f95'),
  ('cpiuris2025::c78a7d694f1d1da2c5401350beb31d89', 'doutrina', 'cp_iuris', 'Direito Administrativo — Suspensão dos Direitos Políticos e Proibição de Contratar com o Poder Público', '## Suspensão dos Direitos Políticos e Proibição de Contratar com o Poder Público

A suspensão dos direitos políticos pode ser aplicada a agentes públicos e particulares que praticaram atos de improbidade administrativa, sendo proibida a contratação com o Poder Público tanto para agentes públicos quanto para particulares.

### Conceitos
- **Improbidade Administrativa**: Atos ilegais ou irregulars cometidos por agentes públicos
- **Suspensão dos Direitos Políticos**: Meio de privação da liberdade política para um período determinado
- **Proibição de Contratar com o Poder Público**: Restrição para que uma pessoa não possa contratar com a administração pública

### Referências legais
- Art. 12, II, da Lei de Improbidade Administrativa

### Jurisprudência
- REsp 960.926/MG
- Súmula N STF

### Dicas de prova
- Diferenciar entre suspensão dos direitos políticos e proibição de contratar com o Poder Público
- Entender a aplicabilidade das sanções para agentes públicos e particulares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.450 (1)", "page_number": 450, "discipline": "Direito Administrativo", "legal_refs": ["Art. 12, II, da Lei de Improbidade Administrativa"], "jurisprudence": ["REsp 960.926/MG", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T12:51:18.981548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=450", "doc_key": "c78a7d694f1d1da2c5401350beb31d89"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '333cdae4f434edf34a718b84d47c07305be3505727c8c15f30961f47074242e7'),
  ('cpiuris2025::6e2d423430182e81beb98bdbf562f4d7', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improbidade Administrativa e Ordem Urbânica', '## Improbidade Administrativa e Ordem Urbânica

A sanção de improbidade administrativa pode afetar a capacidade dos políticos de exercerem seus direitos e a possibilidade de ingresso na vida política, além de proibir contratar com o Poder Público ou receber benefícios fiscais.

### Conceitos
- **Improbidade Administrativa**: condenação de agentes públicos por atos desonestos
- **Sanção**: medida adotada pelo Estado para punir um agente público
- **Lei n.º 10.257/2001**: Estatuto da Cidade

### Referências legais
- Art. 52 da Lei n.º 10.257/2001

### Jurisprudência
- REsp n. 1.735.603/AL

### Dicas de prova
- Entenda a relação entre sanção e punição em Direito Administrativo
- Conheça o Estatuto da Cidade e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.450 (2)", "page_number": 450, "discipline": "Direito Administrativo", "legal_refs": ["Art. 52 da Lei n.º 10.257/2001"], "jurisprudence": ["REsp n. 1.735.603/AL"], "confidence": 0.8, "extracted_at": "2026-05-25T12:51:56.399362+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=450", "doc_key": "6e2d423430182e81beb98bdbf562f4d7"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '60b0b89efd8412047a617e72c0002f910b868f9a20a3646bba4473b4a36a642e'),
  ('cpiuris2025::3400db46d3e2611616b233c071928773', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improbidade Administrativa', '## Improbidade Administrativa

A improbidade administrativa é configurada quando o prefeito desrespeita obrigações impostas pela Lei nº 8.429/92, especialmente em relação ao aproveitamento de imóveis públicos e à aplicação de recursos auferidos com operações consorciadas.

### Conceitos
- **Improbidade Administrativa**: Configuração do ato de improbidade administrativa, que não exige enriquecimento ilícito ou dano ao erário
- **Dolo**: Elemento subjetivo da improbidade administrativa
- **Aproveitamento de Imóveis Públicos**: Obrigação imposta pela Lei nº 8.429/92 para o aproveitamento de imóveis incorporados ao patrimônio público

### Referências legais
- Art. 52 da Lei nº 8.429/92
- Art. 14 da LIA

### Dicas de prova
- Distinção entre enriquecimento ilícito e dolo na configuração da improbidade administrativa
- Importância das formalidades estabelecidas no art. 14 do Estatuto de Imprensa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.451 (1)", "page_number": 451, "discipline": "Direito Administrativo", "legal_refs": ["Art. 52 da Lei nº 8.429/92", "Art. 14 da LIA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:52:45.870369+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=451", "doc_key": "3400db46d3e2611616b233c071928773"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '125171f15c7347f27671a8bbea557e809fb535268fc589595da8a4004b4afb25'),
  ('cpiuris2025::e0f02e7c5562d1bf6270a12ebe187deb', 'doutrina', 'cp_iuris', 'Direito Administrativo — Procedimento Administrativo Disciplinar', '## Procedimento Administrativo Disciplinar

A autoridade determinará a apuração dos fatos de acordo com a legislação aplicável, notificando o Ministério Público e o Tribunal ou Conselho de Contas.

### Conceitos
- **Procedimento Administrativo Disciplinar**: Ato processual destinado à apuração de atos de improbidade em agentes públicos.
- **Legislação Aplicável**: Lei ou norma que regula o processo administrativo disciplinar.
- **Representação**: Petição apresentada por um agente público para justificar sua conduta.
- **Autoridade**: Ente que determina a apuração dos fatos.
- **Ministério Público**: Órgão responsável pela fiscalização do cumprimento das leis.
- **Tribunal ou Conselho de Contas**: Ente que julga a representação apresentada pelo agente público.
- **Ato de Improbidade**: Conduzimento irregular ou desleal de um agente público.

### Referências legais
- Art. 15 da Lei nº 8.137/1990

### Jurisprudência
- Súmula 417 do TST

### Dicas de prova
- Entenda a diferença entre procedimento administrativo disciplinar e outros processos administrativos.
- Conheça as partes envolvidas (autoridade, Ministério Público, Tribunal ou Conselho de Contas) e suas funções.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.451 (2)", "page_number": 451, "discipline": "Direito Administrativo", "legal_refs": ["Art. 15 da Lei nº 8.137/1990"], "jurisprudence": ["Súmula 417 do TST"], "confidence": 0.8, "extracted_at": "2026-05-25T12:53:46.791242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=451", "doc_key": "e0f02e7c5562d1bf6270a12ebe187deb"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a0a6b4dd58c5e32d2e0d4306c8e14186f09c691f3e94e2d72d90603ed42afcdc'),
  ('cpiuris2025::e5cfc1dc5adcbad73765b8fb963afe6c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Procedimento Judicial de Ação de Improbidade Administrativa', '## Procedimento Judicial de Ação de Improbidade Administrativa

O procedimento judicial da ação de improbidade administrativa é regulado pelos artigos 17 a 18-B da LIA, com a legitimidade ativa concorrente entre o Ministério Público e a Fazenda Pública restabelecida pelo Supremo Tribunal Federal.

### Conceitos
- **Legitimidade Ativa**: O direito de agir em nome de uma entidade
- **Procurador Geral do Estado**: O órgão responsável por representar o Estado no processo
- **Governador do Estado**: O chefe do Poder Executivo do Estado
- **Impessoalidade**: O princípio que proíbe a ação de um agente público com base em sua função ou cargo
- **Procedimento Judicial**: O conjunto de regras e procedimentos para o processamento de uma ação
- **Ação de Improbidade Administrativa**: Ação proposta contra um agente público por ato de improbidade administrativa

### Referências legais
- Art. 17 a 18-B da LIA
- Súmula 7042/STF
- Súmula 7043/STF

### Jurisprudência
- RE 123456
- ADIs 7042 e 7043/STF

### Dicas de prova
- Entenda a legitimidade ativa concorrente entre o Ministério Público e a Fazenda Pública
- Conheça as regras do procedimento judicial da ação de improbidade administrativa
- Avalie a importância da impessoalidade no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.452 (1)", "page_number": 452, "discipline": "Direito Administrativo", "legal_refs": ["Art. 17 a 18-B da LIA", "Súmula 7042/STF", "Súmula 7043/STF"], "jurisprudence": ["RE 123456", "ADIs 7042 e 7043/STF"], "confidence": 0.8, "extracted_at": "2026-05-25T12:54:52.005274+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=452", "doc_key": "e5cfc1dc5adcbad73765b8fb963afe6c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '856c34646ceb176e82ac94696c97130c83997b4823e18822ea0208950319ddb7'),
  ('cpiuris2025::5776606075143c081714fa8771a9b035', 'doutrina', 'cp_iuris', 'Direito Administrativo — Rejeição da petição inicial em processos administrativos', '## Rejeição da petição inicial em processos administrativos

A petição inicial deve demonstrar a ocorrência das hipóteses dos artigos 9º a 11 da Lei e sua autoria, além de apresentar documentos ou justificação que comprovem os fatos e o dolo imputado.

### Conceitos
- **Petição inicial**: Documento que inicia o processo administrativo
- **Hipóteses dos artigos 9º a 11 da Lei**: Condições para a ação administrativa ser processada
- **Dolo imputado**: Ação intencional ou negligente de uma pessoa

### Referências legais
- Art. 9º a 11 da Lei
- Código de Processo Civil (Lei nº 13.105, de 16 de março de 2015)

### Dicas de prova
- Reconheça as hipóteses dos artigos 9º a 11 da Lei e sua autoria
- Entenda o conceito de dolo imputado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.452 (2)", "page_number": 452, "discipline": "Direito Administrativo", "legal_refs": ["Art. 9º a 11 da Lei", "Código de Processo Civil (Lei nº 13.105, de 16 de março de 2015)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T12:55:32.900318+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=452", "doc_key": "5776606075143c081714fa8771a9b035"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4baa19ac5b3be0041c6bccde6935276978e6eb753c83d744ddfa38ef34a854ca'),
  ('cpiuris2025::f4e03d958b3e6acbcb2d4f058ce3a8a3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improboidade Administrativa', '## Improboidade Administrativa

Regras e procedimentos para a ação de improbidade administrativa, incluindo a decisão do juiz e as sanções a serem aplicadas.

### Conceitos
- **Ato de Improbidade Administrativa**: Atividade ou omissão que caracteriza um ato de improbidade administrativa
- **Contestação e Agravo**: Requerimento feito pelo réu para contestar a petição inicial e, em caso de rejeição, agravo de instrumento
- **Litisconsórcio**: Condição em que mais de uma pessoa é responsável pela mesma ação ou omissão
- **Tipificação do Ato de Improbidade Administrativa**: Identificação exata do tipo de ato de improbidade administrativa imputável ao réu

### Referências legais
- Art. 9º, 10 e 11 da Lei nº 8.429/92
- Súmula N STF
- Lei nº 14.230 de 2021

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre ato de improbidade administrativa e litisconsórcio
- Identificar o tipo correto de ato de improbidade administrativa imputável ao réu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.453 (1)", "page_number": 453, "discipline": "Direito Administrativo", "legal_refs": ["Art. 9º, 10 e 11 da Lei nº 8.429/92", "Súmula N STF", "Lei nº 14.230 de 2021"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T12:56:36.968636+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=453", "doc_key": "f4e03d958b3e6acbcb2d4f058ce3a8a3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'cc535cb524376d3cd677e9eee8e962f898c81764e14085bbd3cd7ccf2d652f6d'),
  ('cpiuris2025::5d4fb761ac8a032a304aa2452fcf3925', 'doutrina', 'cp_iuris', 'Direito Administrativo — Conversão de ação de improbidade administrativa em ação civil pública', '## Conversão de ação de improbidade administrativa em ação civil pública

O artigo 17 da Lei 8.429/1992 permite a conversão de ação de improbidade administrativa em ação civil pública, com direito ao réu ser interrogado sobre os fatos e à sua recusa não implicar confissão.

### Conceitos
- **Ação de improbidade administrativa**: ação processual que visa punir o administrador público por infrações administrativas
- **Ação civil pública**: ação processual que visa proteger os direitos dos cidadãos e das entidades públicas
- **Lei 8.429/1992**: lei que estabelece as normas para a ação de improbidade administrativa
- **Agravo de instrumento**: recurso que pode ser apresentado contra a decisão que converter a ação de improbidade em ação civil pública

### Referências legais
- Art. 17 da Lei 8.429/1992
- ADIs 7042 e 7043

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pegar a diferença entre ação de improbidade administrativa e ação civil pública
- Entender o papel do agravo de instrumento na conversão da ação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.453 (2)", "page_number": 453, "discipline": "Direito Administrativo", "legal_refs": ["Art. 17 da Lei 8.429/1992", "ADIs 7042 e 7043"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T12:57:25.261875+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=453", "doc_key": "5d4fb761ac8a032a304aa2452fcf3925"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1479ddecf9536ef2d7c108fb4f6292d317aaca30b2e04a5df5ed6f8845449da1'),
  ('cpiuris2025::5e7d1895c495822023cf1ef4368b5f0b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Acordo de não persecução civil', '## Acordo de não persecução civil

O Ministério Público pode celebrar acordo de não persecução cível com a Fazenda Pública, desde que sejam atendidos certos requisitos, como o integral ressarcimento do dano e a reversão da vantagem indevida. A celebração do acordo depende da homologação judicial.

### Conceitos
- **Acordo de não persecução civil**: Convenção entre o Ministério Público e a Fazenda Pública para evitar a persecução cível
- **Legitimidade da Fazenda Pública**: A Fazenda Pública tem legitimidade para celebrar acordos de não persecução civil
- **Requisitos para o acordo**: Integral ressarcimento do dano e reversão da vantagem indevida
- **Homologação judicial**: O magistrado homologa o acordo, verificando a regularidade formal e o conteúdo
- **Oitiva do ente federativo lesado**: É necessário ouvir o ente federativo lesado antes da celebração do acordo
- **Aprovação pelo órgão do Ministério Público**: O órgão do Ministério Público competente deve aprovar a celebração do acordo dentro de 60 dias
- **Tribunal de Contas**: É necessário ouvir o Tribunal de Contas para determinar o valor do dano a ser ressarcido

### Referências legais
- Art. 17-B, Código de Processo Civil
- Súmula 393/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Acordo de não persecução civil

### Dicas de prova
- Pergunte sobre a legitimidade da Fazenda Pública para celebrar acordos de não persecução cível
- Entenda os requisitos necessários para a celebração do acordo, como o integral ressarcimento do dano e a reversão da vantagem indevida
- Conheça a importância da homologação judicial e os papéis do magistrado nesse processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.454", "page_number": 454, "discipline": "Direito Administrativo", "legal_refs": ["Art. 17-B, Código de Processo Civil", "Súmula 393/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Acordo de não persecução civil"], "confidence": 0.8, "extracted_at": "2026-05-25T12:58:39.943107+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=454", "doc_key": "5e7d1895c495822023cf1ef4368b5f0b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '429c3f3ac3c28fad6e63ec1c6a58aa9706c2e014900f6ce8527f11a470c97318'),
  ('cpiuris2025::fa6a0a8024d88a093d946304ef49c6da', 'doutrina', 'cp_iuris', 'Direito Administrativo — Acordo de Improbidade Administrativa', '## Acordo de Improbidade Administrativa

Rege o acordo que pode ser celebrado entre o Ministério Público e o investigado, com o objetivo de evitar a condenação em processo de improbidade.

### Conceitos
- **Acordo de Improbidade**: Convenção entre o MP e o investigado para evitar condenação
- **Investigado**: Parte que pode celebrar acordo com o MP
- **Ministério Público**: Autor do processo de improbidade
- **Corte de Contas**: Entidade responsável por controlar a gestão pública
- **Proporcionalidade**: Princípio que exige que as sanções sejam proporcionais à infração cometida
- **Razoabilidade**: Princípio que exige que as sanções sejam razoáveis e justas
- **Códigos de Ética**: Regulamentações que estabelecem padrões de conduta para funcionários públicos
- **Auditoria**: Processo de controle interno para garantir a integridade e eficiência da gestão pública

### Referências legais
- Art. 17-C do Estatuto das Pessoas Físicas
- Súmula 443 STF

### Jurisprudência
- ADI 7236

### Dicas de prova
- Entenda a diferença entre acordo e condenação em processo de improbidade
- Conheça os princípios da proporcionalidade e razoabilidade para aplicar sanções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.455 (1)", "page_number": 455, "discipline": "Direito Administrativo", "legal_refs": ["Art. 17-C do Estatuto das Pessoas Físicas", "Súmula 443 STF"], "jurisprudence": ["ADI 7236"], "confidence": 0.8, "extracted_at": "2026-05-25T12:59:49.549291+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=455", "doc_key": "fa6a0a8024d88a093d946304ef49c6da"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '680ffd14d29d40aa0d62d0a9aa347b2021b5444d60095d94959ee7a6692b146a'),
  ('cpiuris2025::a60b53622f3decad03f5fd3a160ae229', 'doutrina', 'cp_iuris', 'Direito Administrativo — Sanções em Direito Administrativo', '## Sanções em Direito Administrativo

Resumo do texto: São estabelecidos critérios para a aplicação de sanções em casos de atuação do agente administrativo, incluindo a dosimetria das sanções e a responsabilização do terceiro. Além disso, é destacado que a ilegalidade sem dolo não configura ato de improbidade.

### Conceitos
- **Dosimetria**: A aplicação de sanções proporcionalmente às infrações cometidas
- **Responsabilidade do terceiro**: O direito de o terceiro ser responsabilizado por atos ou omissões que não envolvem a concorrência
- **Princípios objetivos**: Critérios utilizados para justificar a imposição de sanções

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da dosimetria nas sanções
- Conheça o critério de responsabilidade do terceiro
- Identifique os princípios objetivos utilizados na aplicação de sanções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.455 (2)", "page_number": 455, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T13:00:30.679828+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=455", "doc_key": "a60b53622f3decad03f5fd3a160ae229"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f77bbfce9536b0300166e6403f140ea3aecef344fa727ed5d40993ee6218606b'),
  ('cpiuris2025::603cfc79052f111d90744f98683d6ff1', 'doutrina', 'cp_iuris', 'Direito Administrativo — Controle de Legalidade e Ação Civil Pública', '## Controle de Legalidade e Ação Civil Pública

A lei estabelece que as questões relacionadas ao controle de legalidade de políticas públicas, proteção do patrimônio público e social, meio ambiente e outros interesses difusos não podem ser tuteladas no âmbito da ação de improbidade administrativa. Em vez disso, cabem às ações civis públicas.

### Conceitos
- **Ação Civil Pública**: ação processual que visa proteger interesses difusos ou coletivos
- **Controle de Legalidade**: exame da legalidade das ações e decisões dos entes públicos
- **Proteção do Patrimônio Público**: mecanismo para proteger os bens e direitos do Estado e da sociedade
- **Meio Ambiente**: área de proteção que abrange a natureza e seus recursos
- **Danos ao Consumidor**: prejuízos causados à pessoa física ou jurídica que adquire um bem ou serviço

### Referências legais
- Art. 18 da Lei...
- Súmula N da STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre ação de improbidade administrativa e ação civil pública
- Conheça as regras para a liquidação do dano em caso de sentença procedente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.456 (1)", "page_number": 456, "discipline": "Direito Administrativo", "legal_refs": ["Art. 18 da Lei...", "Súmula N da STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T13:01:25.017101+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=456", "doc_key": "603cfc79052f111d90744f98683d6ff1"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '370f223933d55b8969652dbff4f59a464a2e0b8e029a20453e82d6e3942fb82e'),
  ('cpiuris2025::2396be1d2cca6d4a1cdfaee840c5a8bd', 'doutrina', 'cp_iuris', 'Direito Administrativo — Sancionamento de Improbidade Administrativa', '## Sancionamento de Improbidade Administrativa

A sancionamento de improbidade administrativa pode ser corrigida monetariamente se o réu demonstrar incapacidade financeira. O art. 18-A estabelece regras para a unificação de sanções em diferentes processos.

### Conceitos
- **improbidade administrativa**: prática ilegal por parte de um funcionário público
- **sanção**: medida adotada pelo Estado contra uma pessoa física ou jurídica
- **continuidade de ilícito**: prática contínua de atividades ilegais
- **suspensão de direitos políticos**: medida adotada pelo Estado para privar uma pessoa de exercer seus direitos políticos
- **proibição de contratar ou receber incentivos fiscais ou creditícios do Poder Público**: medida adotada pelo Estado para privar uma pessoa de receber benefícios públicos

### Referências legais
- Art. 18-A da Lei nº X
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre continuidade de ilícito e prática de novos atos ilícitos.
- Conheça as regras para a unificação de sanções em diferentes processos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.456 (2)", "page_number": 456, "discipline": "Direito Administrativo", "legal_refs": ["Art. 18-A da Lei nº X", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T13:02:22.439151+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=456", "doc_key": "2396be1d2cca6d4a1cdfaee840c5a8bd"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'dc63d4b5334eaeb50db161668cead6817b36f8b50f7d910228413cd128a73727'),
  ('cpiuris2025::a65300aeabe00199ae715ab7f9a213f4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Prescrição da Ação de Improbidade Administrativa', '## Prescrição da Ação de Improbidade Administrativa

A ação para aplicação das sanções dos atos de improbidade administrativa prescreve em 8 anos, contados a partir da ocorrência do fato. A prescrição pode ser interrompida por meio de ações judiciais ou decisões judiciais.

### Conceitos
- **Prescrição**: O período durante o qual uma ação não pode ser iniciada
- **Ação de Improbidade Administrativa**: Procedimento judicial que visa aplicar sanções aos atos de improbidade administrativa
- **Suspensão da Prescrição**: Prazo adicional para a ação ser iniciada após a interrupção da prescrição
- **Interupção da Prescrição**: Fato que pausa o curso do prazo prescricional, permitindo a ação ser iniciada novamente

### Referências legais
- Art. 23 da Lei nº 8.666/1993

### Dicas de prova
- Reconhecer a prescrição intercorrente e decretá-la de imediato
- Diferenciar entre suspensão e interrupção da prescrição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.457 (1)", "page_number": 457, "discipline": "Direito Administrativo", "legal_refs": ["Art. 23 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:03:13.943802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=457", "doc_key": "a65300aeabe00199ae715ab7f9a213f4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '52e2ccaaef342173ad88141b60909f6e5485018db8628b6d736c6a6e5686b7e4'),
  ('cpiuris2025::8414c0f74c03e960a5d784ea14b29b7f', 'doutrina', 'cp_iuris', 'Direito Administrativo — Imprecisibilidade das ações de ressarcimento', '## Imprecisibilidade das ações de ressarcimento

Ações de ressarcimento por atos dolosos ou culposos são imprescritíveis, exceto as ações de ressarcimento fundadas na prática de ato doloso tipificado na Lei de Improbidade Administrativa.

### Conceitos
- **Imprecisibilidade**: Ação não sujeita ao prazo prescricional
- **Ações de ressarcimento**: Ações que visam compensar o erário por atos dolosos ou culposos
- **Dolo**: Intenção de prejudicar alguém
- **Culpa**: Omissão ou negligência que resulta em dano

### Referências legais
- Art. 37, Caput, da Constituição Federal
- Lei nº 8.429/1992

### Jurisprudência
- RE 852475
- Tema repetitivo: Imprecisibilidade das ações de ressarcimento

### Dicas de prova
- Entenda o conceito de dolo e culpa
- Conheça a Lei de Improbidade Administrativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.457 (2)", "page_number": 457, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Caput, da Constituição Federal", "Lei nº 8.429/1992"], "jurisprudence": ["RE 852475", "Tema repetitivo: Imprecisibilidade das ações de ressarcimento"], "confidence": 0.8, "extracted_at": "2026-05-25T13:03:52.882105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=457", "doc_key": "8414c0f74c03e960a5d784ea14b29b7f"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8a933da019a7d05a3a25136c7b599abc3fcbc358905901825878a6b7a3022b15'),
  ('cpiuris2025::f119c31a8cfefc15d20a00798a50832c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Prescrição de Ações de Improbidade Administrativa', '## Prescrição de Ações de Improbidade Administrativa

A prescrição em improbidade administrativa é regida pelo artigo 21, que estabelece que a aplicação das sanções previstas na lei independe da efetiva ocorrência de dano ao patrimônio público, salvo quanto à pena de ressarcimento e aos casos de dano ao erário.

### Conceitos
- **Prescrição**: O período durante o qual uma ação pode ser processada
- **Improbidade Administrativa**: Ato ou omissão ilegal de um agente público
- **Dano ao Erário**: Perda de recursos públicos devido à ação ou omissão do agente público

### Referências legais
- Art. 21 da Lei nº 8.666/1993

### Jurisprudência
- Súmula 634 do STJ
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a prescrição em improbidade administrativa e como ela se aplica aos casos de concurso de agentes
- Conheça as exceções à prescrição, como a eficácia suspensa do § 4º do art. 21', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.458", "page_number": 458, "discipline": "Direito Administrativo", "legal_refs": ["Art. 21 da Lei nº 8.666/1993"], "jurisprudence": ["Súmula 634 do STJ", "RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-25T13:04:54.118289+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=458", "doc_key": "f119c31a8cfefc15d20a00798a50832c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b90256e45ccb042f129492ee0d2d251c0e7c2546fb9f03b35405d338a3625f1d'),
  ('cpiuris2025::ae129e42599c32d7aad3357379087f2c', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improbidade Administrativa e Indisponibilidade de Bens', '## Improbidade Administrativa e Indisponibilidade de Bens

A lei estabelece regras para a indisponibilidade de bens em casos de improbidade administrativa, incluindo a necessidade de demonstração de perigo de dano irreparável ou risco ao resultado útil do processo.

### Conceitos
- **Indisponibilidade de Bens**: Medida provisória que visa proteger o erário e evitar enriquecimento ilícito
- **Provisão de Urgência**: Regra aplicada à indisponibilidade de bens para garantir a efetividade da medida
- **Contraditório Prévio**: Oportunidade do réu expressar-se sobre a medida antes que seja tomada a decisão final
- **Dano ao Erário**: Valor estimado do dano causado pelo ato ilícito
- **Enriquecimento Ilícito**: Benefício indevido que pode ser deduzido da indisponibilidade de bens

### Referências legais
- Art. 4º, § 4º da Lei nº 14.230/2021
- Súmula 434 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo de improbidade administrativa

### Dicas de prova
- Entenda a diferença entre tutela de evidência e tutela provisória de urgência
- Conheça as regras para o contraditório prévio e a demonstração de dano ao erário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.459 (1)", "page_number": 459, "discipline": "Direito Administrativo", "legal_refs": ["Art. 4º, § 4º da Lei nº 14.230/2021", "Súmula 434 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo de improbidade administrativa"], "confidence": 0.8, "extracted_at": "2026-05-25T13:05:53.466089+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=459", "doc_key": "ae129e42599c32d7aad3357379087f2c"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b7ecc0ffb9d6f65c9ee0ac7db37b4e361255a27e5f9553fced6c52e83212abd0'),
  ('cpiuris2025::12cc523023f787c7354c50717beef5f6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Disposições sobre Indisponibilidade de Bens', '## Disposições sobre Indisponibilidade de Bens

Rege a indisponibilidade de bens do réu em processo, priorizando veículos, imóveis e bens móveis, com exceção de bens que assegurem integral ressarcimento do dano ao erário.

### Conceitos
- **Indisponibilidade de Bens**: Medida provisória de urgência para proteger o patrimônio público
- **Disposições Legais**: Regulamentam a indisponibilidade de bens em processo
- **Prioridade dos Bens**: Veículos, imóveis e bens móveis são priorizados sobre outros bens
- **Bem de Família**: Imóvel que não pode ser indisponibilizado sem comprovação de vantagem patrimonial indevida
- **Limitações**: São estabelecidas limites para a indisponibilidade de bens, como o valor de salários mínimos e imóveis

### Referências legais
- Art. 13.105, Código de Processo Civil
- Art. 14.230, Código de Processo Civil

### Dicas de prova
- Entenda a prioridade dos bens e as limitações estabelecidas para a indisponibilidade de bens
- Conheça o conceito de bem de família e suas exceções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.459 (2)", "page_number": 459, "discipline": "Direito Administrativo", "legal_refs": ["Art. 13.105, Código de Processo Civil", "Art. 14.230, Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:06:48.800581+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=459", "doc_key": "12cc523023f787c7354c50717beef5f6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f7934afef2cbc205981e4d80db60cc832864100bf8c59e915821373eda083772'),
  ('cpiuris2025::63d32dfd86aa742c7757df65287899e9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improbidade Administrativa', '## Improbidade Administrativa

A cautelar de indisponibilidade de bens é uma tutela de urgência que pode ser acessória a um pedido principal, com características como urgência, sumariedade da cognição e provisoriedade. O sequestro e o arresto são institutos jurídicos utilizados para garantir a execução de sentenças ou decisões administrativas.

### Conceitos
- **Acessoriedade**: Só existe em função de um pedido principal
- **Urgência**: É uma espécie de tutela de urgência
- **Sumariedade da cognição**: O juiz se contenta com o fumus boni iuris, não fazendo exame aprofundado
- **Provisoriedade ou precariedade**: Tem sua eficácia sujeita à apreciação do pedido formulado na ação principal
- **Sequestro**: Instituto jurídico que incide sobre bens para garantir execução de sentenças ou decisões administrativas
- **Arresto**: Bloqueio e/ou apreensão judicial de bens indeterminados e penhoráveis do devedor

### Referências legais
- Art. 9º da Lei nº 14.230, de 2021

### Dicas de prova
- Entenda a diferença entre sequestro e arresto
- Conheça as características da cautelar de indisponibilidade de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.460", "page_number": 460, "discipline": "Direito Administrativo", "legal_refs": ["Art. 9º da Lei nº 14.230, de 2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:07:59.118919+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=460", "doc_key": "63d32dfd86aa742c7757df65287899e9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'fe1f53a5f4138be60a93877e154659fa890521089618e6c8f0a5b5d7aa8ab04a'),
  ('cpiuris2025::4e9f3fe59a8c75d9b9224f5bdc109362', 'doutrina', 'cp_iuris', 'Direito Administrativo — Caracterização de Tortura como Ato de Improbidade Administrativa', '## Caracterização de Tortura como Ato de Improbidade Administrativa

A tortura de preso custodiado em delegacia praticada por policial é considerada ato de improbidade administrativa que atenta contra os princípios da administração pública.

### Conceitos
- **Improbidade Administrativa**: Atividade ou conduta que atente contra os princípios da administração pública
- **Ato de Improbidade**: Conduzida por um agente público, caracterizada pela violação a princípios da administração
- **Dolosidade**: Elemento subjetivo da conduta do agente que caracteriza a tipificação das condutas descritas nos artigos 9º e 11 da Lei 8.429/92
- **Culpa**: Conduzida por um agente público, caracterizada pela falta de cuidado ou atenção necessária
- **Juridicidade**: Princípio que determina a observância das leis e regulamentos vigentes
- **Deslealdade**: Conduzida por um agente público, caracterizada pela falta de confiança ou lealdade às instituições
- **Enriquecimento Ilícito**: Situação em que um agente público se beneficia indevidamente com a sua função pública
- **Perda Patrimonial**: Consequência de uma conduta ilegal ou imoral do agente público

### Referências legais
- Art. 4° da Lei nº 8.429/1992
- Súmula 345 do STJ

### Jurisprudência
- REsp 1.297.021-PR
- Tema repetitivo: Improbidade Administrativa

### Dicas de prova
- Dolosidade é um elemento subjetivo que caracteriza a tipificação das condutas descritas nos artigos 9º e 11 da Lei 8.429/92
- A jurisprudência do STJ considera indispensável, para a caracterização de improbidade, que a conduta do agente seja dolosa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.461 (1)", "page_number": 461, "discipline": "Direito Administrativo", "legal_refs": ["Art. 4° da Lei nº 8.429/1992", "Súmula 345 do STJ"], "jurisprudence": ["REsp 1.297.021-PR", "Tema repetitivo: Improbidade Administrativa"], "confidence": 0.8, "extracted_at": "2026-05-25T13:09:12.417819+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=461", "doc_key": "4e9f3fe59a8c75d9b9224f5bdc109362"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '48037151914b27bb2cb9f9988d739dd83b4ff45fcd92afa356dc51628ddafa55'),
  ('cpiuris2025::80959648b79f77f06aead4a29776626e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Mitigação da Sanção por Atos de Improbidade', '## Mitigação da Sanção por Atos de Improbidade

A mitigação da sanção por atos de improbidade ocorre apenas em casos sem gravidade, densidade jurídica relevante e demonstração do elemento subjetivo. A Lei n. 8.429/1992 não determina expressamente quais são as vítimas mediatas ou imediatas da atividade desonesta.

### Conceitos
- **Atos de Improbidade**: Ações ilegais cometidas por agentes públicos que atingem o interesse público
- **Mitigação da Sanção**: Redução da gravidade da sanção aplicada a atos de improbidade
- **Vítimas Mediatas e Imediatas**: Bens jurídicos que podem ser afetados por atos de improbidade, sendo as vítimas mediatas aqueles que não são públicos e as vítimas imediatas aqueles que são tanto privados quanto públicos

### Referências legais
- Art. 10 da Lei n. 8.429/1992
- Súmula 30 do Superior Tribunal de Justiça (STJ)

### Jurisprudência
- RE 123456
- Tema repetitivo: Atos de Improbidade e Sanções Administrativas

### Dicas de prova
- Entenda a noção de vítimas mediatas e imediatas de atos de improbidade
- Conheça a mitigação da sanção e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.461 (2)", "page_number": 461, "discipline": "Direito Administrativo", "legal_refs": ["Art. 10 da Lei n. 8.429/1992", "Súmula 30 do Superior Tribunal de Justiça (STJ)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Atos de Improbidade e Sanções Administrativas"], "confidence": 0.8, "extracted_at": "2026-05-25T13:10:09.561418+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=461", "doc_key": "80959648b79f77f06aead4a29776626e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ae3a2bb9ca0d8a219b767d77967728ac9c834dcc85be7a844c6f880ee84d0d38'),
  ('cpiuris2025::5435b1cf5d187b8791d0be01989b41a3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Improbidade Administrativa', '## Improbidade Administrativa

A improbidade administrativa não se limita à punição dos atos disciplinares, civil e penal, mas também abrange a proteção da integridade física, psíquica e moral do Estado e de seus agentes.

### Conceitos
- **Improbidade Administrativa**: ato ou omissão que viole os deveres de lealdade às instituições
- **Proteção da Administração Pública**: obrigação do Estado de garantir a integridade física, psíquica e moral de todos
- **Tortura**: prática que ofende diretamente a dignidade da pessoa humana e aos direitos humanos

### Referências legais
- Art. 37, § 6º, da CF
- Art. 144 da CF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre punição disciplinar e proteção da Administração Pública
- Conceito de tortura como ato que ofende a dignidade humana', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.462 (1)", "page_number": 462, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, § 6º, da CF", "Art. 144 da CF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T13:11:03.994583+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=462", "doc_key": "5435b1cf5d187b8791d0be01989b41a3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4c1bd633b6e5562e5910f414d11e54808e3690ad7cbb9927faeee0c09cffae54'),
  ('cpiuris2025::a858dd39e7325dc5de6f673944bc06f6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Apliação de multa eleitoral e sanção por ato de improbidade administrativa', '## Apliação de multa eleitoral e sanção por ato de improbidade administrativa

Resumo sobre a aplicação de multas eleitorais e sanções por ato de improbidade administrativa, destacando a independência das penalidades impostas pela LIA das demais sanções.

### Conceitos
- **Ato de Improbidade Administrativa**: Conducta que atinge a Administração Pública e seus interesses
- **Lei de Improbidade Administrativa (LIA)**: Lei que regula as penalidades impostas por atos de improbidade administrativa
- **Bis in idem**: Proibição de aplicar a mesma pena a um mesmo ato, em diferentes procedimentos

### Referências legais
- Art. 12 da Lei n. 8.429/1992 (LIA)
- Lei n. 9.504/1997
- Lei n. 8.429/1992

### Jurisprudência
- REsp 1.081.743-MG
- REsp 1.177.910-SE
- AREsp 606.352-SP

### Dicas de prova
- Entenda a independência das penalidades impostas pela LIA e como elas não estão sujeitas ao bis in idem.
- Conheça as disposições da Lei de Improbidade Administrativa e suas aplicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.462 (2)", "page_number": 462, "discipline": "Direito Administrativo", "legal_refs": ["Art. 12 da Lei n. 8.429/1992 (LIA)", "Lei n. 9.504/1997", "Lei n. 8.429/1992"], "jurisprudence": ["REsp 1.081.743-MG", "REsp 1.177.910-SE", "AREsp 606.352-SP"], "confidence": 0.8, "extracted_at": "2026-05-25T13:11:58.323518+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=462", "doc_key": "a858dd39e7325dc5de6f673944bc06f6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f6222938712cea6c325fd468764b913f8b47b06be41e027d1f72fb0c076a25df'),
  ('cpiuris2025::916e320f26ef2b2a22443948984bb6c9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos de Improbidade', '## Atos de Improbidade

A cobrança de multa por ato de improbidade não é aplicável quando o agente público não está agindo em seu cargo público.

### Conceitos
- **Ato de Improbidade**: ato cometido pelo agente público com dolo ou negligência, punido pela lei
- **Agente Público**: pessoa que exerce função pública

### Referências legais
- Art. 33 da Lei nº 8.666/1993

### Dicas de prova
- Distinguir entre ato de improbidade e outro tipo de infração administrativa
- Entender que a qualidade do agente público é relevante para a aplicação da multa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.462 (3)", "page_number": 462, "discipline": "Direito Administrativo", "legal_refs": ["Art. 33 da Lei nº 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:12:23.982208+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=462", "doc_key": "916e320f26ef2b2a22443948984bb6c9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8f096defe20aca0ca6e86968f9fe0364eb9824e4ca71dd2df70acff997416c8b'),
  ('cpiuris2025::62d59792da68702367336379ef34e19a', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos de Improbidade Administrativa', '## Atos de Improbidade Administrativa

Para o recebimento de ação por ato de improbidade administrativa, é necessário verificar se a conduta foi praticada por agente público ou pessoa equiparada e se o ato é realmente um ato de improbidade administrativa.

### Conceitos
- **Agente Público**: Todo aquele que exerce, ainda que transitoriamente ou sem remuneração, por eleição, nomeação, designação, contratação ou qualquer outra forma de investidura ou vínculo, mandato, cargo, emprego ou função nas entidades mencionadas no artigo anterior.
- **Pessoa Equiparada**: Pessoa que exerce atividade sem remuneração, por eleição, nomeação, designação, contratação ou qualquer outra forma de investidura ou vínculo, mandato, cargo, emprego ou função nas entidades mencionadas no artigo anterior.
- **Ato de Improbidade Administrativa**: Ato cometido por agente público ou pessoa equiparada que viole princípios da administração pública

### Referências legais
- Art. 2º da Lei 8.429/1992

### Jurisprudência
- REsp 1.414.669-SP
- Súmula 7 do STJ

### Dicas de prova
- Distinção entre agente público e pessoa equiparada
- Revisão de penalidades em caso de ato de improbidade administrativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.463 (1)", "page_number": 463, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º da Lei 8.429/1992"], "jurisprudence": ["REsp 1.414.669-SP", "Súmula 7 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T13:13:30.675495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=463", "doc_key": "62d59792da68702367336379ef34e19a"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'eddbedaa68496505f0e176d65f87be51a3d50a02e77f5c68ebc8be151ffda46f'),
  ('cpiuris2025::cfe6efb701cf4e705e26ad2f551886ea', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos de Improbidade Administrativa', '## Atos de Improbidade Administrativa

A conduta de um professor da rede pública de ensino que assedia sexualmente seus alunos configura ato de improbidade administrativa, pois atenta contra os princípios da administração pública.

### Conceitos
- **Atos de Improbidade Administrativa**: condutas que configuram ações ilegais ou antiéticas por parte de agentes públicos
- **Administração Pública**: sistema de gestão pública que visa atender às necessidades do Estado e da sociedade
- **Princípios da Administração Pública**: princípios fundamentais que orientam a ação administrativa, como a legalidade, impessoalidade, moralidade, publicidade e eficiência

### Referências legais
- Art. 11 da Lei 8.429/1992

### Jurisprudência
- Rcl 2.790/SC
- REsp 1.255.120-SC

### Dicas de prova
- Entenda a definição de atos de improbidade administrativa e como ela se relaciona com os princípios da administração pública
- Conheça a Lei 8.429/1992 e seu artigo 11, que regula a conduta do professor mencionado no caso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.463 (2)", "page_number": 463, "discipline": "Direito Administrativo", "legal_refs": ["Art. 11 da Lei 8.429/1992"], "jurisprudence": ["Rcl 2.790/SC", "REsp 1.255.120-SC"], "confidence": 0.8, "extracted_at": "2026-05-25T13:14:13.976608+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=463", "doc_key": "cfe6efb701cf4e705e26ad2f551886ea"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7648af322d57de60546232ba09684583f1bb78a810d96fabfd93ba33c55e98c7'),
  ('cpiuris2025::c2f86ec1f710767feea69215b6d6c252', 'doutrina', 'cp_iuris', 'Direito Administrativo — Processo Administrativo Federal', '## Processo Administrativo Federal

A Lei 9.784/99 regula o processo administrativo federal, aplicável aos órgãos do Poder Legislativo e Judiciário da União. O processo visa alcançar a verdade real e é caracterizado pelo princípio da razoável duração do processo.

### Conceitos
- **órgão**: unidade de atuação integrante da estrutura da Administração direta e da Administração indireta
- **entidade**: unidade de atuação dotada de personalidade jurídica
- **autoridade**: servidor ou agente público dotado de poder de decisão
- **princípio da Verdade Material**: norteia a atuação do administrador público em processos administrativos
- **princípio da segurança jurídica**: aplicado aos Estados e Municípios que devem aplicar a Lei 9.784/99 em ausência de lei local
- **Princípio da Razoável Duração do Processo**: manteve vínculo estreito com o da eficiência e visa à tramitação sem delongas injustificadas

### Referências legais
- Art. 9.784/99

### Jurisprudência
- Súmula nº 5 do STF
- MS 7415
- Súmula 641 do STJ
- Súmula 633 do STJ

### Dicas de prova
- Entenda o conceito de órgão, entidade e autoridade no contexto do processo administrativo federal.
- Conheça os princípios da Verdade Material, segurança jurídica e razoável duração do processo.
- Aprenda a aplicação da Lei 9.784/99 em diferentes contextos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.465", "page_number": 465, "discipline": "Direito Administrativo", "legal_refs": ["Art. 9.784/99"], "jurisprudence": ["Súmula nº 5 do STF", "MS 7415", "Súmula 641 do STJ", "Súmula 633 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T13:15:19.517168+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=465", "doc_key": "c2f86ec1f710767feea69215b6d6c252"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '7a4cf3a606125b2e7b2eeaa1cb7c17138cc1cc59ec32c5964fe41ba3465bc6c7'),
  ('cpiuris2025::da4177a434247c538412f265490361f9', 'doutrina', 'cp_iuris', 'Direito Administrativo — Processo Administrativo Federal e seus Critérios', '## Processo Administrativo Federal e seus Critérios

Descreve os critérios para o processo administrativo federal, incluindo a atuação conforme a lei, atendimento ao interesse público, objetividade e divulgação oficial dos atos administrativos.

### Conceitos
- **Atuação Conforme a Lei**: Acessar à lei para realizar as atividades administrativas.
- **Atendimento ao Interesse Público**: Priorizar o interesse público acima do interesse individual.
- **Objetividade**: Manter a imparcialidade e a neutralidade na tomada de decisões administrativas.
- **Divulgação Oficial dos Atos Administrativos**: Fazer pública as decisões e atos administrativos para garantir transparência.

### Referências legais
- Art. 2º, Parágrafo único da Lei nº 9.784/1999

### Jurisprudência
- Súmula 665-STJ

### Dicas de prova
- Entenda a importância do contraditório e da ampla defesa no processo administrativo.
- Conheça os critérios para o processo administrativo federal e como eles devem ser aplicados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.466 (1)", "page_number": 466, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2º, Parágrafo único da Lei nº 9.784/1999"], "jurisprudence": ["Súmula 665-STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T13:16:17.906867+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=466", "doc_key": "da4177a434247c538412f265490361f9"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6c5321919989274c38bb6e223cb27425b439ced820771459d83adba9cfae917e'),
  ('cpiuris2025::ceb24182b0f9cb02148878033ad1acf3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Direitos do Administrado', '## Direitos do Administrado

O administrado tem direitos específicos perante a Administração, como ser tratado com respeito, ter ciência da tramitação dos processos e fazer-se assistir por advogado.

### Conceitos
- **Direitos do Administrado**: direitos assegurados ao administrado perante a Administração
- **Respeito pelas autoridades e servidores**: dever de facilitar o exercício dos direitos e cumprimento das obrigações
- **Tramitação dos processos**: direito à ciência da tramitação dos processos em que tem a condição de interessado
- **Vista dos autos**: direito à vista dos autos e cópias de documentos neles contidos
- **Alegações e apresentação de documentos**: direito a formular alegações e apresentar documentos antes da decisão
- **Fazer-se assistir por advogado**: facultatividade para fazer-se assistir por advogado, salvo em casos obrigatórios

### Referências legais
- Art. 3º da Lei nº X
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pegar a palavra ''respeito'' e entender que é um direito do administrado.
- Entender que a tramitação dos processos é um direito importante para o administrado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.466 (2)", "page_number": 466, "discipline": "Direito Administrativo", "legal_refs": ["Art. 3º da Lei nº X", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T13:17:05.762127+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=466", "doc_key": "ceb24182b0f9cb02148878033ad1acf3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '88ce2cc84c58b4fd93b7d54b783962f30823adc8fac1000d8ea8574ecc6a51ef'),
  ('cpiuris2025::3f3b0df27b4bf5b7f417093676b70bd0', 'doutrina', 'cp_iuris', 'Direito Administrativo — Início do Processo Administrativo', '## Início do Processo Administrativo

O processo administrativo pode iniciar-se de ofício ou a pedido de interessado. A autoridade administrativa pode iniciar o processo sem necessidade de solicitação do interessado, de acordo com o princípio da Oficialidade.

### Conceitos
- **Oficialidade**: Princípio que determina que a Administração Pública pode iniciar o processo administrativo de ofício.
- **Requerimento inicial**: Documento que contém os dados necessários para iniciar o processo administrativo, como identificação do interessado e formulação do pedido.

### Referências legais
- Art. 5º
- Art. 6º
- Art. 7º

### Dicas de prova
- Entenda o princípio da Oficialidade e a importância do requerimento inicial.
- Conheça os requisitos necessários para iniciar o processo administrativo de ofício.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.467 (1)", "page_number": 467, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º", "Art. 6º", "Art. 7º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:17:44.603515+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=467", "doc_key": "3f3b0df27b4bf5b7f417093676b70bd0"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9aa4b7e1b1cd32c34c7e26095ec330f9a03bf152f6b890b0677ecb54e3f1a420'),
  ('cpiuris2025::2253fff179edc9cb0a420f73b0ab27ed', 'doutrina', 'cp_iuris', 'Direito Administrativo — Impedimentos e Suspeição em Processos Administrativos', '## Impedimentos e Suspeição em Processos Administrativos

O artigo 18 estabelece os impedimentos para servidores ou autoridades que atuam em processos administrativos, incluindo interesses diretos ou indiretos, participação como perito ou testemunha, e situações familiares. O artigo 19 obriga a comunicação do impedimento à autoridade competente.

### Conceitos
- **Impedimento**: Restrição para servidores ou autoridades atuarem em processos administrativos
- **Suspeição**: Situacao que pode afetar a imparcialidade de um servidor ou autoridade em um processo administrativo

### Referências legais
- Art. 18 da Lei X
- Art. 19 da Lei X

### Dicas de prova
- Entenda a distinção entre impedimento e suspeição
- Identifique as situações que podem gerar impedimento ou suspeição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.467 (2)", "page_number": 467, "discipline": "Direito Administrativo", "legal_refs": ["Art. 18 da Lei X", "Art. 19 da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:18:28.332990+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=467", "doc_key": "2253fff179edc9cb0a420f73b0ab27ed"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '36fa4e2214bf7c214d66cf4451eefb33f29681c2c0bc5aa1f68fb9bfaae1867b'),
  ('cpiuris2025::59e4c27a51db7c8de3fa742b0c5d9187', 'doutrina', 'cp_iuris', 'Direito Administrativo — Forma, Tempo e Lugar dos Atos do Processo Administrativo', '## Forma, Tempo e Lugar dos Atos do Processo Administrativo

Regulamentam-se os atos do processo administrativo em relação à forma, tempo e lugar de sua realização.

### Conceitos
- **Autoridade Competente**: Pode ser arguida a suspeição de autoridade ou servidor que tenha amizade íntima ou inimizade notória com algum dos interessados.
- **Intimação**: O órgão competente determinará a intimação do interessado para ciência de decisão ou a efetivação de diligências.
- **Prazo de Intimação**: A antecedência mínima de três dias úteis quanto à data de comparecimento.

### Referências legais
- Art. 20
- Art. 21
- Art. 22
- Art. 23
- Art. 24
- Art. 25
- Art. 26

### Dicas de prova
- Familiarize-se com a definição de suspeição e sua arguição.
- Entenda o conceito de intimação e suas prescrições legais.
- Conheça os prazos de intimação e seus requisitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.468 (1)", "page_number": 468, "discipline": "Direito Administrativo", "legal_refs": ["Art. 20", "Art. 21", "Art. 22", "Art. 23", "Art. 24", "Art. 25", "Art. 26"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:19:16.305940+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=468", "doc_key": "59e4c27a51db7c8de3fa742b0c5d9187"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '64dd51b2689b2f2d78d5863ce8bc203a212aeb1aeb00e0a7b764763b60f84236'),
  ('cpiuris2025::fa42ee764c09ba8216bcdf03d1428406', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desatendimento à intimação e produção dos efeitos da revelia', '## Desatendimento à intimação e produção dos efeitos da revelia

O desatendimento à intimação não impede a produção dos efeitos da revelia no processo administrativo.

### Conceitos
- **Revelia**: Falta de defesa em um processo
- **Desatendimento à intimação**: Não receber a intimação do processo

### Referências legais
- Art. 27 da Lei X

### Dicas de prova
- Entenda a diferença entre desatendimento à intimação e revelia
- Conheça o prazo para decidir no processo administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.468 (2)", "page_number": 468, "discipline": "Direito Administrativo", "legal_refs": ["Art. 27 da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:19:41.874445+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=468", "doc_key": "fa42ee764c09ba8216bcdf03d1428406"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b52abe09212f401f3219e87d58f7e2c9a5201efb9e1ab466967da712637beec8'),
  ('cpiuris2025::9597d06618a29ebe5847b831d52f73de', 'doutrina', 'cp_iuris', 'Direito Administrativo — Decisão Coordenada no Processo Administrativo Federal', '## Decisão Coordenada no Processo Administrativo Federal

A decisão coordenada é uma instância interinstitucional que atua de forma compartilhada para simplificar o processo administrativo, envolvendo participação concomitante de todas as autoridades e agentes decisórios.

### Conceitos
- **Decisão Coordenada**: Instância interinstitucional que atua de forma compartilhada para simplificar o processo administrativo.
- **Participação Concomitante**: A participação de todas as autoridades e agentes decisórios em uma única instância.
- **Responsabilidade Originária**: A responsabilidade de cada órgão ou autoridade envolvido na decisão coordenada.
- **Princípios da Legalidade, Eficiência e Transparência**: Princípios que devem orientar a decisão coordenada.

### Referências legais
- Art. 49-B

### Dicas de prova
- Entenda a importância da participação concomitante em uma decisão coordenada.
- Conheça os princípios que devem orientar a decisão coordenada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.469 (1)", "page_number": 469, "discipline": "Direito Administrativo", "legal_refs": ["Art. 49-B"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:20:40.202145+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=469", "doc_key": "9597d06618a29ebe5847b831d52f73de"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4867895e851b237d3a456ad2df8e62666d7874dffeb5263592148eddeed35ff0'),
  ('cpiuris2025::8e31f25538cbcc5e989ba0e2003dc3ea', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atas administrativas e motivação', '## Atas administrativas e motivação

Resumo do artigo 50 e seus incisos, relacionando a necessidade de motivação em atos administrativos que afetam direitos ou interesses.

### Conceitos
- **ato administrativo**: Ato emitido por um órgão ou entidade do Poder Executivo
- **motivação**: Explicação dos fatos e fundamentos jurídicos que justificam o ato administrativo
- **decisão coordenada**: Decisão tomada por um órgão ou entidade em conjunto com outros órgãos ou entidades
- **ata**: Documento que contém a decisão e os fundamentos do ato administrativo

### Referências legais
- Art. 50 da Lei X

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de ato administrativo e sua motivação.
- Identifique os incisos do artigo 50 e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.469 (2)", "page_number": 469, "discipline": "Direito Administrativo", "legal_refs": ["Art. 50 da Lei X"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T13:21:18.039941+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=469", "doc_key": "8e31f25538cbcc5e989ba0e2003dc3ea"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f3276547a3fe5e35bed35fcac5c7f3d11635a5688fffbbf060060631e5858db5'),
  ('cpiuris2025::7efbb224fa5f6fa2ff5608cabab29787', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desistência e extinção do processo administrativo', '## Desistência e extinção do processo administrativo

O interessado pode desistir total ou parcialmente do pedido formulado, renunciando a direitos disponíveis. A desistência não prejudica o prosseguimento do processo se considerar o interesse público.

### Conceitos
- **Desistência**: Ato pelo qual o interessado renuncia parcialmente ou totalmente a seus direitos e interesses no processo administrativo.
- **Extinção do processo**: Fim do processo administrativo devido à exaurição da sua finalidade, impossibilidade, inutilidade ou prejudicamento por fato superveniente.

### Referências legais
- Art. 51
- Art. 52
- Art. 56
- Art. 57
- Art. 58

### Dicas de prova
- Entenda a diferença entre desistência e extinção do processo administrativo.
- Conheça as legitimidades para interpor recurso administrativo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.470 (1)", "page_number": 470, "discipline": "Direito Administrativo", "legal_refs": ["Art. 51", "Art. 52", "Art. 56", "Art. 57", "Art. 58"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:21:59.217586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=470", "doc_key": "7efbb224fa5f6fa2ff5608cabab29787"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'cde222b1a7defc186ec7f98dba92a4478eaaaa20c1f355d606d30f09e1a76445'),
  ('cpiuris2025::5ed4591b4f7264eab7e877b1b6dfd3d6', 'doutrina', 'cp_iuris', 'Direito Administrativo — Prazo para interposição de recurso administrativo', '## Prazo para interposição de recurso administrativo

O prazo para interposição de recurso administrativo é de dez dias, contado a partir da ciência ou divulgação oficial da decisão recorrida. Em casos específicos, pode ser prorrogado por igual período com justificativa explícita.

### Conceitos
- **Recurso Administrativo**: Ação direta contra uma autoridade administrativa
- **Prazo para interposição de recurso**: Dez dias, contado a partir da ciência ou divulgação oficial da decisão recorrida
- **Suspensivo**: Efeito que impede a execução imediata do ato administrativo
- **Reexame**: Ação para reavaliar uma decisão administrativa

### Referências legais
- Art. 59 da Lei X
- Art. 60 da Lei X
- Art. 61 da Lei X

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre prazo para interposição de recurso e prazo para decisão do recurso
- Conheça as hipóteses em que o recurso pode ter efeito suspensivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.470 (2)", "page_number": 470, "discipline": "Direito Administrativo", "legal_refs": ["Art. 59 da Lei X", "Art. 60 da Lei X", "Art. 61 da Lei X"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T13:22:53.788160+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=470", "doc_key": "5ed4591b4f7264eab7e877b1b6dfd3d6"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '6c0301f4f26d17b1d6d9d0c0bab6cfd3536a22be568cb39e761db7a1acb680af'),
  ('cpiuris2025::271dc96e3d2b90be9e83dc42ad5967d4', 'doutrina', 'cp_iuris', 'Direito Administrativo — Recurso administrativo', '## Recurso administrativo

Resumo do artigo 63 a 65 sobre processos administrativos federais, incluindo prazos e regras de recurso.

### Conceitos
- **Recurso administrativo**: Procedimento utilizado para questionar uma decisão administrativa
- **Prazo**: Período dentro do qual uma ação deve ser concluída
- **Cientificação oficial**: Comunicação formal de uma decisão ou ato administrativo
- **Preclusão administrativa**: Fim do prazo para interpor recurso administrativo

### Referências legais
- Art. 63 da Lei X
- Art. 64 da Lei X
- Art. 65 da Lei X
- Art. 66 da Lei X

### Dicas de prova
- Entenda a diferença entre prazo e vencimento.
- Conheça as regras de cientificação oficial e preclusão administrativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.471 (1)", "page_number": 471, "discipline": "Direito Administrativo", "legal_refs": ["Art. 63 da Lei X", "Art. 64 da Lei X", "Art. 65 da Lei X", "Art. 66 da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:23:37.906565+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=471", "doc_key": "271dc96e3d2b90be9e83dc42ad5967d4"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '3c0f476e416ce56fded8154db8b805ebdae89cff74b692d96d9dd4b74217c08d'),
  ('cpiuris2025::476a1673c66508016e67ea6430f54edb', 'doutrina', 'cp_iuris', 'Direito Administrativo — Prazos processuais e prioridade em procedimentos administrativos', '## Prazos processuais e prioridade em procedimentos administrativos

Art. 67: prazos processuais não se suspensam salvo motivo de força maior comprovada. Art. 69-A: prioridade na tramitação para pessoas com certas condições de saúde.

### Conceitos
- **força maior**: motivo que justifica a suspensão de prazos processuais
- **prioridade**: regime especial concedido a procedimentos administrativos em favor de certas pessoas
- **procedimento administrativo**: processo formalizado pela administração pública

### Referências legais
- Art. 67
- Art. 69-A

### Dicas de prova
- Entenda a diferença entre força maior e prioridade em procedimentos administrativos.
- Conheça as condições de saúde que conferem prioridade na tramitação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.471 (2)", "page_number": 471, "discipline": "Direito Administrativo", "legal_refs": ["Art. 67", "Art. 69-A"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:24:12.661473+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=471", "doc_key": "476a1673c66508016e67ea6430f54edb"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'e57db1f15f7bc711a0098bc54590c5eed2d94b6cf90f8c6d781ac2f9b4d2678b'),
  ('cpiuris2025::0c00bce7ce0be418d0479a315f2b0096', 'doutrina', 'cp_iuris', 'Direito Administrativo — Responsabilidade da pessoa jurídica e seus dirigentes', '## Responsabilidade da pessoa jurídica e seus dirigentes

A Lei Anticorrupção estabelece a responsabilização objetiva administrativa e civil de pessoas jurídicas pela prática de atos contra a administração pública, nacional ou estrangeira. A responsabilidade da pessoa jurídica não exclui a responsabilidade individual dos seus dirigentes.

### Conceitos
- **Responsabilidade objetiva**: A responsabilidade de uma pessoa jurídica pela prática de atos contra a administração pública
- **Pessoa jurídica**: Entidade que pode ser responsabilizada por atos ilícitos
- **Dirigente**: Pessoa natural que exerce função de direção em uma pessoa jurídica
- **Responsabilidade solidária**: A responsabilidade mútua de várias pessoas jurídicas ou indivíduos por um ato ilícito

### Referências legais
- Art. 1º da Lei nº 12.846/2013

### Dicas de prova
- Entenda a noção de responsabilidade objetiva e como ela se aplica às pessoas jurídicas
- Conheça as hipóteses em que a responsabilidade da pessoa jurídica é restringida ou excluída', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.473", "page_number": 473, "discipline": "Direito Administrativo", "legal_refs": ["Art. 1º da Lei nº 12.846/2013"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:25:11.398282+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=473", "doc_key": "0c00bce7ce0be418d0479a315f2b0096"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'bb6674f81b74921077be233ee3257800dd77e1f64011914e4dce8a5b85913e73'),
  ('cpiuris2025::2a8d5ceb00b7671231ce9fac49aef26e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Atos lesivos à administração pública', '## Atos lesivos à administração pública

Definição dos atos que configuram lesão ao patrimônio público nacional ou estrangeiro, princípios da administração pública e compromissos internacionais.

### Conceitos
- **Atos lesivos à administração pública**: Práticas que atentem contra o patrimônio público nacional ou estrangeiro, princípios da administração pública ou compromissos internacionais.
- **Prometer, oferecer ou dar vantagem indevida a agente público**: Prática que configura ato lesivo à administração pública
- **Financiar, custear, patrocinar ou subvencionar prática de atos ilícitos**: Apoio direto ou indireto a práticas ilegais
- **Utilizar-se de interposta pessoa física ou jurídica para ocultar interesses**: Técnica utilizada para dissimular identidade dos beneficiários
- **Frustrar ou fraudar procedimento licitatório público**: Prática que impede a realização de ato de procedimento licitatório público
- **Dificultar atividade de investigação ou fiscalização**: Prática que obstaculiza a atuação de órgãos públicos em investigações ou fiscalizações

### Referências legais
- Art. 5º da Lei n° 12.846/2013

### Dicas de prova
- Entenda a definição de atos lesivos à administração pública e como elas são configuradas.
- Identifique as práticas que podem dificultar a investigação ou fiscalização de órgãos públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.474 (1)", "page_number": 474, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º da Lei n° 12.846/2013"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:26:15.268475+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=474", "doc_key": "2a8d5ceb00b7671231ce9fac49aef26e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'aefa693b36185f0ac72d8ae00c3d45c26d169563eccf09d53a81ea908cfac2fd'),
  ('cpiuris2025::60b2c0de3fb5981daf51c274cc3c66e5', 'doutrina', 'cp_iuris', 'Direito Administrativo — Agente Público Estrangeiro', '## Agente Público Estrangeiro

Pessoa que exerce cargo, emprego ou função pública em órgãos, entidades estatais ou representações diplomáticas de país estrangeiro, bem como pessoas jurídicas controladas diretamente ou indiretamente pelo poder público de país estrangeiro.

### Conceitos
- **Agente Público Estrangeiro**: Pessoa que exerce cargo, emprego ou função pública em órgãos, entidades estatais ou representações diplomáticas de país estrangeiro
- **Pessoas Jurídicas Controladas**: Organizações públicas internacionais e pessoas jurídicas controladas diretamente ou indiretamente pelo poder público de país estrangeiro

### Referências legais
- Art. 6º da Lei...
- Súmula N STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre agente público e pessoa jurídica controlada
- Entenda a noção de pessoas jurídicas internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.474 (2)", "page_number": 474, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º da Lei...", "Súmula N STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T13:26:52.825787+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=474", "doc_key": "60b2c0de3fb5981daf51c274cc3c66e5"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'ae7452938e5ffff5f530d0b1538d612131c8d228990fec840d586b7ea38ffeda'),
  ('cpiuris2025::fbc1b4adef3ff307191ca9d616e0ce8e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Sanções Administrativas e Processo de Responsabilidade', '## Sanções Administrativas e Processo de Responsabilidade

A lei estabelece sanções administrativas para pessoas jurídicas, incluindo multa patrimonial e reputacional, além da obrigação de reparar o dano causado. O processo administrativo de responsabilidade é conduzido por comissão designada pela autoridade instauradora.

### Conceitos
- **Multa Patrimonial**: Sanção administrativa que visa penalizar a pessoa jurídica por infrações
- **Multa Reputacional**: Sanção administrativa que visa prejudicar a reputação da pessoa jurídica
- **Reparação Integral do Dano**: Obrigação de reparar o dano causado pela infração
- **Processo Administrativo de Responsabilidade**: Procedimento que visa apurar a responsabilidade de pessoa jurídica por infrações

### Referências legais
- Art. 8º da Lei Anticorrupção
- Art. 10 da Lei Anticorrupção

### Dicas de prova
- Entenda a diferença entre multa patrimonial e reputacional
- Conheça a obrigação de reparar o dano causado
- Avalie a importância do processo administrativo de responsabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.475 (1)", "page_number": 475, "discipline": "Direito Administrativo", "legal_refs": ["Art. 8º da Lei Anticorrupção", "Art. 10 da Lei Anticorrupção"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:27:54.465337+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=475", "doc_key": "fbc1b4adef3ff307191ca9d616e0ce8e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2de68bb80b2539529aeac0760afbef227aa0adec99b848fca1c2cf1783105f1b'),
  ('cpiuris2025::cf1d61e5bb48114845f9fe9e3314dcda', 'doutrina', 'cp_iuris', 'Direito Administrativo — Investigação de Infrações', '## Investigação de Infrações

Regras para a investigação e processamento de infrações, incluindo busca e apreensão, bem como prazos para conclusão do processo.

### Conceitos
- **Investigação de Infrações**: Ação realizada pelo órgão administrativo para determinar a existência ou não de infrações.
- **Comissão Instalada**: Entidade responsável pela investigação e processamento de infrações.
- **Suspensão de Efeitos**: Medida cautelar proposta à autoridade instauradora para suspender os efeitos do ato ou processo objeto da investigação.
- **Prazo de Conclusão**: Período dentro do qual a comissão deve concluir o processo.
- **Relatórios**: Documentos apresentados pela comissão sobre os fatos apurados e eventual responsabilidade da pessoa jurídica.
- **Sanções**: Medidas legais aplicadas às pessoas jurídicas responsáveis pelas infrações.
- **Autoridade Instauradora**: Órgão administrativo que institui a comissão instalada e decide sobre prazos e medidas.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- ...

### Jurisprudência
- Súmula 434 do STF
- ...

### Dicas de prova
- Entenda a importância da investigação de infrações e o papel da comissão instalada.
- Conheça as regras para suspensão de efeitos e prazo de conclusão do processo.
- Aprenda a distinguir entre relatórios e sanções aplicadas às pessoas jurídicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.475 (2)", "page_number": 475, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "..."], "jurisprudence": ["Súmula 434 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T13:28:49.452193+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=475", "doc_key": "cf1d61e5bb48114845f9fe9e3314dcda"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '26647b1f10e877872d50d00805c29e7953e862bb7449f319d14ad962bac129c8'),
  ('cpiuris2025::face10ab4e37a003cf3446ab6f638bd5', 'doutrina', 'cp_iuris', 'Direito Administrativo — Desconsideração da Personalidade Jurídica e Acordo de Leniência', '## Desconsideração da Personalidade Jurídica e Acordo de Leniência

A Lei Anticorrupção estabelece que a personalidade jurídica pode ser desconsiderada se utilizada com abuso do direito para facilitar ou encobrir práticas ilícitas. Além disso, o acordo de leniência é um mecanismo pelo qual as pessoas jurídicas podem colaborar com as investigações e processos administrativos em troca de benefícios.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Ação administrativa que busca desconsiderar a personalidade jurídica de uma pessoa jurídica por abuso do direito
- **Acordo de Leniência**: Mecanismo pelo qual as pessoas jurídicas podem colaborar com as investigações e processos administrativos em troca de benefícios

### Referências legais
- Art. 11 da Lei N° 12.846/2013
- Art. 14 da Lei N° 12.846/2013

### Dicas de prova
- Entenda a diferença entre desconsideração da personalidade jurídica e acordo de leniência.
- Conheça os requisitos para o acordo de leniência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.476 (1)", "page_number": 476, "discipline": "Direito Administrativo", "legal_refs": ["Art. 11 da Lei N° 12.846/2013", "Art. 14 da Lei N° 12.846/2013"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:29:37.932572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=476", "doc_key": "face10ab4e37a003cf3446ab6f638bd5"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f248d73653aa8f129664f60415db4886cf199fd8783d056c261d056cef94cea4'),
  ('cpiuris2025::c7640c03a9654bbbfcb68cdd1b27f163', 'doutrina', 'cp_iuris', 'Direito Administrativo — Acordo de Leniência', '## Acordo de Leniência

O acordo de leniência isenta a pessoa jurídica das sanções previstas em certos artigos e reduz o valor da multa aplicável até 2/3, mas não exime a obrigação de reparar integralmente o dano causado.

### Conceitos
- **Acordo de Leniência**: acordo entre a administração pública e uma pessoa jurídica para reduzir as sanções
- **Multa**: sancionamento aplicado pela administração pública
- **Sanção**: ação disciplinar tomada pelo Estado contra uma pessoa jurídica
- **Pessoa Jurídica**: entidade que pode ser responsável por atos e contratos

### Referências legais
- Art. 6º, inciso II; Art. 19, inciso IV; §2º da Lei X

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre multa e sanção
- Conheça as condições para isenção de multa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.476 (2)", "page_number": 476, "discipline": "Direito Administrativo", "legal_refs": ["Art. 6º, inciso II; Art. 19, inciso IV; §2º da Lei X"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T13:30:25.707548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=476", "doc_key": "c7640c03a9654bbbfcb68cdd1b27f163"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '4f6f1f0956fd8dbef1a3dc613bac69ad39b13e4f954dedb5b3f6e663bc61c7f4'),
  ('cpiuris2025::db4990c9257cdf6ce2fd23afc385cbb2', 'doutrina', 'cp_iuris', 'Direito Administrativo — Acordo de Leniência e Responsabilidade Judicial', '## Acordo de Leniência e Responsabilidade Judicial

A Lei Anticorrupção estabelece o acordo de leniência como meio para assegurar a colaboração das pessoas jurídicas com a administração pública. O acordo interrompe o prazo prescricional dos atos ilícitos e impede a celebração de novo acordo por 3 anos, caso haja descumprimento. A responsabilidade judicial é objetiva e pode ser exercida tanto na esfera administrativa quanto no âmbito civil.

### Conceitos
- **Acordo de Leniência**: Convenção entre a administração pública e uma pessoa jurídica para assegurar a colaboração
- **Responsabilidade Judicial**: Obrigação objetiva da pessoa jurídica perante o Estado e os cidadãos
- **Prazo Prescricional**: Período durante o qual não pode ser processado um ato ilícito
- **Legitimidade Ativa**: Direito de uma entidade para agir em um processo

### Referências legais
- Art. 5º da Lei Anticorrupção
- Art. 8º da Lei Anticorrupção
- Art. 9º da Lei Anticorrupção

### Dicas de prova
- Entenda a diferença entre o acordo de leniência e a responsabilidade judicial
- Conheça as condições para a legitimidade ativa na ação comuns contra a administração pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.477 (1)", "page_number": 477, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º da Lei Anticorrupção", "Art. 8º da Lei Anticorrupção", "Art. 9º da Lei Anticorrupção"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:31:20.614877+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=477", "doc_key": "db4990c9257cdf6ce2fd23afc385cbb2"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '2dfe3d24ffdb188e1b98c3476b078872014ed222b7bcf4cabdf5fee005fc8cb4'),
  ('cpiuris2025::45b30d9bf31bf88f6a66b8c39898a6a8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Sanções Judiciais para Pessoas Jurídicas Infratoras', '## Sanções Judiciais para Pessoas Jurídicas Infratoras

São aplicadas sanções judiciais às pessoas jurídicas infratoras, incluindo perdimento de bens, suspensão ou interdição de atividades, dissolução compulsória e proibição de incentivos públicos.

### Conceitos
- **Pessoas Jurídicas**: Entidades que podem ser responsabilizadas por infrações
- **Sanções Judiciais**: Medidas legais aplicadas às pessoas jurídicas infratoras
- **Perdimento de Bens**: Derrubada total ou parcial de bens obtidos pela infração
- **Suspensão ou Interdição de Atividades**: Limitação temporária ou permanente das atividades da pessoa jurídica
- **Dissolução Compulsória**: Fim forçado e definitivo da pessoa jurídica
- **Proibição de Incentivos Públicos**: Restrição temporária ou permanente do acesso a incentivos públicos

### Referências legais
- Art. 19, §3º e §4º do Código de Processo Administrativo

### Dicas de prova
- Entenda a distinção entre sanções isoladas e cumulativas.
- Conheça as diferentes formas de aplicação das sanções judiciais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.477 (2)", "page_number": 477, "discipline": "Direito Administrativo", "legal_refs": ["Art. 19, §3º e §4º do Código de Processo Administrativo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:32:07.525976+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=477", "doc_key": "45b30d9bf31bf88f6a66b8c39898a6a8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '8b5540d0df8484ee45c22bee38da68a27b5aaacfdae0ed87b9490b3748c9bf3d'),
  ('cpiuris2025::6cde2337850e487b46cb66f6ee6ac424', 'doutrina', 'cp_iuris', 'Direito Administrativo — Indisponibilidade de bens e valores', '## Indisponibilidade de bens e valores

A indisponibilidade de bens, direitos ou valores é permitida para garantia do pagamento da multa ou reparação integral do dano causado, ressalvando o direito do terceiro de boa-fé.

### Conceitos
- **Indisponibilidade**: Medida que garante a proteção dos bens, direitos ou valores necessários à garantia do pagamento da multa ou reparação integral do dano causado.
- **Garantia**: Mecanismo que assegura o cumprimento de uma obrigação ou a realização de um ato.
- **Terceiro de boa-fé**: Pessoa que não tem conhecimento da irregularidade ou do erro que justifica a indisponibilidade de bens, direitos ou valores.
- **Multa**: Sancionamento aplicado às infrações administrativas.
- **Reparação integral**: Compensação total pelo dano causado à vítima.

### Referências legais
- Art. 7º da Lei Anticorrupção

### Dicas de prova
- Entenda a diferença entre multa e reparação integral.
- Conheça o conceito de terceiro de boa-fé e sua importância na indisponibilidade de bens.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.478", "page_number": 478, "discipline": "Direito Administrativo", "legal_refs": ["Art. 7º da Lei Anticorrupção"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:33:06.602391+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=478", "doc_key": "6cde2337850e487b46cb66f6ee6ac424"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a246eb93950d9e6f3dd7dea0961f8f870f4ec43f0a7c64b38f8cda8ba70d7ed8'),
  ('cpiuris2025::2abd400bc1143f7f2981d6fe4883b4f8', 'doutrina', 'cp_iuris', 'Direito Administrativo — Índices de Acórdãos e Ações Diretas', '## Índices de Acórdãos e Ações Diretas

Lista de acórdãos, ações diretas e agravo regimentais relacionados ao Direito Administrativo.

### Conceitos
- **Acórdão**: Decisão final do tribunal ou órgão administrativo competente
- **Ação Direta de Constitucionalidade**: Mecanismo processual que visa a interpretação da Constituição por meio de ações judiciais
- **Ação Direta de Inconstitucionalidade**: Mecanismo processual que visa a invalidação de leis ou atos administrativos incompatíveis com a Constituição
- **Agravo Regimental**: Recurso especial contra decisões do tribunal ou órgão administrativo competente

### Referências legais
- Art. 5º, inciso XXVII da CF/88
- Súmula 634 STF

### Jurisprudência
- RE 123456
- ADI 2.893/PE
- ADI 4.295/DF

### Dicas de prova
- Entenda a importância dos índices de acórdãos no Direito Administrativo.
- Conheça as diferenças entre Ação Direta de Constitucionalidade e Ação Direta de Inconstitucionalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.480", "page_number": 480, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, inciso XXVII da CF/88", "Súmula 634 STF"], "jurisprudence": ["RE 123456", "ADI 2.893/PE", "ADI 4.295/DF"], "confidence": 0.8, "extracted_at": "2026-05-25T13:33:58.939180+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=480", "doc_key": "2abd400bc1143f7f2981d6fe4883b4f8"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'b458a350e22641285549be5a8c5dbc9a649b4a18dc1845047adb950e3f9a1178'),
  ('cpiuris2025::4ad03c3e1cbdb906eab40f0db007d2e3', 'doutrina', 'cp_iuris', 'Direito Administrativo — Decreto-Lei e sua classificação', '## Decreto-Lei e sua classificação

Resumo do texto: Decreto-Lei é um tipo de lei que tem natureza administrativa, podendo ser classificado como uma medida provisória ou uma lei ordinária. Exemplos incluem Decreto-Lei nº 200/67 e Decreto-Lei nº 20.910/32.

### Conceitos
- **Decreto-Lei**: Lei com natureza administrativa
- **Medida Provisória**: Lei que tem natureza administrativa e é aprovada por decreto do Presidente da República
- **Lei Ordinária**: Lei que tem natureza jurídica e é aprovada pelo Congresso Nacional

### Referências legais
- Art. 2.º da Constituição Federal de 1988

### Dicas de prova
- Entenda que Decreto-Lei é uma medida provisória com natureza administrativa
- Diferencie entre Medida Provisória e Lei Ordinária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.481", "page_number": 481, "discipline": "Direito Administrativo", "legal_refs": ["Art. 2.º da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:34:41.805274+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=481", "doc_key": "4ad03c3e1cbdb906eab40f0db007d2e3"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'a318ae1498a42e1fcb8c8c2f07a67f89267065ada3f9f2d41c7803b965a0230b'),
  ('cpiuris2025::a703d328d70c31a727ee897ea01d9a8e', 'doutrina', 'cp_iuris', 'Direito Administrativo — Lista de Leis e Códigos', '## Lista de Leis e Códigos

Lista de leis e códigos brasileiros mencionados no texto, incluindo a Constituição Federal.

### Conceitos
- **Lei Complementar**: Lei que complementa uma lei ordinária
- **Código Civil**: Código que regula as relações civis
- **Código Tributário Nacional**: Código que regula a tributação no Brasil
- **Constituição Federal**: Documento que estabelece as bases do Estado brasileiro

### Referências legais
- Art. X da Constituição Federal de 1988
- LC n.º 123/03
- LC n.º 152/2015
- Código Tributário Nacional
- Lei de Introdução às Normas do Direito Brasileiro

### Dicas de prova
- Identifique a Lei Complementar mencionada no texto
- Diferencie entre Código Civil e Código Tributário Nacional
- Entenda o papel da Constituição Federal na estrutura do Estado brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.482", "page_number": 482, "discipline": "Direito Administrativo", "legal_refs": ["Art. X da Constituição Federal de 1988", "LC n.º 123/03", "LC n.º 152/2015", "Código Tributário Nacional", "Lei de Introdução às Normas do Direito Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:35:38.310567+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=482", "doc_key": "a703d328d70c31a727ee897ea01d9a8e"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '5a7498fb0ab2a5354c5ecaac7bc6da9bd03eb87034716bfb98d8190dc91fb2f3'),
  ('cpiuris2025::592fcfb537f8c7f66d09d863b548a92b', 'doutrina', 'cp_iuris', 'Direito Administrativo — Leis e Medidas Provisórias', '## Leis e Medidas Provisórias

Lista de leis e medidas provisorias publicadas até o ano de 2023, incluindo a Lei n.º 12.016/09, entre outras.

### Conceitos
- **Medidas Provisórias**: Instrumento do poder executivo para resolver situações de emergência ou crise.
- **Lei n.º 12.016/09**: Lei que regulamenta a gestão pública e o patrimônio público.
- **Poder Executivo**: Unidade do Estado que exerce a autoridade sobre os cidadãos.
- **Gestão Pública**: Modalidade de gestão que visa maximizar a eficiência e a eficácia na prestação dos serviços públicos.
- **Patrimônio Público**: Bens e direitos que pertencem ao Estado ou às entidades públicas.
- **Medidas Provisórias**: Instrumento do poder executivo para resolver situações de emergência ou crise.
- **Legislação Administrativa**: Normas e regras que regem a atividade administrativa.
- **Recurso Extraordinário**: Procedimento judicial que visa revisar uma decisão de um tribunal inferior.

### Referências legais
- Art. 37 da Constituição Federal
- Art. 81 do Código de Processo Administrativo

### Jurisprudência
- RE 86.933/SP
- RE 135.310/SP

### Dicas de prova
- Identifique a legislação administrativa que regula a gestão pública e o patrimônio público.
- Entenda a diferença entre medidas provisorias e leis.
- Conheça as regras do recurso extraordinário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.483", "page_number": 483, "discipline": "Direito Administrativo", "legal_refs": ["Art. 37 da Constituição Federal", "Art. 81 do Código de Processo Administrativo"], "jurisprudence": ["RE 86.933/SP", "RE 135.310/SP"], "confidence": 0.8, "extracted_at": "2026-05-25T13:36:41.688688+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=483", "doc_key": "592fcfb537f8c7f66d09d863b548a92b"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '1586db0d362252fc86bf855ed7b219b822022b58a7fb071408b62f0934d1e981'),
  ('cpiuris2025::453ea3f48834db990a5aa1988500ba29', 'doutrina', 'cp_iuris', 'Direito Administrativo — Recurso Especial e Mandado de Segurança', '## Recurso Especial e Mandado de Segurança

Exemplos de recursos especiais e mandados de segurança, incluindo REs, RMSs e súmulas do STJ e STF.

### Conceitos
- **RE**: Recurso Especial
- **RMS**: Mandado de Segurança
- **STJ**: Superior Tribunal de Justiça
- **STF**: Supremo Tribunal Federal
- **Súmula**: Decisão final do tribunal sobre uma questão jurídica

### Referências legais
- Art. 5º, inciso XXXV da CF
- Art. 81 da LAD
- Código de Processo Civil

