- Conheça as súmulas do STJ e STF.
- Aprenda a aplicar o artigo 5º, inciso XXXV da CF em casos de mandado de segurança.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.484", "page_number": 484, "discipline": "Direito Administrativo", "legal_refs": ["Art. 5º, inciso XXXV da CF", "Art. 81 da LAD", "Código de Processo Civil"], "jurisprudence": ["RE 1.188.352/DF", "RE 1.209.429/SP", "Súmula nº 07, STJ", "Súmula nº 119, STJ", "Súmula nº 14, STF"], "confidence": 0.8, "extracted_at": "2026-05-25T13:37:35.682787+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=484", "doc_key": "453ea3f48834db990a5aa1988500ba29"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', '9b181c39de586345655eac457c67a6aedaf3e5a6f54f6beb4b12a8df177bf1db'),
  ('cpiuris2025::1ef2e389d5b87ded860e4658ca8395ce', 'doutrina', 'cp_iuris', 'Direito Administrativo — Súmulas do STJ e STF', '## Súmulas do STJ e STF

Resumo de súmulas do STJ e STF relacionadas ao Direito Administrativo.

### Conceitos
- **Súmula Vinculante**: súmula emitida pela Suprema Corte Federal que tem foro de direito e não pode ser alterada por ação judicial ou administrativa.
- **STJ**: Superior Tribunal de Justiça, órgão judiciário brasileiro responsável por julgar recursos federais
- **STF**: Suprema Corte Federal, órgão judiciário brasileiro responsável por julgar recursos constitucionais e federais

### Referências legais
- Art. 102 da CF
- Súmula Vinculante nº 12, STF
- Súmula Vinculante nº 13, STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Súmula Vinculante

### Dicas de prova
- Entenda a diferença entre STJ e STF.
- Conheça as súmulas vinculantes e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf", "source_ref": "IURIS - Direito Administrativo - Vol. 02 - 2025.pdf · p.485", "page_number": 485, "discipline": "Direito Administrativo", "legal_refs": ["Art. 102 da CF", "Súmula Vinculante nº 12, STF", "Súmula Vinculante nº 13, STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Súmula Vinculante"], "confidence": 0.8, "extracted_at": "2026-05-25T13:38:33.850610+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Administrativo - Vol. 02 - 2025.pdf#page=485", "doc_key": "1ef2e389d5b87ded860e4658ca8395ce"}'::jsonb, '{"materia": "Direito Administrativo"}'::jsonb, 'cp_iuris_2025', 'f8190d54b58700d63233fd3253359fdff5434eba7a476b939f901027485dc052'),
  ('cpiuris2025::53732bc23e2d86de5b45a0833a726949', 'doutrina', 'cp_iuris', 'Direito Administrativo — Referências Bibliográficas', '## Referências Bibliográficas

