  ('cpiuris2025::2f3908c0622d01275b77d89e9eb2b534', 'doutrina', 'cp_iuris', 'Direito Ambiental — Introdução ao Direito Ambiental', '## Introdução ao Direito Ambiental

O direito ambiental é uma disciplina jurídica que regula as relações entre o homem e o meio ambiente, visando proteger a natureza e garantir o desenvolvimento sustentável.

### Conceitos
- **Meio Ambiente**: A natureza, incluindo todos os seres vivos, ecossistemas e processos biológicos
- **Desenvolvimento Sustentável**: Um estilo de desenvolvimento que atende às necessidades do presente sem comprometer as capacidades do futuro para atender às suas próprias necessidades

### Referências legais
- Art. 225 da Constituição Federal

### Dicas de prova
- Entenda a importância do meio ambiente e do desenvolvimento sustentável
- Conheça as principais diretrizes constitucionais que regem o direito ambiental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.2", "page_number": 2, "discipline": "Direito Ambiental", "legal_refs": ["Art. 225 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:39:38.422210+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=2", "doc_key": "2f3908c0622d01275b77d89e9eb2b534"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '940282b0084dfbc64a30bcbdbb5e89494cfbc595734b17b4f4a53d2e931d3f30'),
  ('cpiuris2025::31ccbb9b016749ccf5d93e524ce4e5f6', 'doutrina', 'cp_iuris', 'Direito Ambiental — Autor do texto', '## Autor do texto

Informações sobre o autor do texto, sem contexto específico.

### Conceitos
- **Procurador Federal**: Profissional responsável por defender os interesses do Estado em relação ao meio ambiente.
- **Núcleo de Defesa do Meio Ambiente**: Unidade organizacional dentro da Procuradoria-Geral Federal, com o objetivo de proteger o meio ambiente.

### Dicas de prova
- Identificar a fonte e a posição do autor em relação ao tema ambiental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.3", "page_number": 3, "discipline": "Direito Ambiental", "legal_refs": [], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:40:10.596250+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=3", "doc_key": "31ccbb9b016749ccf5d93e524ce4e5f6"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'd9e5d8f5461b05a26e3970ae54ab990fb51b0715ee743280c343895652b54caa'),
  ('cpiuris2025::1099e1414e3299ead54b8fe40e6f11d5', 'doutrina', 'cp_iuris', 'Direito Ambiental — Microssistema Jurídico de Tutela Ambiental', '## Microssistema Jurídico de Tutela Ambiental

Descreve o microssistema jurídico que regula a tutela ambiental, incluindo a criação do SISNAMA e do SNUC.

### Conceitos
- **SISNAMA**: Sistema Nacional do Meio Ambiente
- **SNUC**: Sistema Nacional de Unidades de Conservação da Natureza
- **Conferência das Nações Unidas sobre o Meio Ambiente Humano**: Evento que levou à criação do SISNAMA
- **Política Nacional do Meio Ambiente**: Policia governamental que regula a proteção ambiental
- **Objetivos do SNUC**: Metas para a conservação da natureza
- **Instrumentos do SISNAMA**: Leis e regulamentos que compõem o sistema
- **Sistema Nacional de Unidades de Conservação da Natureza**: Organização governamental que protege a natureza

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o papel do SISNAMA e do SNUC na tutela ambiental
- Conheça os objetivos e instrumentos desses sistemas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.4 (1)", "page_number": 4, "discipline": "Direito Ambiental", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:40:56.769957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=4", "doc_key": "1099e1414e3299ead54b8fe40e6f11d5"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '1800ec5900efeae3a5116a6e9db1ab09fd4333ae011b5a33f545f14cd354708c'),
  ('cpiuris2025::ddd02f55f0caf7d0f10d66415ceea902', 'doutrina', 'cp_iuris', 'Direito Ambiental — Tutela Ambiental e Espaços Territoriais Protegidos', '## Tutela Ambiental e Espaços Territoriais Protegidos

O texto discute os diferentes espaços territoriais protegidos, como Áreas de Preservação Permanente, Áreas de Reserva Legal e Áreas de Uso Alternativo do Solo, e como eles estão relacionados ao Sistema Nacional de Gerenciamento de Recursos Hídricos.

### Conceitos
- **Área de Preservação Permanente**: área protegida para preservar a biodiversidade
- **Áreas de Reserva Legal**: área protegida para garantir a segurança do solo e da água
- **Áreas de Uso Alternativo do Solo**: área onde o uso do solo é reestruturado para evitar a degradação ambiental
- **Sistema Nacional de Gerenciamento de Recursos Hídricos**: sistema que gerencia os recursos hídricos do país
- **Tutela Ambiental**: mecanismo jurídico que protege o meio ambiente

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a relação entre os espaços territoriais protegidos e o Sistema Nacional de Gerenciamento de Recursos Hídricos.
