  ('cpiuris2025::b74610b73eb0f6f215dd01c97ba5abf2', 'doutrina', 'cp_iuris', 'Direito Ambiental — Sistema de Responsabilização por Ilícitos Ambientais', '## Sistema de Responsabilização por Ilícitos Ambientais

Descreve a criação e as diferentes formas de responsabilidade relacionadas a ilícitos ambientais.

### Conceitos
- **Responsabilidade Administrativa**: Responsabilidade do Estado ou entidades governamentais
- **Tríplice Responsabilização**: Responsabilidade civil, penal e administrativa por ilícitos ambientais
- **Tutela Processual**: Meio processual destinado a proteger os direitos do meio ambiente
- **Evolução Histórica**: Desenvolvimento e mudanças ao longo do tempo da responsabilidade ambiental

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a tríplice responsabilização
- Conheça as diferentes formas de responsabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Direito Ambiental", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:42:24.343782+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=4", "doc_key": "b74610b73eb0f6f215dd01c97ba5abf2"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '6b093ed7632e06881d11e2dea4b89bfd36dbaf3aef7fc63b9400e139d980e16c'),
  ('cpiuris2025::05607fd94b2aeadadee7f38f238e8c8c', 'doutrina', 'cp_iuris', 'Direito Ambiental — Microssistema Jurídico de Tutela Ambiental', '## Microssistema Jurídico de Tutela Ambiental

A necessidade de compreender o Direito Ambiental no Brasil é urgente e essencial para resolver os conflitos ambientais globais.

### Conceitos
- **Direito Ambiental**: ramo do Direito que disciplina a preservação ambiental
- **Tutela Ambiental**: proteção e conservação do meio ambiente
- **Desenvolvimento Econômico**: expansão econômica para melhorar a qualidade de vida
- **Efeito Estufa**: fenômeno climático causado pela concentração de gases
- **Políticas Públicas Ambientais**: medidas governamentais para proteger o meio ambiente

### Referências legais
- Art. 225, inciso III da Constituição Federal
- Súmula 646 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Tutela Ambiental

### Dicas de prova
- Entenda a relação entre o desenvolvimento econômico e a preservação ambiental
- Conheça as consequências do efeito estufa e das políticas públicas ambientais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Direito Ambiental", "legal_refs": ["Art. 225, inciso III da Constituição Federal", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Tutela Ambiental"], "confidence": 0.8, "extracted_at": "2026-05-25T13:43:13.231573+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=5", "doc_key": "05607fd94b2aeadadee7f38f238e8c8c"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '07af3b2dff4e2b989d2df4523dd4a30fdc3c59138b8962a6bec287ef04e6e281'),
  ('cpiuris2025::83e73429ac70de7d6462c0b10e4863bb', 'doutrina', 'cp_iuris', 'Direito Ambiental — Complexidade do Direito Ambiental', '## Complexidade do Direito Ambiental

A disciplina é complexa devido à ausência de um Código Ambiental unificador, levando a uma interpretação cuidadosa de várias leis e atos normativos.

### Conceitos
- **Código Ambiental**: não existente
- **Tutela Ambiental**: área jurídica que regula a proteção do meio ambiente

### Referências legais
- Constituição da República

### Dicas de prova
- Entenda a complexidade do Direito Ambiental e a necessidade de interpretação cuidadosa de várias leis.
- Identifique as fontes jurídicas que regem a tutela ambiental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Direito Ambiental", "legal_refs": ["Constituição da República"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:43:40.911765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=5", "doc_key": "83e73429ac70de7d6462c0b10e4863bb"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'b6842b1ac9a81daf078fba24c8a4e1e1a6051c54f2cb665c2639a2761b854cab'),
  ('cpiuris2025::341b6cf17f1cad8639dbd50ce98d2114', 'doutrina', 'cp_iuris', 'Direito Ambiental — Microssistema Jurídico de Tutela Ambiental', '## Microssistema Jurídico de Tutela Ambiental

Reúne leis e normas que regem a proteção do meio ambiente, incluindo a fauna, o meio ambiente, a qualidade do ar, a pesca de cetáceos, a gestão de florestas públicas, entre outras.

### Conceitos
- **Lei Federal**: Lei que regula um aspecto específico do direito ambiental
- **Política Nacional**: Política estabelecida pelo governo para regular um aspecto específico do meio ambiente
- **Resolução do Conama**: Resolução emitida pela Comissão Nacional do Meio Ambiente (Conama) sobre um tema ambiental específico
- **Decreto Federal**: Decreto emitido pelo governo para regular um aspecto específico do meio ambiente

### Referências legais
- Art. 5 da Lei Federal n.º 5.197/67
- Art. 2 da Lei Federal n.º 6.938/81
- Art. 1 da Lei Federal n.º 14.850/24

### Jurisprudência
- RE 123456
- Tema repetitivo: Política Nacional do Meio Ambiente

### Dicas de prova
- Entenda a hierarquia das leis ambientais e como elas se relacionam entre si.
- Conheça as resoluções do Conama e suas implicações práticas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.6", "page_number": 6, "discipline": "Direito Ambiental", "legal_refs": ["Art. 5 da Lei Federal n.º 5.197/67", "Art. 2 da Lei Federal n.º 6.938/81", "Art. 1 da Lei Federal n.º 14.850/24"], "jurisprudence": ["RE 123456", "Tema repetitivo: Política Nacional do Meio Ambiente"], "confidence": 0.8, "extracted_at": "2026-05-25T13:44:47.878314+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=6", "doc_key": "341b6cf17f1cad8639dbd50ce98d2114"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '717320e52b380a0c338e8e7d1f1894af97e3d7bf0f933139a942bafda4e8d219'),
  ('cpiuris2025::6f9067d883ebd5f4ac7065ca1976eab5', 'doutrina', 'cp_iuris', 'Direito Ambiental — Microssistema Jurídico de Tutela Ambiental (MTA)', '## Microssistema Jurídico de Tutela Ambiental (MTA)

O Microssistema Jurídico de Tutela Ambiental é um conjunto de normas que disciplinam crimes e infrações ambientais, com princípios e lógica jurídica próprias. Para compreendê-lo adequadamente, é necessário um diálogo entre suas fontes normativas.

### Conceitos
- **Microssistema Jurídico de Tutela Ambiental (MTA)**: conjunto de normas que disciplinam crimes e infrações ambientais
- **Princípios jurídicos próprios**: princípios que regem o Microssistema Jurídico de Tutela Ambiental
- **Institutos jurídicos**: institutos previstos em leis específicas para aplicação e interpretação do MTA

### Referências legais
- Art. 72 da Lei Federal n.º 9.605/98
- Decreto Federal n.º 6.514/08
- Lei Federal n.º 6.938/81
- Art. 70, §1º da Lei Federal n.º 9.605/98

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de Microssistema Jurídico de Tutela Ambiental e seus princípios jurídicos próprios
- Conheça as institutos jurídicos previstos em leis específicas para aplicação e interpretação do MTA', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direito Ambiental", "legal_refs": ["Art. 72 da Lei Federal n.º 9.605/98", "Decreto Federal n.º 6.514/08", "Lei Federal n.º 6.938/81", "Art. 70, §1º da Lei Federal n.º 9.605/98"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T13:45:44.421959+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=7", "doc_key": "6f9067d883ebd5f4ac7065ca1976eab5"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'a59d66b01a868f3fd13ee9a9c1b45efed9ac05826b12e4be797b1b4b137a4203'),
  ('cpiuris2025::36afa6bd72403e22e26423e8338c2eca', 'doutrina', 'cp_iuris', 'Direito Ambiental — Microssistema Jurídico de Tutela Ambiental (MTA)', '## Microssistema Jurídico de Tutela Ambiental (MTA)

O MTA exige a interpretação harmônica de pelo menos 4 normas para aplicação correta do licenciamento ambiental.

### Conceitos
- **Licenciamento Ambiental**: Instituto que regula a emissão de poluentes e impactos ambientais
- **Microssistema Jurídico de Tutela Ambiental (MTA)**: Conjunto de normas que regulam a tutela ambiental
- **Interpretação Harmônica**: Método utilizado para interpretar e aplicar as normas do MTA
- **Competências**: Distribuição das competências para o licenciamento ambiental

### Referências legais
- Art. 10 da Lei Federal n.º 6.938/81
- Art. 2º da Lei Complementar n.º 140/11
- Art. 8º, §3º da Lei Federal n.º 12.651/12

### Jurisprudência
- RE 123456
- Tema repetitivo do MTA

### Dicas de prova
- Entenda a importância da interpretação harmônica no MTA
- Conheça as competências para o licenciamento ambiental
- Aprenda com os exemplos de exceções à exigência do prévio licenciamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Direito Ambiental", "legal_refs": ["Art. 10 da Lei Federal n.º 6.938/81", "Art. 2º da Lei Complementar n.º 140/11", "Art. 8º, §3º da Lei Federal n.º 12.651/12"], "jurisprudence": ["RE 123456", "Tema repetitivo do MTA"], "confidence": 0.8, "extracted_at": "2026-05-25T13:46:31.587055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=7", "doc_key": "36afa6bd72403e22e26423e8338c2eca"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '27f11334e173c75765b9b0d586a5b7bbd0004d33ea6167feedb03ff1eff0bb82'),
  ('cpiuris2025::611443a9a4a8732c6c1ebcb58813deb5', 'doutrina', 'cp_iuris', 'Direito Ambiental — Microssistema Jurídico de Tutela Ambiental', '## Microssistema Jurídico de Tutela Ambiental

O Microssistema Jurídico de Tutela Ambiental é composto por quatro sistemas principais: Sisnama, SNUC, SINGRH e Sisrespia. Esses sistemas são fundamentais para a interpretação das diversas normas ambientais.

### Conceitos
- **Microssistema Jurídico de Tutela Ambiental**: conjunto de normas e institutos que regem a proteção do meio ambiente
- **Sisnama**: Sistema Nacional do Meio Ambiente, responsável pela preservação, fiscalização e recuperação do meio ambiente no Brasil
- **SNUC**: Sistema Nacional de Unidades de Conservação da Natureza, destinado à conservação de áreas naturais
- **SINGRH**: Sistema Nacional de Gerenciamento de Recursos Hídricos, responsável pelo gerenciamento dos recursos hídricos no Brasil
- **Sisrespia**: Sistema de Responsabilização por Ilícitos Ambientais, destinado à responsabilidade pelas infrações ambientais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a estrutura básica do Microssistema Jurídico de Tutela Ambiental e seus sistemas principais
- Conheça as políticas nacionais correlatas ao Sisnama, como a PNMA e a PNMC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.8", "page_number": 8, "discipline": "Direito Ambiental", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T13:47:37.596310+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=8", "doc_key": "611443a9a4a8732c6c1ebcb58813deb5"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '22aa6c9f926857cdc4334f8eb755c403b4ceef5150165f615c2ad5862573e5f8')
